QT_ISI(16,{"2215":["(Khidhir berkata, \"Bukankah sudah kukatakan kepadamu, bahwa sesungguhnya kamu tidak akan dapat sabar bersamaku)\" hal ini sebagai teguran yang kedua bagimu di samping teguran yang pertama tadi, dalam hal ini alasanmu tidak dapat diterima.",[["۞ قَالَ","He said"],["أَلَمْ","Did not"],["أَقُل","I say"],["لَّكَ","to you"],["إِنَّكَ","that you"],["لَن","never"],["تَسْتَطِيعَ","will be able"],["مَعِىَ","with me"],["صَبْرًۭا","(to have) patience"]]],"2216":["Oleh sebab itu maka (berkatalah Musa, \"Jika aku bertanya kepadamu tentang sesuatu sesudah ini) sesudah kali ini (maka janganlah kamu menemani aku lagi) artinya janganlah kamu mengikuti aku lagi (sesungguhnya kamu telah cukup memberikan kepadaku) dapat dibaca Ladunii atau Ladunnii, artinya dari pihakku (udzur\") alasan agar aku berpisah denganmu.",[["قَالَ","He said"],["إِن","If"],["سَأَلْتُكَ","I ask you"],["عَن","about"],["شَىْءٍۭ","anything"],["بَعْدَهَا","after it"],["فَلَا","then (do) not"],["تُصَـٰحِبْنِى ۖ","keep me as a companion"],["قَدْ","Verily"],["بَلَغْتَ","you have reached"],["مِن","from me"],["لَّدُنِّى","from me"],["عُذْرًۭا","an excuse"]]],"2217":["(Maka keduanya berjalan; hingga tatkala keduanya sampai kepada penduduk suatu negeri) yaitu kota Inthakiyah (mereka meminta dijamu kepada penduduk negeri itu) keduanya meminta kepada mereka supaya memberi makan kepadanya sebagaimana layaknya tamu (tetapi penduduk negeri itu tidak mau menjamu mereka, kemudian keduanya mendapatkan dalam negeri itu dinding rumah) yang tingginya mencapai seratus hasta (yang hampir roboh) mengingat kemiringannya yang sangat (maka Khidhir menegakkan dinding itu) dengan tangannya sendiri (Musa berkata) kepadanya, (\"Jika kamu mau, niscaya kamu mengambil) menurut suatu qiraat dibaca Laittakhadzta (upah untuk itu)\" yakni persenan karena mereka tidak mau menjamu kita, sedangkan kita sangat membutuhkan makanan.",[["فَٱنطَلَقَا","So they set out"],["حَتَّىٰٓ","until"],["إِذَآ","when"],["أَتَيَآ","they came"],["أَهْلَ","(to the) people"],["قَرْيَةٍ","(of) a town"],["ٱسْتَطْعَمَآ","they asked for food"],["أَهْلَهَا","(from) its people"],["فَأَبَوْا۟","but they refused"],["أَن","to"],["يُضَيِّفُوهُمَا","offer them hospitality"],["فَوَجَدَا","Then they found"],["فِيهَا","in it"],["جِدَارًۭا","a wall"],["يُرِيدُ","(that) want(ed)"],["أَن","to"],["يَنقَضَّ","collapse"],["فَأَقَامَهُۥ ۖ","so he set it straight"],["قَالَ","He said"],["لَوْ","If"],["شِئْتَ","you wished"],["لَتَّخَذْتَ","surely you (could) have taken"],["عَلَيْهِ","for it"],["أَجْرًۭا","a payment"]]],"2218":["(Khidhir berkata) kepada Nabi Musa, (\"Inilah perpisahan) waktu perpisahan (antara aku dengan kamu). Lafal Baina dimudhafkan kepada hal yang tidak Muta'addi atau berbilang, pengulangan lafal Baina di sini diperbolehkan karena di antara keduanya terdapat huruf 'Athaf Wawu. (Aku akan memberitahukan kepadamu) sebelum perpisahanku denganmu (tujuan perbuatan-perbuatan yang kamu tidak sabar terhadapnya).",[["قَالَ","He said"],["هَـٰذَا","This"],["فِرَاقُ","(is) parting"],["بَيْنِى","between me"],["وَبَيْنِكَ ۚ","and between you"],["سَأُنَبِّئُكَ","I will inform you"],["بِتَأْوِيلِ","of (the) interpretation"],["مَا","(of) what"],["لَمْ","not"],["تَسْتَطِع","you were able"],["عَّلَيْهِ","on it"],["صَبْرًا","(to have) patience"]]],"2219":["(Adapun perahu itu adalah kepunyaan orang-orang miskin) yang jumlahnya ada sepuluh orang (yang bekerja di laut) dengan menyewakannya, mereka menjadikannya sebagai mata pencaharian (dan aku bertujuan merusakkan perahu itu, karena di hadapan mereka) jika mereka kembali, atau di hadapan mereka sekarang ini (ada seorang raja) kafir (yang mengambil tiap-tiap perahu) yang masih baik (secara ghashab) yakni dengan cara merampasnya. Lafal Ghashban dinashabkan karena menjadi Mashdar yang kedudukannya menjelaskan tentang cara pengambilan itu.",[["أَمَّا","As for"],["ٱلسَّفِينَةُ","the ship"],["فَكَانَتْ","it was"],["لِمَسَـٰكِينَ","of (the) poor people"],["يَعْمَلُونَ","working"],["فِى","in"],["ٱلْبَحْرِ","the sea"],["فَأَرَدتُّ","So I intended"],["أَنْ","that"],["أَعِيبَهَا","I cause defect (in) it"],["وَكَانَ","(as there) was"],["وَرَآءَهُم","after them"],["مَّلِكٌۭ","a king"],["يَأْخُذُ","who seized"],["كُلَّ","every"],["سَفِينَةٍ","ship"],["غَصْبًۭا","(by) force"]]],"2220":["(Adapun anak muda itu, kedua orang tuanya adalah orang-orang Mukmin, dan kami khawatir bahwa dia akan mendorong kedua orang tuanya itu kepada kesesatan dan kekafiran), karena sesungguhnya sebagaimana yang telah disebutkan di dalam hadis sahih Muslim, bahwa anak muda itu telah dicap oleh Allah menjadi orang kafir. Dan seandainya ia hidup niscaya dia akan mendorong kedua orang tuanya kepada kekafiran, disebabkan kecintaan keduanya kepadanya, hingga keduanya pasti akan mengikuti jejak anaknya.",[["وَأَمَّا","And as for"],["ٱلْغُلَـٰمُ","the boy"],["فَكَانَ","his parents were"],["أَبَوَاهُ","his parents were"],["مُؤْمِنَيْنِ","believers"],["فَخَشِينَآ","and we feared"],["أَن","that"],["يُرْهِقَهُمَا","he would overburden them"],["طُغْيَـٰنًۭا","(by) transgression"],["وَكُفْرًۭا","and disbelief"]]],"2221":["(Dan kami menghendaki, supaya menggantikan bagi kedua orang tuanya) dapat dibaca Yubaddilahuma atau Yubdilahuma (Rabbnya dengan anak lain yang lebih baik kesuciannya daripada anaknya itu) artinya lebih baik dan lebih bertakwa (dan lebih) daripada anaknya itu (dalam kasih sayangnya) dapat dibaca Ruhman atau Ruhuman, artinya berbakti kepada kedua orang tuanya. Ternyata sesudah itu Allah menggantikan bagi keduanya seorang anak perempuan yang kemudian dikawini oleh seorang nabi, dan dari hasil perkawinannya itu lahirlah seorang nabi. Pada akhirnya Allah memberikan petunjuk kepada suatu umat melalui nabi itu.",[["فَأَرَدْنَآ","So we intended"],["أَن","that"],["يُبْدِلَهُمَا","would change for them"],["رَبُّهُمَا","their Lord"],["خَيْرًۭا","a better"],["مِّنْهُ","than him"],["زَكَوٰةًۭ","(in) purity"],["وَأَقْرَبَ","and nearer"],["رُحْمًۭا","(in) affection"]]],"2222":["(Adapun dinding rumah itu adalah kepunyaan dua orang anak muda yang yatim di kota ini, dan di bawahnya ada harta benda simpanan) yakni harta yang terpendam berupa emas dan perak (bagi mereka berdua, sedangkan ayahnya adalah seorang yang saleh) maka dengan kesalehannya itu ia dapat memelihara kedua anaknya dan harta benda bagi keduanya (maka Rabbmu menghendaki agar mereka berdua sampai kepada kedewasaannya) sampai kepada usia dewasa (dan mengeluarkan simpanannya itu, sebagai rahmat dari Rabbmu). Lafal Rahmatan menjadi Maf'ul Lah, sedangkan 'Amilnya adalah lafal Araada (dan bukanlah aku melakukannya itu) yaitu semua hal yang telah disebutkan tadi, yakni melubangi perahu, membunuh anak muda dan mendirikan tembok yang hampir roboh (menurut kemauanku sendiri) berdasarkan keinginanku sendiri, tetapi hal itu kulakukan berdasarkan perintah dan ilham dari Allah. (Demikian itu adalah tujuan perbuatan-perbuatan yang kamu tidak dapat sabar terhadapnya)\" lafal Tasthi' menurut pendapat lain dibaca Isthaa'a dan Istathas'a artinya mampu. Di dalam ayat ini dan ayat-ayat sebelumnya terdapat berbagai macam ungkapan, yaitu terkadang memakai istilah Aradtu (aku menghendaki); terkadang memakai istilah Aradnaa (kami menghendaki), dan terkadang memakai istilah Araada Rabbuka (Rabbmu menghendaki). Hal ini dinamakan Jam'un Bainal Lughataini atau penganekaragaman ungkapan.",[["وَأَمَّا","And as for"],["ٱلْجِدَارُ","the wall"],["فَكَانَ","it was"],["لِغُلَـٰمَيْنِ","for two orphan boys"],["يَتِيمَيْنِ","for two orphan boys"],["فِى","in"],["ٱلْمَدِينَةِ","the town"],["وَكَانَ","and was"],["تَحْتَهُۥ","underneath it"],["كَنزٌۭ","a treasure"],["لَّهُمَا","for them"],["وَكَانَ","and was"],["أَبُوهُمَا","their father"],["صَـٰلِحًۭا","righteous"],["فَأَرَادَ","So intended"],["رَبُّكَ","your Lord"],["أَن","that"],["يَبْلُغَآ","they reach"],["أَشُدَّهُمَا","their maturity"],["وَيَسْتَخْرِجَا","and bring forth"],["كَنزَهُمَا","their treasure"],["رَحْمَةًۭ","(as) a mercy"],["مِّن","from"],["رَّبِّكَ ۚ","your Lord"],["وَمَا","And not"],["فَعَلْتُهُۥ","I did it"],["عَنْ","on"],["أَمْرِى ۚ","my (own) accord"],["ذَٰلِكَ","That"],["تَأْوِيلُ","(is the) interpretation"],["مَا","(of) what"],["لَمْ","not"],["تَسْطِع","you were able"],["عَّلَيْهِ","on it"],["صَبْرًۭا","(to have) patience"]]],"2223":["(Dan mereka akan bertanya kepadamu) yakni orang-orang yahudi (tentang Zulkarnain) yang namanya adalah Iskandar; dia bukan seorang Nabi (Katakanlah, \"Aku akan bacakan) aku akan kisahkan (kepada kalian mengenainya) tentang perihalnya (sebagai kisah)\".",[["وَيَسْـَٔلُونَكَ","And they ask you"],["عَن","about"],["ذِى","Dhul-qarnain"],["ٱلْقَرْنَيْنِ ۖ","Dhul-qarnain"],["قُلْ","Say"],["سَأَتْلُوا۟","I will recite"],["عَلَيْكُم","to you"],["مِّنْهُ","about him"],["ذِكْرًا","a remembrance"]]],"2224":["(Sesungguhnya Kami telah memberi kekuasaan kepadanya di muka bumi) dengan memudahkan perjalanan baginya di muka bumi ini (dan Kami telah memberikan kepadanya di dalam menghadapi segala sesuatu) yang ia perlukan (jalan untuk mencapainya) jalan yang dapat mengantarkannya kepada yang dikehendakinya.",[["إِنَّا","Indeed, We"],["مَكَّنَّا","[We] established"],["لَهُۥ","[for] him"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["وَءَاتَيْنَـٰهُ","and We gave him"],["مِن","of"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["سَبَبًۭا","a means"]]],"2225":["(Maka dia pun menempuh suatu jalan) yakni dia menempuh jalan ke arah Barat.",[["فَأَتْبَعَ","So he followed"],["سَبَبًا","a course"]]],"2226":["(Hingga apabila dia telah sampai ke tempat terbenamnya matahari) tempat matahari terbenam (dia melihat matahari terbenam di dalam laut yang berlumpur hitam) pengertian terbenamnya matahari di dalam laut hanyalah berdasarkan pandangan mata saja, karena sesungguhnya matahari jauh lebih besar daripada dunia atau bumi (dan dia mendapati di situ) di laut itu (segolongan umat) yang kafir (Kami berkata, \"Hai Zulkarnain!) dengan melalui ilham (Kamu boleh menyiksa) kaum itu dengan cara membunuh mereka (atau boleh berbuat kebaikan terhadap mereka)\" dengan hanya menawan mereka.",[["حَتَّىٰٓ","Until"],["إِذَا","when"],["بَلَغَ","he reached"],["مَغْرِبَ","(the) setting place"],["ٱلشَّمْسِ","(of) the sun"],["وَجَدَهَا","he found it"],["تَغْرُبُ","setting"],["فِى","in"],["عَيْنٍ","a spring"],["حَمِئَةٍۢ","(of) dark mud"],["وَوَجَدَ","and he found"],["عِندَهَا","near it"],["قَوْمًۭا ۗ","a community"],["قُلْنَا","We said"],["يَـٰذَا","O Dhul-qarnain"],["ٱلْقَرْنَيْنِ","O Dhul-qarnain"],["إِمَّآ","Either"],["أَن","[that]"],["تُعَذِّبَ","you punish"],["وَإِمَّآ","or"],["أَن","[that]"],["تَتَّخِذَ","you take"],["فِيهِمْ","[in] them"],["حُسْنًۭا","(with) goodness"]]],"2227":["(Berkata Zulkarnain, \"Adapun orang yang aniaya) yang melakukan kemusyrikan (maka kami kelak akan mengazabnya) yaitu kami akan membunuhnya (kemudian dia dikembalikan kepada Rabbnya, lalu Rabb mengazabnya dengan azab yang tiada taranya). Lafal Nukran artinya yang sangat keras, yakni azab yang sangat keras di neraka.",[["قَالَ","He said"],["أَمَّا","As for"],["مَن","(one) who"],["ظَلَمَ","wrongs"],["فَسَوْفَ","then soon"],["نُعَذِّبُهُۥ","we will punish him"],["ثُمَّ","Then"],["يُرَدُّ","he will be returned"],["إِلَىٰ","to"],["رَبِّهِۦ","his Lord"],["فَيُعَذِّبُهُۥ","and He will punish him"],["عَذَابًۭا","(with) a punishment"],["نُّكْرًۭا","terrible"]]],"2228":["(Adapun orang-orang yang beriman dan beramal saleh, maka baginya pahala yang terbaik) yakni surga; diidhafatkannya lafal Jazaa-an kepada lafal Al Husna mengandung makna penjelasan. Dan menurut qiraat yang lain lafal Jazaa-an dibaca Jazaa-u'; sehubungan dengan bacaan ini Imam Al-Farra' mengatakan bahwa dinashabkannya lafal Jazaa-an karena dianggap sebagai kalimat penafsir, maksudnya bila ditinjau dari segi nisbatnya (dan akan Kami titahkan kepadanya perintah yang mudah dari perintah-perintah Kami)\" maksudnya Kami akan memberikan perintah kepadanya dengan perintah yang mudah untuk ia laksanakan.",[["وَأَمَّا","But as for"],["مَنْ","(one) who"],["ءَامَنَ","believes"],["وَعَمِلَ","and does"],["صَـٰلِحًۭا","righteous (deeds)"],["فَلَهُۥ","then for him"],["جَزَآءً","(is) a reward"],["ٱلْحُسْنَىٰ ۖ","good"],["وَسَنَقُولُ","And we will speak"],["لَهُۥ","to him"],["مِنْ","from"],["أَمْرِنَا","our command"],["يُسْرًۭا","(with) ease"]]],"2229":["(Kemudian ia menempuh jalan yang lain) yaitu menuju ke arah Timur.",[["ثُمَّ","Then"],["أَتْبَعَ","he followed"],["سَبَبًا","(a) course"]]],"2230":["(Hingga apabila dia telah sampai ke tempat terbitnya matahari) tempat matahari terbit (dia mendapati matahari itu menyinari segolongan umat) mereka adalah bangsa Zunuj atau orang-orang Indian (yang Kami tidak menjadikan bagi mereka dari sinarnya) yaitu dari sinar matahari (sesuatu yang melindunginya) baik berupa pakaian atau pun atap-atap. Karena sesungguhnya tanah tempat mereka tinggal tidak dapat menopang bangunan, dan mereka hanya mempunyai tempat perlindungan berupa liang-liang, di tempat tersebut mereka masuk bila matahari terbit, dan bila matahari telah tinggi baru mereka keluar dari liang-liang itu.",[["حَتَّىٰٓ","Until"],["إِذَا","when"],["بَلَغَ","he reached"],["مَطْلِعَ","(the) rising place"],["ٱلشَّمْسِ","(of) the sun"],["وَجَدَهَا","and he found it"],["تَطْلُعُ","rising"],["عَلَىٰ","on"],["قَوْمٍۢ","a community"],["لَّمْ","not"],["نَجْعَل","We made"],["لَّهُم","for them"],["مِّن","against it"],["دُونِهَا","against it"],["سِتْرًۭا","any shelter"]]],"2231":["(Demikianlah) perkara itu sebagaimana yang telah Kami ceritakan. (Dan sesungguhnya Kami meliputi terhadap semua apa yang ada padanya) yaitu yang ada pada Zulkarnain berupa alat-alat persenjataan, balatentara dan lain sebagainya (dengan ilmu Kami) yakni Kami mengetahui semuanya.",[["كَذَٰلِكَ","Thus"],["وَقَدْ","And verily"],["أَحَطْنَا","We encompassed"],["بِمَا","of what"],["لَدَيْهِ","(was) with him"],["خُبْرًۭا","(of the) information"]]],"2232":["(Kemudian dia menempuh suatu jalan yang lain lagi).",[["ثُمَّ","Then"],["أَتْبَعَ","he followed"],["سَبَبًا","a course"]]],"2233":["(Hingga apabila dia telah sampai di antara dua buah bendungan) dibaca Saddaini atau Suddaini, dan sesudah kedua bendungan tersebut terdapat dua buah gunung, yaitu di salah satu wilayah negeri Turki. Bendungan raja Iskandar akan dibangun di antara kedua buah bukit itu, sebagaimana yang akan dijelaskan nanti (dia mendapati di hadapan kedua bendungan itu) yakni pada sebelah depan keduanya (suatu kaum yang hampir tidak mengerti pembicaraan) mereka tidak dapat memahami pembicaraan melainkan secara lambat sekali. Menurut qiraat yang lain lafal Yafqahuuna dibaca Yufqihuuna.",[["حَتَّىٰٓ","Until"],["إِذَا","when"],["بَلَغَ","he reached"],["بَيْنَ","between"],["ٱلسَّدَّيْنِ","the two mountains"],["وَجَدَ","he found"],["مِن","besides them"],["دُونِهِمَا","besides them"],["قَوْمًۭا","a community"],["لَّا","not"],["يَكَادُونَ","who would almost"],["يَفْقَهُونَ","understand"],["قَوْلًۭا","(his) speech"]]],"2234":["(Mereka berkata, \"Hai Zulkarnain! Sesungguhnya Yakjuj dan Makjuj itu) dikenal dengan nama Yakjuj dan Makjuj. Kedua nama tersebut merupakan nama 'Ajam bagi dua kabilah, dengan demikian maka I'rabnya tidak menerima tanwin (orang-orang yang membuat kerusakan di muka bumi) mereka gemar merampok dan membuat kerusakan di kala mereka keluar dari sarangnya menuju kami (maka dapatkah kami memberikan sesuatu pembayaran kepadamu) yakni upah berupa harta; dan menurut qiraat yang lain lafal Kharjan dibaca Kharaajan (supaya kamu membuat dinding antara kami dan mereka?)\" tembok penghalang hingga mereka tidak dapat mencapai kami.",[["قَالُوا۟","They said"],["يَـٰذَا","O Dhul-qarnain"],["ٱلْقَرْنَيْنِ","O Dhul-qarnain"],["إِنَّ","Indeed"],["يَأْجُوجَ","Yajuj"],["وَمَأْجُوجَ","and Majuj"],["مُفْسِدُونَ","(are) corrupters"],["فِى","in"],["ٱلْأَرْضِ","the land"],["فَهَلْ","So may"],["نَجْعَلُ","we make"],["لَكَ","for you"],["خَرْجًا","an expenditure"],["عَلَىٰٓ","[on]"],["أَن","that"],["تَجْعَلَ","you make"],["بَيْنَنَا","between us"],["وَبَيْنَهُمْ","and between them"],["سَدًّۭا","a barrier"]]],"2235":["(Zulkarnain berkata, \"Apa yang telah dikuasakan kepadaku) menurut qiraat yang lain lafal Makkannii dibaca Makkananii tanpa diidghamkan (oleh Rabbku terhadapnya) terhadap harta benda dan lain-lainnya (adalah lebih baik) daripada pembayaran kalian yang akan kalian berikan kepadaku, maka aku tidak memerlukannya lagi, dan aku akan membuat tembok penghalang buat kalian sebagai sumbangan suka rela dariku sendiri (maka tolonglah aku dengan kekuatan) apa saja yang aku perlukan dari kalian (agar aku membuatkan dinding antara kamu dan mereka) yakni tembok penghalang yang kuat dan tak dapat ditembus.",[["قَالَ","He said"],["مَا","What"],["مَكَّنِّى","has established me"],["فِيهِ","[in it]"],["رَبِّى","my Lord"],["خَيْرٌۭ","(is) better"],["فَأَعِينُونِى","but assist me"],["بِقُوَّةٍ","with strength"],["أَجْعَلْ","I will make"],["بَيْنَكُمْ","between you"],["وَبَيْنَهُمْ","and between them"],["رَدْمًا","a barrier"]]],"2236":["(Berilah aku potongan-potongan besi)\" sebesar bata kecil yang akan dijadikan sebagai bahan bangunan tembok lalu Zulkarnain membangun tembok penghalang itu daripadanya, dan dia memakai kayu dan batu bara yang dimasukkan di tengah-tengah tembok besi itu. (Sehingga apabila besi itu telah sama rata dengan kedua puncak gunung itu) lafal Shadafaini dapat dibaca Shudufaini dan Shudfaini, artinya sisi bagian puncak kedua bukit itu telah rata dengan bangunan, kemudian dibuatkannyalah peniup-peniup dan api sepanjang bangunan tembok itu (berkatalah Zulkarnain, \"Tiuplah api itu)\" lalu api itu mereka tiup (Hingga apabila besi itu menjadi) berubah bentuknya menjadi (merah) bagaikan api (dia pun berkata, \"Berilah aku tembaga yang mendidih agar kutuangkan ke atas besi panas itu)\" maksudnya tembaga yang dilebur. Lafal Aatuunii dan lafal Ufrigh merupakan kedua Fi'il yang saling berebutan terhadap Ma'mulnya, kemudian dibuanglah Ma'mul dari Fi'il yang pertama karena beramalnya Fi'il yang kedua. Selanjutnya tembaga yang sudah dilebur itu dituangkan ke atas besi yang merah membara, sehingga masuklah tembaga itu ke dalam partikel-partikel potongan besi, akhirnya kedua logam itu menyatu.",[["ءَاتُونِى","Bring me"],["زُبَرَ","sheets"],["ٱلْحَدِيدِ ۖ","(of) iron"],["حَتَّىٰٓ","until"],["إِذَا","when"],["سَاوَىٰ","he (had) leveled"],["بَيْنَ","between"],["ٱلصَّدَفَيْنِ","the two cliffs"],["قَالَ","he said"],["ٱنفُخُوا۟ ۖ","Blow"],["حَتَّىٰٓ","until"],["إِذَا","when"],["جَعَلَهُۥ","he made it"],["نَارًۭا","fire"],["قَالَ","he said"],["ءَاتُونِىٓ","Bring me"],["أُفْرِغْ","I pour"],["عَلَيْهِ","over it"],["قِطْرًۭا","molten copper"]]],"2237":["(Maka mereka tidak dapat) yakni Yakjuj dan Makjuj itu (mendakinya) memanjat tembok itu karena terlalu tinggi dan terlalu licin (dan mereka tidak dapat pula melubanginya) karena tembok itu terlalu kuat dan tebal sekali.",[["فَمَا","So not"],["ٱسْطَـٰعُوٓا۟","they were able"],["أَن","to"],["يَظْهَرُوهُ","scale it"],["وَمَا","and not"],["ٱسْتَطَـٰعُوا۟","they were able"],["لَهُۥ","in it"],["نَقْبًۭا","(to do) any penetration"]]],"2238":["(Dia berkata) yakni Zulkarnain, (\"Ini) tembok ini atau bendungan ini, atau kemampuan di dalam membangun ini (adalah rahmat dari Rabbku) merupakan nikmat-Nya, sebab tembok ini dapat mencegah Yakjuj dan Makjuj untuk keluar (maka apabila sudah datang janji Rabbku) yakni saat mereka dapat keluar, bila hari kiamat telah dekat. (Dia akan menjadikannya hancur luluh) rata dengan tanah (dan janji Rabbku itu) tentang keluarnya mereka dan peristiwa-peristiwa lainnya (adalah benar)\" pasti terjadi.",[["قَالَ","He said"],["هَـٰذَا","This"],["رَحْمَةٌۭ","(is) a mercy"],["مِّن","from"],["رَّبِّى ۖ","my Lord"],["فَإِذَا","But when"],["جَآءَ","comes"],["وَعْدُ","(the) Promise"],["رَبِّى","(of) my Lord"],["جَعَلَهُۥ","He will make it"],["دَكَّآءَ ۖ","level"],["وَكَانَ","And is"],["وَعْدُ","(the) Promise"],["رَبِّى","(of) my Lord"],["حَقًّۭا","true"]]],"2239":["Selanjutnya Allah berfirman: (Kami biarkan sebagian di antara mereka pada hari itu) pada hari mereka keluar dari tembok itu (bercampur aduk dengan sebagian yang lain) mereka bercampur aduk karena saking banyaknya jumlah mereka (kemudian ditiup lagi sangkakala) untuk membangkitkan mereka menjadi hidup kembali (lalu Kami kumpulkan mereka itu) yakni seluruh makhluk pada suatu tempat di hari kiamat (semuanya).",[["۞ وَتَرَكْنَا","And We (will) leave"],["بَعْضَهُمْ","some of them"],["يَوْمَئِذٍۢ","(on) that Day"],["يَمُوجُ","to surge"],["فِى","over"],["بَعْضٍۢ ۖ","others"],["وَنُفِخَ","and (will be) blown"],["فِى","in"],["ٱلصُّورِ","the trumpet"],["فَجَمَعْنَـٰهُمْ","then We (will) gather them"],["جَمْعًۭا","all together"]]],"2240":["(Dan Kami tampakkan) Kami dekatkan (Jahanam pada hari itu kepada orang-orang kafir dengan jelas).",[["وَعَرَضْنَا","And We (will) present"],["جَهَنَّمَ","Hell"],["يَوْمَئِذٍۢ","(on) that Day"],["لِّلْكَـٰفِرِينَ","to the disbelievers"],["عَرْضًا","(on) display"]]],"2241":["(Yaitu orang-orang yang matanya) menjadi Badal atau kata ganti dari lafal Al-Kaafiriina yang pada ayat sebelumnya (dalam keadaan tertutup dari memperhatikan ayat-yat-Ku) yakni Alquran, karenanya mereka buta tidak dapat mengambil petunjuk darinya (dan adalah mereka tidak sanggup mendengar) artinya, mereka tidak mampu untuk mendengarkan dari nabi apa yang telah dibacakan kepada mereka, karena mereka membencinya, oleh sebab itu mereka tidak beriman kepadanya.",[["ٱلَّذِينَ","Those"],["كَانَتْ","had been"],["أَعْيُنُهُمْ","their eyes"],["فِى","within"],["غِطَآءٍ","a cover"],["عَن","from"],["ذِكْرِى","My remembrance"],["وَكَانُوا۟","and were"],["لَا","not"],["يَسْتَطِيعُونَ","able"],["سَمْعًا","(to) hear"]]],"2242":["(Maka apakah orang-orang kafir menyangka bahwa mereka dapat mengambil hamba-hamba-Ku) yakni para Malaikat-Ku, Nabi 'Isa dan Nabi 'Uzair (menjadi penolong-penolong selain Aku?) yakni tuhan-tuhan yang dapat menolong mereka. Lafal Auliyaa-a ini menjadi Maf'ul Tsani daripada lafal Liyattakhidzuu, sedangkan Maf'ul Tsani daripada lafal Hasiba tidak disebutkan. Maksud ayat: Apakah mereka menyangka bahwa pengambilan mereka terhadap hal-hal yang telah disebutkan itu sebagai sesembahan mereka tidak membuat-Ku murka, dan Aku hanya berdiam diri tidak menghukum mereka? Tentu saja tidak. (Sesungguhnya Kami telah menyediakan neraka Jahanam bagi orang-orang kafir) yaitu bagi mereka dan bagi orang-orang kafir lainnya yang seperti mereka (sebagai tempat tinggal) maksudnya Jahanam itu telah disediakan buat mereka sebagaimana disediakannya tempat tinggal bagi tamu.",[["أَفَحَسِبَ","Do then think"],["ٱلَّذِينَ","those who"],["كَفَرُوٓا۟","disbelieve"],["أَن","that"],["يَتَّخِذُوا۟","they (can) take"],["عِبَادِى","My servants"],["مِن","besides Me"],["دُونِىٓ","besides Me"],["أَوْلِيَآءَ ۚ","(as) protectors"],["إِنَّآ","Indeed, We "],["أَعْتَدْنَا","We have prepared"],["جَهَنَّمَ","Hell"],["لِلْكَـٰفِرِينَ","for the disbelievers"],["نُزُلًۭا","(as) a lodging"]]],"2243":["(Katakanlah, \"Apakah akan Kami beritahukan kepada kalian tentang orang-orang yang paling merugi perbuatannya?)\" lafal A'maalan menjadi Tamyiz atau keterangan pembeda yang bentuknya sama dengan Mumayyaz. Kemudian Allah swt. menjelaskan siapa mereka yang merugi itu, melalui firman berikutnya.",[["قُلْ","Say"],["هَلْ","Shall"],["نُنَبِّئُكُم","We inform you"],["بِٱلْأَخْسَرِينَ","of the greatest losers"],["أَعْمَـٰلًا","(as to their) deeds"]]],"2244":["(Yaitu orang-orang yang telah sia-sia perbuatannya dalam kehidupan dunia ini) amal perbuatan mereka batil tidak diterima (sedangkan mereka menyangka) menduga (bahwa mereka berbuat sebaik-baiknya) yang pasti mereka akan menerima pahala karenanya.",[["ٱلَّذِينَ","Those "],["ضَلَّ","is lost"],["سَعْيُهُمْ","their effort"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["ٱلدُّنْيَا","(of) the world"],["وَهُمْ","while they"],["يَحْسَبُونَ","think"],["أَنَّهُمْ","that they"],["يُحْسِنُونَ","(were) acquiring good"],["صُنْعًا","(in) work"]]],"2245":["(Mereka itu orang-orang yang kafir terhadap ayat-ayat Rabb mereka) kafir terhadap bukti-bukti yang menunjukkan kepada keesaan-Nya, baik berupa Alquran maupun lain-lainnya (dan kafir terhadap perjumpaan dengan Dia) ingkar pada adanya hari berbangkit, perhitungan amal perbuatan, pahala dan siksaan (maka hapuslah amalan-amalan mereka) yakni ditolak (dan Kami tidak mengadakan suatu penilaian bagi amalan mereka pada hari kiamat) Kami tidak menganggap sama sekali amal perbuatan mereka.",[["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(are) the ones who"],["كَفَرُوا۟","disbelieve"],["بِـَٔايَـٰتِ","in the Verses"],["رَبِّهِمْ","(of) their Lord"],["وَلِقَآئِهِۦ","and the meeting (with) Him"],["فَحَبِطَتْ","So (are) vain"],["أَعْمَـٰلُهُمْ","their deeds"],["فَلَا","so not"],["نُقِيمُ","We will assign"],["لَهُمْ","for them"],["يَوْمَ","(on) the Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["وَزْنًۭا","any weight"]]],"2246":["(Demikianlah) yakni perihal yang telah Kusebutkan sehubungan dengan dihapusnya amal perbuatan mereka dan lain-lainnya. Lafal Dzaalika menjadi Mubtada sedangkan Khabarnya ialah: (balasan mereka itu neraka Jahanam, disebabkan kekafiran mereka dan disebabkan mereka menjadikan ayat-ayat-Ku dan Rasul-rasul-Ku sebagai olok-olok) keduanya menjadi ejekan dan olokan mereka.",[["ذَٰلِكَ","That"],["جَزَآؤُهُمْ","(is) their recompense "],["جَهَنَّمُ","Hell "],["بِمَا","because"],["كَفَرُوا۟","they disbelieved"],["وَٱتَّخَذُوٓا۟","and took"],["ءَايَـٰتِى","My Verses"],["وَرُسُلِى","and My Messengers"],["هُزُوًا","(in) ridicule"]]],"2247":["(Sesungguhnya orang-orang yang beriman dan beramal saleh, bagi mereka) menurut ilmu Allah (adalah surga Firdaus) yaitu bagian tengah dan bagian teratas daripada surga. Idhafah di sini memberikan pengertian Bayan atau menjelaskan (menjadi tempat tinggal) tempat menetap mereka.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["وَعَمِلُوا۟","and did"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["كَانَتْ","for them will be"],["لَهُمْ","for them will be"],["جَنَّـٰتُ","Gardens"],["ٱلْفِرْدَوْسِ","(of) the Paradise"],["نُزُلًا","(as) a lodging"]]],"2248":["(Mereka kekal di dalamnya, mereka tidak ingin) tidak meminta (berpindah daripadanya) pindah ke tempat yang lain.",[["خَـٰلِدِينَ","Abiding forever"],["فِيهَا","in it"],["لَا","Not"],["يَبْغُونَ","they will desire"],["عَنْهَا","from it"],["حِوَلًۭا","any transfer"]]],"2249":["(Katakanlah, \"Kalau sekiranya lautan) airnya (menjadi tinta) yaitu sarana untuk menulis (untuk menulis kalimat-kalimat Rabbku) yang menunjukkan kepada kebijaksanaan-kebijaksanaan dan keajaiban-keajaiban ciptaan-Nya, seumpamanya hal itu ditulis (sungguh habislah lautan itu) untuk menulisnya (sebelum habis) dapat dibaca Tanfadza atau Yanfadza, yakni sebelum habis ditulis (kalimat-kalimat Rabbku, meskipun Kami datangkan sebanyak itu) lautan yang sama (sebagai tambahan tintanya.\") niscaya tambahan ini pun akan habis pula, sedangkan kalimat-kalimat Rabbku masih belum habis ditulis. Lafal Madadan dinashabkan karena menjadi Tamyiz.",[["قُل","Say"],["لَّوْ","If"],["كَانَ","were"],["ٱلْبَحْرُ","the sea"],["مِدَادًۭا","ink"],["لِّكَلِمَـٰتِ","for (the) Words"],["رَبِّى","(of) my Lord"],["لَنَفِدَ","surely (would be) exhausted"],["ٱلْبَحْرُ","the sea"],["قَبْلَ","before"],["أَن","[that]"],["تَنفَدَ","(were) exhausted"],["كَلِمَـٰتُ","(the) Words"],["رَبِّى","(of) my Lord"],["وَلَوْ","even if"],["جِئْنَا","We brought"],["بِمِثْلِهِۦ","(the) like (of) it"],["مَدَدًۭا","(as) a supplement"]]],"2250":["(Katakanlah, \"Sesungguhnya aku ini hanyalah seorang manusia) anak Adam (seperti kalian, yang diwahyukan kepadaku, 'Bahwa sesungguhnya Rabb kalian itu adalah Tuhan Yang Esa.') huruf Anna di sini Maktufah atau dicegah untuk beramal oleh sebab adanya Ma, sedangkan huruf Ma masih tetap status Mashdarnya. Maksudnya; yang diwahyukan kepadaku mengenai keesaan Tuhan (Barang siapa mengharap) bercita-cita (perjumpaan dengan Rabbnya) setelah dibangkitkan dan menerima pembalasan (maka hendaklah ia mengerjakan amal yang saleh dan janganlah ia mempersekutukan di dalam beribadah kepada Rabbnya) yakni sewaktu ia beribadah kepada-Nya, seumpamanya ia hanya ingin pamer (dengan seorang pun\").",[["قُلْ","Say"],["إِنَّمَآ","Only"],["أَنَا۠","I"],["بَشَرٌۭ","(am) a man"],["مِّثْلُكُمْ","like you"],["يُوحَىٰٓ","Has been revealed"],["إِلَىَّ","to me"],["أَنَّمَآ","that"],["إِلَـٰهُكُمْ","your God"],["إِلَـٰهٌۭ","(is) God"],["وَٰحِدٌۭ ۖ","One"],["فَمَن","So whoever"],["كَانَ","is"],["يَرْجُوا۟","hoping"],["لِقَآءَ","(for the) meeting"],["رَبِّهِۦ","(with) his Lord"],["فَلْيَعْمَلْ","let him do"],["عَمَلًۭا","deeds"],["صَـٰلِحًۭا","righteous"],["وَلَا","and not"],["يُشْرِكْ","associate"],["بِعِبَادَةِ","in (the) worship"],["رَبِّهِۦٓ","(of) his Lord"],["أَحَدًۢا","anyone"]]],"2251":["(Kaf Ha Ya 'Ain Shad) hanya Allah yang mengetahui maksudnya.",[["كٓهيعٓصٓ","Kaaf Ha Ya Ain Sad"]]],"2252":["Ini adalah (penjelasan tentang rahmat Rabb kamu kepada hamba-Nya) lafal 'abdahu menjadi Maf'ul dari Rahmah (Zakaria) sebagai penjelasan dari kata 'hamba' tadi.",[["ذِكْرُ","(A) mention"],["رَحْمَتِ","(of the) Mercy"],["رَبِّكَ","(of) your Lord"],["عَبْدَهُۥ","(to) His servant"],["زَكَرِيَّآ","Zakariya"]]],"2253":["(Yaitu tatkala) lafal Idz berta'alluq kepada lafal Rahmah (ia berdoa kepada Rabbnya dengan seruan) yang mengandung doa (yang lembut) dengan suara yang pelan-pelan di tengah malam, karena berdoa di tengah malam itu lebih cepat untuk dikabulkan.",[["إِذْ","When"],["نَادَىٰ","he called"],["رَبَّهُۥ","(to) his Lord"],["نِدَآءً","a call "],["خَفِيًّۭا","secret"]]],"2254":["(Ia berkata, \"Ya Rabbku! Sesungguhnya telah lemah) menjadi lemah (tulang-tulangku) semuanya (dan kepala ini telah dipenuhi) (oleh uban) lafal Syaiban menjadi Tamyiz yang dipindahkan dari Fa'ilnya, maksudnya uban telah merata di rambut kepalanya sebagaimana meratanya nyala api pada kayu dan sesungguhnya aku bermaksud berdoa kepada-Mu (dan aku belum pernah dengan doaku kepada-Mu) (merasa kecewa, ya Rabbku!) artinya, merasa dikecewakan di masa-masa lalu; maka janganlah Engkau kecewakan aku di masa mendatang.",[["قَالَ","He said"],["رَبِّ","My Lord"],["إِنِّى","Indeed, [I]"],["وَهَنَ","(have) weakened"],["ٱلْعَظْمُ","my bones"],["مِنِّى","my bones"],["وَٱشْتَعَلَ","and flared"],["ٱلرَّأْسُ","(my) head"],["شَيْبًۭا","(with) white"],["وَلَمْ","and not"],["أَكُنۢ","I have been"],["بِدُعَآئِكَ","in (my) supplication (to) You"],["رَبِّ","my Lord"],["شَقِيًّۭا","unblessed"]]],"2255":["(Dan sesungguhnya aku khawatir terhadap mawaliku) yakni orang-orang dekat hubungan familinya denganku seperti anak-anak paman (sepeninggalku) yakni sesudah aku meninggal dunia, aku khawatir mereka akan menyia-nyiakan agama sebagaimana yang telah kusaksikan sendiri apa yang terjadi di kalangan orang-orang Bani Israel, yaitu mereka berani mengubah agamanya (sedangkan istriku adalah seorang yang mandul) tidak beranak (maka anugerahilah aku dari sisi Engkau) (seorang putra) anak lelaki.",[["وَإِنِّى","And indeed, I"],["خِفْتُ","[I] fear"],["ٱلْمَوَٰلِىَ","the successors"],["مِن","after me"],["وَرَآءِى","after me"],["وَكَانَتِ","and is"],["ٱمْرَأَتِى","my wife"],["عَاقِرًۭا","barren"],["فَهَبْ","So give"],["لِى","[to] me"],["مِن","from"],["لَّدُنكَ","Yourself"],["وَلِيًّۭا","an heir"]]],"2256":["(Yang akan mewarisi aku) kalau dibaca Jazm berarti lafal Yaritsni menjadi jawab dari Fi'il Amar, dan kalau dibaca Rafa' yaitu Yaritsuni berarti menjadi kata sifat dari lafal Waliyyan (dan mewarisi) dapat dibaca Yaritsu atau Yarits (sebagian keluarga Ya'qub) kakekku dalam hal ilmu dan kenabian (dan jadikanlah ia, ya Rabbku, seorang yang diridai)\" di sisi Engkau.",[["يَرِثُنِى","Who will inherit me"],["وَيَرِثُ","and inherit"],["مِنْ","from"],["ءَالِ","(the) family"],["يَعْقُوبَ ۖ","(of) Yaqub"],["وَٱجْعَلْهُ","And make him"],["رَبِّ","my Lord"],["رَضِيًّۭا","pleasing"]]],"2257":["(Hai Zakaria, sesungguhnya Kami memberi kabar gembira kepadamu akan beroleh seorang anak) yang akan menjadi waris, sebagaimana yang kamu minta (yang namanya Yahya, yang sebelumnya Kami tidak pernah menciptakan orang yang serupa dengan dia) dalam hal namanya, yakni seseorang yang diberi nama Yahya.",[["يَـٰزَكَرِيَّآ","O Zakariya"],["إِنَّا","Indeed, We"],["نُبَشِّرُكَ","[We] give you glad tidings"],["بِغُلَـٰمٍ","of a boy"],["ٱسْمُهُۥ","his name"],["يَحْيَىٰ","(will be) Yahya"],["لَمْ","not"],["نَجْعَل","We (have) assigned"],["لَّهُۥ","[for] it"],["مِن","before"],["قَبْلُ","before"],["سَمِيًّۭا","(this) name"]]],"2258":["(Zakaria berkata, \"Ya Rabbku! Bagaimana) mana mungkin (akan ada anak bagiku, padahal istriku adalah seorang yang mandul dan aku sendiri sesungguhnya sudah mencapai umur yang sangat tua)\" lafal 'itiyyan berasal dari lafal 'Ataa artinya Yabisa atau kering, maksudnya ia telah mencapai umur seratus dua puluh tahun, dan istrinya telah mencapai umur sembilan puluh delapan tahun. Kata 'Itiyyun pada asalnya adalah 'Ituwwun. Kemudian huruf Ta dikasrahkan untuk meringankan pengucapannya lalu jadilah 'Itiwwun. Selanjutnya huruf Wawu yang pertama diganti menjadi huruf Ya demi penyesuaian dengan harakat Kasrah sebelumnya, dan huruf Wawu yang kedua diganti pula dengan huruf Ya supaya huruf Ya yang pertama dapat diidgamkan atau dimasukkan kepadanya, sehingga jadilah 'Itiyyun.",[["قَالَ","He said"],["رَبِّ","My Lord"],["أَنَّىٰ","How"],["يَكُونُ","can"],["لِى","I have"],["غُلَـٰمٌۭ","a boy"],["وَكَانَتِ","while is"],["ٱمْرَأَتِى","my wife"],["عَاقِرًۭا","barren"],["وَقَدْ","and indeed"],["بَلَغْتُ","I have reached"],["مِنَ","of"],["ٱلْكِبَرِ","the old age"],["عِتِيًّۭا","extreme"]]],"2259":["(Allah berfirman) perkaranya memang (\"Demikianlah.\") cara menciptakan seorang anak lelaki dari kamu berdua (Rabbmu berfirman, \"Hal itu adalah mudah bagi-Ku) yaitu dengan memberikan kekuatan bersetubuh kepadamu, kemudian menjadikan rahim istrimu dapat menerima spermamu (dan sesungguhnya telah Aku ciptakan kamu sebelum itu, padahal kamu belum ada sama sekali)\" di waktu kamu belum diciptakan. Untuk menampilkan kekuasaan Allah yang mampu menciptakan hal yang besar ini, maka Dia memberikan ilham suatu pertanyaan, supaya pertanyaan itu kelak dijawab dengan hal yang membuktikan kekuasaan-Nya yang maha besar itu. Tatkala Zakaria merasa rindu akan kedatangan berita gembira kelahiran seorang putra itu.",[["قَالَ","He said"],["كَذَٰلِكَ","Thus"],["قَالَ","said"],["رَبُّكَ","your Lord"],["هُوَ","'It"],["عَلَىَّ","(is) easy for Me"],["هَيِّنٌۭ","(is) easy for Me"],["وَقَدْ","and certainly"],["خَلَقْتُكَ","I (have) created you"],["مِن","before"],["قَبْلُ","before"],["وَلَمْ","while not"],["تَكُ","you were"],["شَيْـًۭٔا","anything.'"]]],"2260":["(Zakaria berkata, \"Ya Rabbku! Berilah aku suatu tanda)\" pertanda yang menunjukkan istriku mulai mengandung (Allah berfirman, \"Tanda bagimu) yang menunjukkan hal itu (adalah bahwa kamu tidak boleh bercakap-cakap dengan manusia) mencegah dirimu untuk tidak berbicara dengan mereka selain dari berzikir kepada Allah (selama tiga malam) yakni tiga hari tiga malam (padahal kamu sehat)\" lafal Sawiyyan berkedudukan menjadi Hal dari Fa'il lafal Takallama, maksudnya ia tidak berbicara dengan mereka tanpa sebab.",[["قَالَ","He said"],["رَبِّ","My Lord"],["ٱجْعَل","Make"],["لِّىٓ","for me"],["ءَايَةًۭ ۚ","a sign"],["قَالَ","He said"],["ءَايَتُكَ","Your sign"],["أَلَّا","(is) that not"],["تُكَلِّمَ","you will speak"],["ٱلنَّاسَ","(to) the people"],["ثَلَـٰثَ","(for) three"],["لَيَالٍۢ","nights"],["سَوِيًّۭا","sound"]]],"2261":["(Maka ia keluar dari mihrab menuju kaumnya) yakni dari mesjid, sedang orang-orang menunggu pintu mesjid itu dibuka, karena mereka hendak melakukan salat di dalamnya, sesuai dengan kebiasaan mereka menurut perintah Zakaria (lalu ia memberi isyarat) (kepada mereka; hendaklah kalian bertasbih) maksudnya melakukan salat (di waktu pagi dan petang) yakni pada permulaan siang hari dan akhirnya, sebagaimana biasa. Setelah Nabi Zakaria mencegah dirinya untuk bercakap-cakap dengan mereka, pada saat itu diketahui bahwa istrinya mengandung Yahya. Selang dua tahun kemudian setelah Yahya lahir, Allah berfirman kepadanya.",[["فَخَرَجَ","Then he came out"],["عَلَىٰ","to"],["قَوْمِهِۦ","his people"],["مِنَ","from"],["ٱلْمِحْرَابِ","the prayer chamber"],["فَأَوْحَىٰٓ","and he signaled"],["إِلَيْهِمْ","to them"],["أَن","to"],["سَبِّحُوا۟","glorify (Allah)"],["بُكْرَةًۭ","(in) the morning"],["وَعَشِيًّۭا","and (in) the evening"]]],"2262":["(Hai Yahya! Ambillah Kitab itu) yakni kitab Taurat (dengan sungguh-sungguh) secara sungguh-sungguh. (Dan Kami berikan kepadanya hikmah) kenabian (selagi ia masih kanak-kanak) sewaktu berumur tiga tahun.",[["يَـٰيَحْيَىٰ","O Yahya"],["خُذِ","Hold"],["ٱلْكِتَـٰبَ","the Scripture"],["بِقُوَّةٍۢ ۖ","with strength"],["وَءَاتَيْنَـٰهُ","And We gave him"],["ٱلْحُكْمَ","[the] wisdom"],["صَبِيًّۭا","(when he was) a child"]]],"2263":["(Dan rasa belas kasihan yang mendalam) terhadap manusia (dari sisi Kami) dari haribaan Kami (dan zakat) yakni senang bersedekah kepada mereka (Dan ia adalah seorang yang bertakwa) menurut suatu riwayat disebutkan, bahwa Nabi Yahya tidak pernah melakukan suatu dosa pun, dan hatinya tidak pernah mempunyai keinginan untuk melakukannya.",[["وَحَنَانًۭا","And affection"],["مِّن","from"],["لَّدُنَّا","Us"],["وَزَكَوٰةًۭ ۖ","and purity"],["وَكَانَ","and he was"],["تَقِيًّۭا","righteous"]]],"2264":["(Dan seorang yang berbakti kepada kedua orang tuanya) yaitu selalu berbuat baik kepada keduanya (dan bukanlah ia orang yang sombong) takabur (lagi bukan pula ia orang yang durhaka) terhadap Rabbnya.",[["وَبَرًّۢا","And dutiful"],["بِوَٰلِدَيْهِ","to his parents"],["وَلَمْ","and not"],["يَكُن","he was"],["جَبَّارًا","a tyrant"],["عَصِيًّۭا","disobedient"]]],"2265":["(Kesejahteraan) dari Kami (terlimpahkan kepadanya pada hari ia dilahirkan dan pada hari ia meninggal dan pada hari ia dibangkitkan hidup kembali) di saat-saat yang mengerikan yakni hari kiamat. Pada hari itu belum pernah ada pemandangan yang sengeri itu, maka Nabi Yahya selamat daripadanya.",[["وَسَلَـٰمٌ","And peace be"],["عَلَيْهِ","upon him"],["يَوْمَ","(the) day"],["وُلِدَ","he was born"],["وَيَوْمَ","and (the) day"],["يَمُوتُ","he dies"],["وَيَوْمَ","and (the) day"],["يُبْعَثُ","he will be raised"],["حَيًّۭا","alive"]]],"2266":["(Dan ceritakanlah di dalam Kitab) yakni Alquran (tentang Maryam) kisahnya (yaitu ketika) (ia menjauhkan diri dari keluarganya ke suatu tempat di sebelah Timur) Maryam mengasingkan diri di suatu tempat di sebelah Timur rumahnya.",[["وَٱذْكُرْ","And mention"],["فِى","in"],["ٱلْكِتَـٰبِ","the Book"],["مَرْيَمَ","Maryam"],["إِذِ","when"],["ٱنتَبَذَتْ","she withdrew"],["مِنْ","from"],["أَهْلِهَا","her family"],["مَكَانًۭا","(to) a place"],["شَرْقِيًّۭا","eastern"]]],"2267":["(Maka ia mengadakan tabir yang menutupinya dari mereka) Maryam membuat tabir untuk melindungi dirinya sewaktu ia membuka penutup kepalanya, atau membuka pakaiannya atau menyucikan dirinya dari haid (lalu Kami mengutus kepadanya roh Kami) yakni malaikat Jibril (maka ia menjelma di hadapannya) sesudah Maryam memakai pakaiannya (dalam bentuk manusia yang sempurna) manusia sesungguhnya.",[["فَٱتَّخَذَتْ","Then she took"],["مِن","from them"],["دُونِهِمْ","from them"],["حِجَابًۭا","a screen"],["فَأَرْسَلْنَآ","Then We sent"],["إِلَيْهَا","to her"],["رُوحَنَا","Our Spirit"],["فَتَمَثَّلَ","then he assumed for her the likeness"],["لَهَا","then he assumed for her the likeness"],["بَشَرًۭا","(of) a man"],["سَوِيًّۭا","well-proportioned"]]],"2268":["(Maryam berkata, \"Sesungguhnya aku berlindung daripadamu kepada Tuhan Yang Maha Pemurah, jika kamu seorang yang bertakwa.\") kamu pasti dapat menahan diri daripadaku dengan bacaan Ta'awwudzku ini.",[["قَالَتْ","She said"],["إِنِّىٓ","Indeed, I"],["أَعُوذُ","[I] seek refuge"],["بِٱلرَّحْمَـٰنِ","with the Most Gracious"],["مِنكَ","from you"],["إِن","if"],["كُنتَ","you are"],["تَقِيًّۭا","God fearing"]]],"2269":["(Ia berkata, \"Sesungguhnya aku ini adalah utusan Rabbmu, untuk memberimu seorang anak laki-laki yang suci)\" yang kelak menjadi nabi.",[["قَالَ","He said"],["إِنَّمَآ","Only"],["أَنَا۠","I am"],["رَسُولُ","a Messenger"],["رَبِّكِ","(from) your Lord"],["لِأَهَبَ","that I (may) bestow"],["لَكِ","on you"],["غُلَـٰمًۭا","a son"],["زَكِيًّۭا","pure"]]],"2270":["(Maryam berkata, \"Bagaimana akan ada bagiku seorang anak laki-laki, sedangkan tidak pernah seorang manusia pun menyentuhku) yakni mengawiniku (dan aku bukan pula seorang pezina!)\" seorang pelacur.",[["قَالَتْ","She said"],["أَنَّىٰ","How"],["يَكُونُ","can be"],["لِى","for me"],["غُلَـٰمٌۭ","a son"],["وَلَمْ","when not"],["يَمْسَسْنِى","has touched me"],["بَشَرٌۭ","a man"],["وَلَمْ","and not"],["أَكُ","I am"],["بَغِيًّۭا","unchaste"]]],"2271":["(Jibril berkata,) perkaranya memang (\"Demikianlah.\") yaitu akan diciptakan bagimu seorang anak laki-laki tanpa ayah (Rabbmu berfirman, \"Hal itu adalah mudah bagi-Ku) yaitu dengan cara Aku memerintahkan kepada malaikat Jibril supaya meniup dirimu, lalu karena itu kamu mengandung. Mengingat kalimat yang telah disebutkan mengandung makna illat atau kausalita, maka kalimat berikutnya di'athafkan kepadanya, yaitu (dan agar dapat Kami menjadikannya suatu tanda bagi manusia) yang menunjukkan akan kekuasaan-Ku (dan sebagai rahmat dari Kami) bagi orang-orang yang beriman kepadanya (dan hal itu adalah) penciptaan itu merupakan (suatu perkara yang sudah diputuskan)\" di dalam ilmu-Ku, malaikat Jibril meniupkan nafasnya ke dalam baju kurung Maryam, seketika itu juga Maryam merasakan di dalam kandungannya terdapat seorang bayi.",[["قَالَ","He said"],["كَذَٰلِكِ","Thus"],["قَالَ","said"],["رَبُّكِ","your Lord"],["هُوَ","'It"],["عَلَىَّ","(is) for Me"],["هَيِّنٌۭ ۖ","easy"],["وَلِنَجْعَلَهُۥٓ","and so that We will make him"],["ءَايَةًۭ","a sign"],["لِّلنَّاسِ","for the mankind"],["وَرَحْمَةًۭ","and a Mercy"],["مِّنَّا ۚ","from Us"],["وَكَانَ","And (it) is"],["أَمْرًۭا","a matter"],["مَّقْضِيًّۭا","decreed.'"]]],"2272":["(Maka Maryam mengandungnya, lalu ia mengasingkan diri) menjauhkan diri (dengan membawa kandungannya ke tempat yang jauh) jauh dari keluarganya.",[["۞ فَحَمَلَتْهُ","So she conceived him"],["فَٱنتَبَذَتْ","and she withdrew"],["بِهِۦ","with him"],["مَكَانًۭا","(to) a place"],["قَصِيًّۭا","remote"]]],"2273":["(Maka sewaktu datang kepadanya) ketika ia mengalami (rasa sakit akan melahirkan) yaitu rasa mulas karena akan melahirkan (-terpaksa ia bersandar- pada pangkal pohon kurma) yakni menyandarkan diri padanya, lalu ia melahirkan. Perlu diketahui bahwa sejak peniupan malaikat Jibril hingga melahirkan hanya memakan waktu sesaat saja (dia berkata, \"Aduhai alangkah baiknya aku) lafal Ya di sini menunjukkan makna Tanbih atau ungkapan kekecewaan (mati sebelum ini) yakni sebelum perkara ini (dan aku menjadi barang yang tidak berarti, lagi dilupakan)\" sebagai sesuatu yang tiada artinya, tidak dikenal dan tidak disebut-sebut.",[["فَأَجَآءَهَا","Then drove her"],["ٱلْمَخَاضُ","the pains of childbirth"],["إِلَىٰ","to"],["جِذْعِ","(the) trunk"],["ٱلنَّخْلَةِ","(of) the date-palm"],["قَالَتْ","She said"],["يَـٰلَيْتَنِى","O! I wish"],["مِتُّ","I (had) died"],["قَبْلَ","before"],["هَـٰذَا","this"],["وَكُنتُ","and I was"],["نَسْيًۭا","(in) oblivion"],["مَّنسِيًّۭا","forgotten"]]],"2274":["(Maka Jibril menyerunya dari tempat yang lebih rendah,) pada saat itu malaikat Jibril berada di tempat yang lebih rendah dari tempat Maryam (\"Janganlah kamu bersedih hati, sesungguhnya Rabbmu telah menjadikan anak sungai di bawahmu\") yaitu sebuah sungai yang dahulunya kering kini berair kembali, berkat kekuasaan Allah.",[["فَنَادَىٰهَا","So cried to her"],["مِن","from"],["تَحْتِهَآ","beneath her"],["أَلَّا","That (do) not"],["تَحْزَنِى","grieve"],["قَدْ","verily"],["جَعَلَ","(has) placed"],["رَبُّكِ","your Lord"],["تَحْتَكِ","beneath you"],["سَرِيًّۭا","a stream"]]],"2275":["(Dan goyanglah pangkal pohon kurma itu ke arahmu) yang pada saat itu kering. Huruf Ba dalam lafal Bijidz'i adalah Zaidah atau tambahan (niscaya pohon itu akan menggugurkan) asal kata Tusaaqith adalah Tatasaaqath kemudian Ta yang kedua diganti menjadi Sin, selanjutnya diidgamkan pada Sin yang kedua. Menurut qiraat yang lain tetap dibaca seperti lafal asalnya (buah kurma kepadamu) lafal Ruthaban adalah Tamyiz (yang masak-masak) lafal Janiyyan menjadi sifat dari lafal Ruthaban.",[["وَهُزِّىٓ","And shake"],["إِلَيْكِ","towards you"],["بِجِذْعِ","(the) trunk"],["ٱلنَّخْلَةِ","(of) the date-palm"],["تُسَـٰقِطْ","it will drop"],["عَلَيْكِ","upon you"],["رُطَبًۭا","fresh dates"],["جَنِيًّۭا","ripe"]]],"2276":["(Maka makanlah) dari buah kurma yang masak itu (dan minumlah) dari air sungai kecil itu (serta bersenang hatilah kamu) dengan anakmu itu. Lafal 'Ainan berfungsi sebagai Tamyiz yang dipindahkan dari Fa'ilnya, maksudnya selamat bersenang hati dengan anakmu itu. Atau dengan kata lain, kamu menjadi tenang dengan adanya anakmu itu sehingga kamu tidak memikirkan hal-hal yang lain. (Jika) lafal Immaa ini pada asalnya terdiri dari In Syarthiyah dan Ma Zaidah yang kemudian diidgamkan menjadi satu hingga menjadi Immaa (kamu melihat) dan lafal Tarayinna terbuang huruf Lam Fi'il dan 'Ain Fi'ilnya, kemudian harakat 'Ain Fi'ilnya dipindahkan pada huruf Ra, selanjutnya Ya Dhamir dikasrahkan karena bertemu dua sukun, sehingga jadilah Tarayinna (seorang manusia) kemudian ia menanyakan kepadamu tentang anakmu itu (maka katakanlah, \"Sesungguhnya aku bernazar shaum untuk Tuhan Yang Maha Pemurah) dengan menahan diri untuk tidak berbicara, baik mengenai perihal anaknya atau orang-orang lainnya, hal ini terbukti dengan perkataan selanjutnya (maka aku tidak akan berkata dengan seorang manusia pun pada hari ini)\" sesudah kejadian ini.",[["فَكُلِى","So eat"],["وَٱشْرَبِى","and drink"],["وَقَرِّى","and cool"],["عَيْنًۭا ۖ","(your) eyes"],["فَإِمَّا","And if"],["تَرَيِنَّ","you see"],["مِنَ","from"],["ٱلْبَشَرِ","human being"],["أَحَدًۭا","anyone"],["فَقُولِىٓ","then say"],["إِنِّى","Indeed, I"],["نَذَرْتُ","[I] have vowed"],["لِلرَّحْمَـٰنِ","to the Most Gracious"],["صَوْمًۭا","a fast"],["فَلَنْ","so not"],["أُكَلِّمَ","I will speak"],["ٱلْيَوْمَ","today"],["إِنسِيًّۭا","(to any) human being"]]],"2277":["(Maka Maryam membawa anak itu kepada kaumnya dengan menggendongnya) lafal Tahmiluhu menjadi Hal atau kata keterangan keadaan. Sehingga kaumnya melihat anak itu (Kaumnya berkata, \"Hai Maryam! Sesungguhnya kamu telah melakukan sesuatu yang amat mungkar) suatu dosa yang sangat besar karena kamu memperoleh anak tanpa ayah.",[["فَأَتَتْ","Then she came"],["بِهِۦ","with him"],["قَوْمَهَا","(to) her people"],["تَحْمِلُهُۥ ۖ","carrying him"],["قَالُوا۟","They said"],["يَـٰمَرْيَمُ","O Maryam"],["لَقَدْ","Certainly"],["جِئْتِ","you (have) brought"],["شَيْـًۭٔا","an amazing thing"],["فَرِيًّۭا","an amazing thing"]]],"2278":["(Hai saudara perempuan Harun!) dia adalah seorang lelaki yang saleh, hal ini berarti Maryam pun serupa dengannya dalam hal memelihara kehormatan (Ayahmu sekali-kali bukanlah seorang yang buruk) bukan seorang pezina (dan ibumu sekali-kali bukanlah seorang pelacur)\" bukan pula seorang pezina, maka dari manakah anak ini.",[["يَـٰٓأُخْتَ","O sister"],["هَـٰرُونَ","(of) Harun"],["مَا","Not"],["كَانَ","was"],["أَبُوكِ","your father"],["ٱمْرَأَ","an evil man"],["سَوْءٍۢ","an evil man"],["وَمَا","and not"],["كَانَتْ","was"],["أُمُّكِ","your mother"],["بَغِيًّۭا","unchaste"]]],"2279":["(Maka Maryam mengisyaratkan) kepada kaumnya (-seraya menunjuk- kepada anaknya) maksudnya supaya mereka bertanya kepada anaknya. (Mereka berkata, \"Bagaimana kami akan berbicara dengan anak) yang masih (kecil berada dalam ayunan?)\".",[["فَأَشَارَتْ","Then she pointed"],["إِلَيْهِ ۖ","to him"],["قَالُوا۟","They said"],["كَيْفَ","How"],["نُكَلِّمُ","(can) we speak"],["مَن","(to one) who"],["كَانَ","is"],["فِى","in"],["ٱلْمَهْدِ","the cradle"],["صَبِيًّۭا","a child"]]],"2280":["(Isa berkata, \"Sesungguhnya aku ini hamba Allah, Dia memberiku Alkitab) yakni kitab Injil (dan Dia menjadikan aku seorang nabi).",[["قَالَ","He said"],["إِنِّى","Indeed, I am"],["عَبْدُ","a slave"],["ٱللَّهِ","(of) Allah"],["ءَاتَىٰنِىَ","He gave me"],["ٱلْكِتَـٰبَ","the Scripture"],["وَجَعَلَنِى","and made me"],["نَبِيًّۭا","a Prophet"]]],"2281":["(Dan Dia menjadikan aku seorang yang diberkati di mana saja aku berada) maksudnya Dia menjadikan diriku orang yang banyak memberi manfaat kepada manusia. Ungkapan ini merupakan berita tentang kedudukan yang telah dipastikan baginya (dan Dia memerintahkan kepadaku mendirikan salat dan menunaikan zakat) Allah memerintahkan kepadaku untuk melakukan kedua hal tersebut (selama aku hidup).",[["وَجَعَلَنِى","And He (has) made me"],["مُبَارَكًا","blessed"],["أَيْنَ","wherever"],["مَا","wherever"],["كُنتُ","I am"],["وَأَوْصَـٰنِى","and has enjoined (on) me"],["بِٱلصَّلَوٰةِ","[of] the prayer"],["وَٱلزَّكَوٰةِ","and zakah"],["مَا","as long as I am"],["دُمْتُ","as long as I am"],["حَيًّۭا","alive"]]],"2282":["(Dan berbakti kepada ibuku) lafal Barran dinashabkan oleh lafal Ja'alani yang keberadaannya diperkirakan, maksudnya, Dia menjadikan aku sebagai orang yang berbakti kepada ibuku (dan Dia tidak menjadikan aku seorang yang sombong) orang yang merasa tinggi diri (lagi celaka) yang durhaka kepada Rabbnya.",[["وَبَرًّۢا","And dutiful"],["بِوَٰلِدَتِى","to my mother"],["وَلَمْ","and not"],["يَجْعَلْنِى","He (has) made me"],["جَبَّارًۭا","insolent"],["شَقِيًّۭا","unblessed"]]],"2283":["(Dan kesejahteraan) dari Allah (semoga dilimpahkan kepadaku, pada hari aku dilahirkan, pada hari aku meninggal dan pada hari aku dibangkitkan hidup kembali)\" hal ini telah dikatakan pada kisah yang lalu, yaitu dalam doa Nabi Yahya.",[["وَٱلسَّلَـٰمُ","And peace (be)"],["عَلَىَّ","on me"],["يَوْمَ","(the) day"],["وُلِدتُّ","I was born"],["وَيَوْمَ","and (the) day"],["أَمُوتُ","I will die"],["وَيَوْمَ","and (the) Day"],["أُبْعَثُ","I will be raised"],["حَيًّۭا","alive"]]],"2284":["(Itulah Isa putra Maryam, yang mengatakan perkataan yang benar) jika lafal Alqaul dibaca Rafa', berarti menjadi Khabar dari Mubtada yang diperkirakan keberadaannya, maksudnya, perkataan Isa bin Maryam adalah perkataan yang benar. Kalau dibaca Nashab berarti ada lafal Qultu yang diperkirakan keberadaannya sebelumnya, maksudnya Aku mengatakan perkataan yang benar (yang mereka berbantah-bantahan tentang kebenarannya) lafal Yamtaruuna berasal dari kata Al Miryah; mereka meragukan kebenarannya, mereka adalah orang-orang Nasrani; mereka mengatakan perkataan yang dusta, yaitu, \"Sesungguhnya Isa itu adalah anak Allah\".",[["ذَٰلِكَ","That"],["عِيسَى","(was) Isa"],["ٱبْنُ","(the) son"],["مَرْيَمَ ۚ","(of) Maryam"],["قَوْلَ","a statement"],["ٱلْحَقِّ","(of) truth"],["ٱلَّذِى","that which"],["فِيهِ","about it"],["يَمْتَرُونَ","they dispute"]]],"2285":["(Tidak layak bagi Allah mempunyai anak, Maha Suci Dia) dari hal tersebut. (Apabila Dia telah menetapkan sesuatu) yakni, Dia berkehendak untuk menciptakannya (maka Dia hanya berkata kepadanya, \"Jadilah\" maka jadilah dia) kalau dibaca Rafa' yaitu Yakuunu berarti ada lafal Huwa atau dia yang diperkirakan keberadaannya, kalau dibaca Nashab yaitu berarti dengan memperkirakan lafal An sebelumnya. Oleh sebab itu maka Nabi Isa diciptakan tanpa ayah.",[["مَا","Not"],["كَانَ","(it) is"],["لِلَّهِ","for Allah"],["أَن","that"],["يَتَّخِذَ","He should take"],["مِن","any son"],["وَلَدٍۢ ۖ","any son"],["سُبْحَـٰنَهُۥٓ ۚ","Glory be to Him"],["إِذَا","When"],["قَضَىٰٓ","He decrees"],["أَمْرًۭا","a matter"],["فَإِنَّمَا","then only"],["يَقُولُ","He says"],["لَهُۥ","to it"],["كُن","Be"],["فَيَكُونُ","and it is"]]],"2286":["(Sesungguhnya Allah adalah Rabbku dan Rabb kalian, maka sembahlah Dia) jika dibaca Anna maka dengan memperkirakan keberadaan lafal Udzkur, maksudnya: Ingatlah, sesungguhnya Allah dan seterusnya. Jika dibaca Kasrah yaitu Inna maka dengan memperkirakan keberadaan lafal Qul sebelumnya, maksudnya: Katakanlah, sesungguhnya Allah; hal ini dibuktikan oleh firman lainnya, yaitu: Aku tidak pernah mengatakan kepada mereka melainkan apa yang Engkau perintahkan kepadaku untuk mengatakannya, yaitu, \"Sembahlah Allah, Rabbku dan Rabb kalian.\" (Q.S. Al-Maidah, 117). (ini) hal yang telah disebutkan tadi (adalah jalan) penuntun (yang lurus) yang dapat mengantarkan ke surga.",[["وَإِنَّ","And indeed"],["ٱللَّهَ","Allah"],["رَبِّى","(is) my Lord"],["وَرَبُّكُمْ","and your Lord"],["فَٱعْبُدُوهُ ۚ","so worship Him"],["هَـٰذَا","This"],["صِرَٰطٌۭ","(is) a path"],["مُّسْتَقِيمٌۭ","straight"]]],"2287":["(Maka berselisihlah golongan-golongan yang ada di antara mereka) yakni orang-orang Nasrani, yaitu sehubungan dengan perihal Isa, apakah dia anak Allah, atau tuhan di samping Allah, ataukah tuhan yang ketiga. (Maka kecelakaanlah) azab yang sangat keras (bagi orang-orang kafir) disebabkan apa yang telah disebutkan tadi dan hal-hal lainnya (pada waktu menyaksikan hari yang besar) yakni kehadiran mereka di hari kiamat dan kengerian-kengerian yang terjadi pada waktu itu.",[["فَٱخْتَلَفَ","But differed"],["ٱلْأَحْزَابُ","the sects"],["مِنۢ","from among them"],["بَيْنِهِمْ ۖ","from among them"],["فَوَيْلٌۭ","so woe"],["لِّلَّذِينَ","to those who"],["كَفَرُوا۟","disbelieve"],["مِن","from"],["مَّشْهَدِ","(the) witnessing"],["يَوْمٍ","(of) a Day"],["عَظِيمٍ","great"]]],"2288":["(Alangkah terangnya pendengaran mereka dan alangkah tajamnya penglihatan mereka) kedua lafal ini merupakan Shighat atau ungkapan rasa takjub, maknanya sama dengan lafal Ma Asma'ahum dan Ma Absharahum (pada hari mereka datang kepada Kami) di akhirat kelak. (Tetapi orang-orang yang zalim) menurut ungkapan meletakkan isim Zhahir pada tempat isim Mudhmar' (pada hari ini) yakni di dunia (berada dalam kesesatan yang nyata) nyata kesesatannya, disebabkan mereka tuli tidak mau mendengarkan perkara yang hak, dan mereka buta tidak mau melihat yang benar. Maksudnya, hai orang yang diajak bicara sepatutnya kamu merasa takjub dan heran terhadap pendengaran dan penglihatan mereka di akhirat, sesudah di dunia mereka tuli dan buta.",[["أَسْمِعْ","How they will hear"],["بِهِمْ","How they will hear"],["وَأَبْصِرْ","and how (they will) see"],["يَوْمَ","(the) Day"],["يَأْتُونَنَا ۖ","they will come to Us"],["لَـٰكِنِ","but"],["ٱلظَّـٰلِمُونَ","the wrongdoers"],["ٱلْيَوْمَ","today"],["فِى","(are) in"],["ضَلَـٰلٍۢ","error"],["مُّبِينٍۢ","clear"]]],"2289":["(Dan berilah mereka peringatan) takut-takutilah hai Muhammad, orang-orang kafir Mekah itu (tentang hari penyesalan) yaitu hari kiamat sewaktu orang yang berbuat jahat merasa menyesal sekali karena tidak mau berbuat kebaikan di dunia (yaitu ketika segala perkara telah diputus) bagi mereka di hari kiamat, yaitu mereka harus menerima azab (Dan mereka) di dunia (dalam kelalaian) tentang hari penyesalan itu (dan mereka tidak pula beriman) kepada adanya hari penyesalan itu.",[["وَأَنذِرْهُمْ","And warn them"],["يَوْمَ","(of the) Day"],["ٱلْحَسْرَةِ","(of) the Regret"],["إِذْ","when"],["قُضِىَ","has been decided"],["ٱلْأَمْرُ","the matter"],["وَهُمْ","And they"],["فِى","(are) in"],["غَفْلَةٍۢ","heedlessness"],["وَهُمْ","and they"],["لَا","(do) not"],["يُؤْمِنُونَ","believe"]]],"2290":["(Sesungguhnya Kami) lafal Nahnu berfungsi sebagai Taukid atau kata pengukuh (mewarisi bumi dan semua orang-orang yang ada di dalamnya) baik yang berakal maupun yang lainnya, yaitu dengan membinasakan mereka (dan hanya kepada Kamilah mereka dikembalikan) pada hari kiamat untuk menerima pembalasan.",[["إِنَّا","Indeed, We"],["نَحْنُ","[We]"],["نَرِثُ","[We] will inherit"],["ٱلْأَرْضَ","the earth"],["وَمَنْ","and whoever"],["عَلَيْهَا","(is) on it"],["وَإِلَيْنَا","and to Us"],["يُرْجَعُونَ","they will be returned"]]],"2291":["(Dan ceritakanlah) kepada mereka (tentang Ibrahim di dalam Al-Kitab ini) Alquran, yaitu tentang kisahnya. (Sesungguhnya ia adalah seorang yang sangat membenarkan) seorang yang sangat jujur dalam keimanannya (lagi seorang nabi) hal ini dijelaskan dalam ayat selanjutnya.",[["وَٱذْكُرْ","And mention"],["فِى","in"],["ٱلْكِتَـٰبِ","the Book"],["إِبْرَٰهِيمَ ۚ","Ibrahim"],["إِنَّهُۥ","Indeed, he"],["كَانَ","was"],["صِدِّيقًۭا","a man of truth"],["نَّبِيًّا","a Prophet"]]],"2292":["(Yaitu ketika ia berkata kepada bapaknya) yang bernama Azar, (\"Wahai bapakku!) huruf Ta pada lafal Abati ganti dari Ya Idhafah, karena keduanya tidak dapat dikumpulkan menjadi satu. Azar adalah penyembah berhala (Mengapa kamu menyembah sesuatu yang tidak mendengar, tidak melihat dan tidak dapat menolong kamu) tidak dapat mencukupimu (sedikit pun?) baik berupa manfaat maupun bahaya.",[["إِذْ","When"],["قَالَ","he said"],["لِأَبِيهِ","to his father"],["يَـٰٓأَبَتِ","O my father"],["لِمَ","Why"],["تَعْبُدُ","(do) you worship"],["مَا","that which"],["لَا","not"],["يَسْمَعُ","hears"],["وَلَا","and not"],["يُبْصِرُ","sees"],["وَلَا","and not"],["يُغْنِى","benefits"],["عَنكَ","[to] you"],["شَيْـًۭٔا","(in) anything"]]],"2293":["(Wahai bapakku! Sesungguhnya telah datang kepadaku sebagian ilmu pengetahuan yang tidak datang kepadamu, maka ikutilah aku, niscaya aku akan menunjukkan kepadamu jalan) penuntun (yang lurus) tidak menyimpang dari kebenaran.",[["يَـٰٓأَبَتِ","O my father"],["إِنِّى","Indeed, [I]"],["قَدْ","verily"],["جَآءَنِى","(has) come to me"],["مِنَ","of"],["ٱلْعِلْمِ","the knowledge"],["مَا","what"],["لَمْ","not"],["يَأْتِكَ","came to you"],["فَٱتَّبِعْنِىٓ","so follow me"],["أَهْدِكَ","I will guide you"],["صِرَٰطًۭا","(to) the path"],["سَوِيًّۭا","even"]]],"2294":["(Wahai bapakku! Janganlah kamu menyembah setan) dengan ketaatanmu kepadanya, yaitu menyembah berhala. (Sesungguhnya setan itu durhaka kepada Tuhan Yang Maha Pemurah) yang banyak durhakanya.",[["يَـٰٓأَبَتِ","O my father"],["لَا","(Do) not"],["تَعْبُدِ","worship"],["ٱلشَّيْطَـٰنَ ۖ","the Shaitaan"],["إِنَّ","Indeed"],["ٱلشَّيْطَـٰنَ","the Shaitaan"],["كَانَ","is"],["لِلرَّحْمَـٰنِ","to the Most Gracious"],["عَصِيًّۭا","disobedient"]]],"2295":["(Wahai bapakku! Sesungguhnya aku khawatir bahwa kamu akan ditimpa azab dari Tuhan Yang Maha Pemurah) jika kamu tidak bertobat (maka kamu menjadi kawan bagi setan)\" yaitu menjadi penolong dan temannya di neraka.",[["يَـٰٓأَبَتِ","O my father"],["إِنِّىٓ","Indeed, I"],["أَخَافُ","[I] fear"],["أَن","that"],["يَمَسَّكَ","will touch you"],["عَذَابٌۭ","a punishment"],["مِّنَ","from"],["ٱلرَّحْمَـٰنِ","the Most Gracious"],["فَتَكُونَ","so you would be"],["لِلشَّيْطَـٰنِ","to the Shaitaan"],["وَلِيًّۭا","a friend"]]],"2296":["(Bapaknya berkata, \"Bencikah kamu kepada tuhan-tuhanku, hai Ibrahim?) maka sebab itu kamu mencelanya. (Jika kamu tidak berhenti) mencaci makinya (maka niscaya kamu akan kurajam) dengan batu, atau dengan perkataan yang jelek, maka hati-hatilah kamu terhadapku (dan tinggalkanlah aku buat waktu yang lama)\" yakni dalam masa yang lama.",[["قَالَ","He said"],["أَرَاغِبٌ","Do you hate"],["أَنتَ","Do you hate"],["عَنْ","(from)"],["ءَالِهَتِى","my gods"],["يَـٰٓإِبْرَٰهِيمُ ۖ","O Ibrahim"],["لَئِن","Surely, if"],["لَّمْ","not"],["تَنتَهِ","you desist"],["لَأَرْجُمَنَّكَ ۖ","surely, I will stone you"],["وَٱهْجُرْنِى","so leave me"],["مَلِيًّۭا","(for) a prolonged time"]]],"2297":["(Ibrahim berkata, \"Semoga keselamatan dilimpahkan kepadamu) dariku, maksudnya aku tidak akan lagi menimpakan hal-hal yang tidak diinginkan kepadamu (aku akan memintakan ampun bagimu kepada Rabbku. Sesungguhnya Dia sangat baik kepadaku\") lafal Hafiyyan berasal dari lafal Hafaa, yang artinya sangat baik hingga Dia selalu memperkenankan doaku. Kemudian Nabi Ibrahim memenuhi janjinya itu, sebagaimana disebutkan di dalam surah Asy-Syu'ara, yaitu, \".. dan ampunilah bapakku...\" (Q.S. Asy-Syu'ara, 86). Hal ini dilakukan oleh Nabi Ibrahim sebelum jelas baginya bahwa bapaknya itu adalah musuh Allah, sebagaimana yang telah disebutkan di dalam surah At-Taubah.",[["قَالَ","He said"],["سَلَـٰمٌ","Peace (be)"],["عَلَيْكَ ۖ","on you"],["سَأَسْتَغْفِرُ","I will ask forgiveness"],["لَكَ","for you"],["رَبِّىٓ ۖ","(from) my Lord"],["إِنَّهُۥ","Indeed, He"],["كَانَ","is"],["بِى","to me"],["حَفِيًّۭا","Ever Gracious"]]],"2298":["(Dan aku akan menjauhkan diri daripada kalian dan daripada apa yang kalian seru) yang kalian sembah (selain Allah, dan aku akan berdoa) yakni aku akan menyembah (kepada Rabbku, mudah-mudahan aku dengan berdoa kepada Rabbku) dengan beribadah kepada-Nya (tidak akan kecewa)\" sebagaimana kalian kecewa karena menyembah berhala-berhala itu.",[["وَأَعْتَزِلُكُمْ","And I will leave you"],["وَمَا","and what"],["تَدْعُونَ","you invoke"],["مِن","besides"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["وَأَدْعُوا۟","and I will invoke"],["رَبِّى","my Lord"],["عَسَىٰٓ","May be"],["أَلَّآ","that not"],["أَكُونَ","I will be"],["بِدُعَآءِ","in invocation"],["رَبِّى","(to) my Lord"],["شَقِيًّۭا","unblessed"]]],"2299":["(Ketika Ibrahim sudah menjauhkan diri dari mereka dan dari apa yang mereka sembah selain Allah) dia pergi ke tanah suci (Kami anugerahkan kepadanya) dua orang putra yang menjadi penghibur hatinya (Ishak dan Yakub. Dan masing-masingnya) di antara keduanya (Kami angkat menjadi nabi).",[["فَلَمَّا","So when"],["ٱعْتَزَلَهُمْ","he left them"],["وَمَا","and what"],["يَعْبُدُونَ","they worshipped"],["مِن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["وَهَبْنَا","[and] We bestowed"],["لَهُۥٓ","[to] him"],["إِسْحَـٰقَ","Isaac"],["وَيَعْقُوبَ ۖ","and Yaqub"],["وَكُلًّۭا","and each (of them)"],["جَعَلْنَا","We made"],["نَبِيًّۭا","a Prophet"]]],"2300":["(Dan Kami anugerahkan kepada mereka) bertiga Nabi Ibrahim, Nabi Ishak, dan Nabi Yakub (sebagian dari rahmat Kami,) berupa harta benda dan anak-anak (dan Kami jadikan mereka buah tutur yang baik lagi tinggi) mereka selalu menjadi pujian dan sanjungan semua pemeluk agama.",[["وَوَهَبْنَا","And We bestowed"],["لَهُم","to them"],["مِّن","of"],["رَّحْمَتِنَا","Our Mercy"],["وَجَعَلْنَا","and We made"],["لَهُمْ","for them"],["لِسَانَ","a truthful mention"],["صِدْقٍ","a truthful mention"],["عَلِيًّۭا","high"]]],"2301":["(Dan ceritakanlah kisah Musa di dalam Alquran ini. Sesungguhnya ia adalah seorang yang mukhlis) dapat dibaca Mukhlishan dan Mukhlashan, artinya seorang yang ikhlas di dalam beribadah dan Allah membersihkan dirinya dari hal-hal yang kotor (di samping ia adalah seorang rasul dan nabi).",[["وَٱذْكُرْ","And mention"],["فِى","in"],["ٱلْكِتَـٰبِ","the Book"],["مُوسَىٰٓ ۚ","Musa"],["إِنَّهُۥ","Indeed, he"],["كَانَ","was"],["مُخْلَصًۭا","chosen"],["وَكَانَ","and was"],["رَسُولًۭا","a Messenger"],["نَّبِيًّۭا","a Prophet"]]],"2302":["(Dan Kami telah memanggilnya) melalui firman-Nya, \"Hai Musa! Sesungguhnya Aku adalah Allah...\" (Q.S. Al-Qashash, 30). (dari arah Thur) nama sebuah bukit (sebelah kanan) yakni dari sebelah kanan Nabi Musa ketika ia baru datang dari negeri Madyan (dan Kami telah mendekatkannya kepada Kami waktu dia munajat) bermunajat, yaitu Allah memperdengarkan Kalam-Nya kepadanya.",[["وَنَـٰدَيْنَـٰهُ","And We called him"],["مِن","from"],["جَانِبِ","(the) side"],["ٱلطُّورِ","(of) the Mount"],["ٱلْأَيْمَنِ","the right"],["وَقَرَّبْنَـٰهُ","and brought him near"],["نَجِيًّۭا","(for) conversation"]]],"2303":["(Dan Kami telah menganugerahkan kepadanya sebagian rahmat Kami) sebagian dari nikmat Kami (yaitu saudaranya, Harun) Lafal Haruna menjadi Badal atau Athaf Bayan (menjadi seorang nabi) lafal Nabiyyan ini menjadi Hal atau kata keterangan yang dimaksud daripada pemberian itu; hal ini merupakan pengabulan dari doa Nabi Musa sendiri yang meminta kepada Allah, supaya Dia mengangkat saudara tuanya menjadi rasul pula.",[["وَوَهَبْنَا","And We bestowed"],["لَهُۥ","[to] him"],["مِن","from"],["رَّحْمَتِنَآ","Our Mercy"],["أَخَاهُ","his brother"],["هَـٰرُونَ","Harun"],["نَبِيًّۭا","a Prophet"]]],"2304":["(Dan ceritakanlah kisah Ismail di dalam Alquran. Sesungguhnya ia adalah seorang yang benar janjinya) sekali-kali ia tidak menjanjikan sesuatu melainkan ia memenuhinya. Disebutkan bahwa ia pernah menunggu seseorang yang telah berjanji kepadanya, selama tiga hari atau satu tahun, sehingga orang yang berjanji itu datang kepadanya di tempat yang dijanjikan itu, dan ternyata Nabi Ismail masih menunggu di tempat itu (dan dia adalah seorang rasul) untuk kabilah Jurhum (dan nabi).",[["وَٱذْكُرْ","And mention"],["فِى","in"],["ٱلْكِتَـٰبِ","the Book"],["إِسْمَـٰعِيلَ ۚ","Ishmael"],["إِنَّهُۥ","Indeed, he"],["كَانَ","was"],["صَادِقَ","true"],["ٱلْوَعْدِ","(to his) promise"],["وَكَانَ","and was"],["رَسُولًۭا","a Messenger "],["نَّبِيًّۭا","a Prophet"]]],"2305":["(Dan ia menyuruh ahlinya) yakni kaumnya (untuk salat dan menunaikan zakat dan ia adalah seorang yang diridai di sisi Rabbnya) lafal Mardhiyyan asalnya Mardhuwwun, kedua huruf Wawunya diganti menjadi Ya. Selanjutnya harakat Dhammah Dhadhnya diganti menjadi Kasrah, akhirnya jadi Mardhiyyun, oleh karena kedudukannya menjadi Khabar Kaana maka bacaannya menjadi Mardhiyyan.",[["وَكَانَ","And he used"],["يَأْمُرُ","(to) enjoin"],["أَهْلَهُۥ","(on) his people"],["بِٱلصَّلَوٰةِ","the prayer"],["وَٱلزَّكَوٰةِ","and zakah"],["وَكَانَ","and was"],["عِندَ","near"],["رَبِّهِۦ","his Lord"],["مَرْضِيًّۭا","pleasing"]]],"2306":["(Dan ceritakanlah kisah Idris di dalam Alquran) Nabi Idris adalah buyut Nabi Ibrahim atau ayah kakek Nabi Nuh (Sesungguhnya ia adalah seorang yang sangat membenarkan dan seorang nabi).",[["وَٱذْكُرْ","And mention"],["فِى","in"],["ٱلْكِتَـٰبِ","the Book"],["إِدْرِيسَ ۚ","Idris"],["إِنَّهُۥ","Indeed, he"],["كَانَ","was"],["صِدِّيقًۭا","truthful"],["نَّبِيًّۭا","a Prophet"]]],"2307":["(Dan Kami telah mengangkatnya ke martabat yang tinggi) ia masih tetap hidup sampai sekarang bertempat di langit keempat atau keenam, atau ketujuh atau berada di dalam surga. Ia dimasukkan ke dalam surga setelah terlebih dahulu mencicipi rasanya mati lalu dihidupkan kembali, setelah itu ia tidak mau keluar lagi dari dalam surga.",[["وَرَفَعْنَـٰهُ","And We raised him"],["مَكَانًا","(to) a position"],["عَلِيًّا","high"]]],"2308":["(Mereka itu) kalimat ini menjadi Mubtada (adalah orang-orang yang telah diberi nikmat oleh Allah) menjadi sifat daripada lafal Ulaaika (yaitu para nabi) menjadi Bayan atau keterangan dari lafal Ulaaika yang kedudukannya sama dengan sifat. Lafal-lafal yang sesudahnya sampai kepada Jumlah Syarat menjadi sifat dari lafal Nabiyyiin. Maka firman-Nya (dari keturunan Adam) yakni Nabi Idris (dan dari orang-orang yang Kami muatkan bersama Nuh) di dalam bahteranya, maksudnya adalah Nabi Ibrahim yaitu cucu daripada anak Nabi Nuh yang bernama Sam (dan dari keturunan Ibrahim) yakni Nabi Ismail dan Nabi Ishaq serta Nabi Yakub, (dan) dari keturunan (Israel) yang dimaksud adalah Nabi Musa, Nabi Harun, Nabi Zakaria, Nabi Yahya, dan Nabi Isa (dan dari orang-orang yang telah Kami beri petunjuk dan telah Kami pilih) daripada mereka. Khabar dari lafal Ulaaika yang di permulaan ayat tadi ialah (\"Apabila dibacakan kepada mereka ayat-ayat Allah Yang Maha Pemurah, maka mereka menyungkur dengan bersujud dan menangis\"). Lafal Sujjadan dan Bukiyyan adalah bentuk jamak dari lafal Saajidun dan Baakin. Maksudnya jadilah kalian orang-orang seperti mereka. Asal kata Bukiyyun adalah Bukiwyun, kemudian huruf Wawunya diganti menjadi Ya dan harakat Dhammahnya diganti pula dengan Kasrah, sehingga menjadi Buhiyyun.",[["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(were) the ones whom"],["أَنْعَمَ","Allah bestowed favor"],["ٱللَّهُ","Allah bestowed favor"],["عَلَيْهِم","upon them"],["مِّنَ","from (among)"],["ٱلنَّبِيِّـۧنَ","the Prophets"],["مِن","of"],["ذُرِّيَّةِ","(the) offspring"],["ءَادَمَ","(of) Adam"],["وَمِمَّنْ","and of those"],["حَمَلْنَا","We carried"],["مَعَ","with"],["نُوحٍۢ","Nuh"],["وَمِن","and of"],["ذُرِّيَّةِ","(the) offspring"],["إِبْرَٰهِيمَ","(of) Ibrahim"],["وَإِسْرَٰٓءِيلَ","and Israel"],["وَمِمَّنْ","and of (those) whom"],["هَدَيْنَا","We guided"],["وَٱجْتَبَيْنَآ ۚ","and We chose"],["إِذَا","When"],["تُتْلَىٰ","were recited"],["عَلَيْهِمْ","to them"],["ءَايَـٰتُ","(the) Verses"],["ٱلرَّحْمَـٰنِ","(of) the Most Gracious"],["خَرُّوا۟","they fell"],["سُجَّدًۭا","prostrating"],["وَبُكِيًّۭا ۩","and weeping"]]],"2309":["(Maka datanglah sesudah mereka pengganti yang jelek yang menyia-nyiakan salat) dengan cara meninggalkannya seperti orang-orang Yahudi dan Nasrani (dan memperturutkan hawa nafsunya) gemar melakukan perbuatan-perbuatan maksiat (maka mereka kelak akan menemui kesesatan) ghayya adalah nama sebuah lembah di neraka Jahanam, mereka akan dijerumuskan ke dalamnya.",[["۞ فَخَلَفَ","Then succeeded"],["مِنۢ","after them"],["بَعْدِهِمْ","after them"],["خَلْفٌ","successors"],["أَضَاعُوا۟","who neglected"],["ٱلصَّلَوٰةَ","the prayer"],["وَٱتَّبَعُوا۟","and they followed"],["ٱلشَّهَوَٰتِ ۖ","the lusts"],["فَسَوْفَ","so soon"],["يَلْقَوْنَ","they will meet"],["غَيًّا","evil"]]],"2310":["(Kecuali) yakni berbeda halnya dengan (orang yang bertobat, beriman dan beramal saleh, mereka itu akan masuk surga dan mereka tidak dianiaya) tidak dirugikan (barang sedikit pun) dari pahala mereka.",[["إِلَّا","Except"],["مَن","(one) who"],["تَابَ","repented"],["وَءَامَنَ","and believed"],["وَعَمِلَ","and did"],["صَـٰلِحًۭا","good (deeds)"],["فَأُو۟لَـٰٓئِكَ","Then those"],["يَدْخُلُونَ","will enter"],["ٱلْجَنَّةَ","Paradise"],["وَلَا","and not"],["يُظْلَمُونَ","they will be wronged"],["شَيْـًۭٔا","(in) anything"]]],"2311":["(Yaitu surga Adn) menjadi tempat tinggal mereka. Lafaz 'Adn menjadi Badal daripada lafal Jannatin (yang telah dijanjikan oleh Tuhan Yang Maha Pemurah kepada hamba-hamba-Nya, sekalipun surga itu tidak tampak). Lafal Bil Ghaibi menjadi Hal, maksudnya walaupun surga itu tidak kelihatan oleh mereka. (Sesungguhnya janji Allah itu) yakni apa yang telah dijanjikan oleh-Nya (pasti akan ditepati). Lafal Ma'tiyyan maknanya Aatiyan; asalnya adalah Ma'tiwyun. Yang dimaksud dengan janji-Nya adalah surga yang akan ditempati oleh orang-orang yang berhak memasukinya.",[["جَنَّـٰتِ","Gardens"],["عَدْنٍ","(of) Eden"],["ٱلَّتِى","which"],["وَعَدَ","promised"],["ٱلرَّحْمَـٰنُ","the Most Gracious"],["عِبَادَهُۥ","(to) His slaves"],["بِٱلْغَيْبِ ۚ","in the unseen"],["إِنَّهُۥ","Indeed, [it]"],["كَانَ","is"],["وَعْدُهُۥ","His promise"],["مَأْتِيًّۭا","sure to come"]]],"2312":["(Mereka tidak mendengar perkataan yang tidak berguna di dalam surga) pembicaraan yang tak berarti (kecuali) mereka hanya mendengar (ucapan Salam) dari para Malaikat buat mereka, atau dari sebagian mereka kepada sebagian yang lain. (Bagi mereka rezekinya di surga itu tiap-tiap pagi dan petang) dalam perkiraan kedua waktu tersebut menurut perhitungan waktu di dunia, karena sesungguhnya di dalam surga itu tidak ada siang dan malam tetapi yang ada hanyalah cahaya dan nur yang abadi.",[["لَّا","Not"],["يَسْمَعُونَ","they will hear"],["فِيهَا","therein"],["لَغْوًا","vain talk"],["إِلَّا","but"],["سَلَـٰمًۭا ۖ","peace"],["وَلَهُمْ","And for them"],["رِزْقُهُمْ","(is) their provision"],["فِيهَا","therein"],["بُكْرَةًۭ","morning"],["وَعَشِيًّۭا","and evening"]]],"2313":["(Itulah surga yang akan Kami wariskan) Kami anugerahkan dan Kami tempatkan di dalamnya (kepada hamba-hamba Kami yang selalu bertakwa) yang berlaku taat kepada-Nya. Ayat berikut diturunkan ketika wahyu datang sangat terlambat selama beberapa hari, kemudian Nabi saw. berkata kepada malaikat Jibril ketika datang kepadanya, \"Apakah gerangan yang menyebabkan engkau tidak menziarahi aku selama ini\".",[["تِلْكَ","This"],["ٱلْجَنَّةُ","(is) Paradise"],["ٱلَّتِى","which"],["نُورِثُ","We give (as) inheritance"],["مِنْ","[of] (to)"],["عِبَادِنَا","Our slaves"],["مَن","(the one) who"],["كَانَ","is"],["تَقِيًّۭا","righteous"]]],"2314":["(Dan tidaklah kami turun melainkan dengan perintah Rabbmu, kepunyaan-Nyalah apa-apa yang ada di hadapan kita) yakni berupa semua perkara akhirat (apa-apa yang ada di belakang kita) berupa semua perkara duniawi (dan apa-apa yang ada di antara keduanya) apa yang ada dalam waktu sekarang sampai dengan datangnya hari kiamat. Yang dimaksud ialah bahwa pengetahuan mengenai kesemuanya itu berada pada-Nya (dan tidaklah Rabbmu lupa) lafal Nasiyyan bermakna Naasiyan, maksudnya, Allah tidak akan meninggalkanmu disebabkan wahyu yang terlambat datang kepadamu.",[["وَمَا","And not"],["نَتَنَزَّلُ","we descend"],["إِلَّا","except"],["بِأَمْرِ","by (the) Command"],["رَبِّكَ ۖ","(of) your Lord"],["لَهُۥ","To Him (belongs)"],["مَا","what"],["بَيْنَ","(is) before us"],["أَيْدِينَا","(is) before us"],["وَمَا","and what"],["خَلْفَنَا","(is) behind us"],["وَمَا","and what"],["بَيْنَ","(is) between"],["ذَٰلِكَ ۚ","that"],["وَمَا","And not"],["كَانَ","is"],["رَبُّكَ","your Lord"],["نَسِيًّۭا","forgetful"]]],"2315":["Dia adalah (Rabb) yang menguasai (langit dan bumi dan apa-apa yang ada di antara keduanya, maka sembahlah Dia dan berteguh hatilah dalam beribadah kepada-Nya) bersikap sabarlah dalam menjalankan dua perkara tersebut. (Apakah kamu mengetahui ada seorang yang sama dengan Dia) yang patut disembah seperti Dia, tentu saja tidak.",[["رَّبُّ","Lord"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا","(is) between both of them"],["فَٱعْبُدْهُ","so worship Him"],["وَٱصْطَبِرْ","and be constant"],["لِعِبَـٰدَتِهِۦ ۚ","in His worship"],["هَلْ","Do"],["تَعْلَمُ","you know"],["لَهُۥ","for Him"],["سَمِيًّۭا","any similarity"]]],"2316":["(Dan berkata manusia,) mereka yang ingkar kepada adanya hari berbangkit, yaitu Ubay bin Khalaf atau Walid bin Mughirah, ayat ini diturunkan berkenaan dengan sikapnya itu (\"Betulkah apabila) dapat dibaca Aidza dan Ayidza (aku telah mati, bahwa aku sungguh-sungguh akan dibangkitkan menjadi hidup kembali?\") yakni akan dihidupkan kembali dari kuburan sebagaimana yang telah dikatakan oleh Muhammad. Kata tanya di sini mengandung makna Nafi atau kalimat negatif, maksudnya, Aku tidak akan dihidupkan kembali sesudah mati. Huruf Ma adalah Zaidah yang faedahnya untuk mengukuhkan kalimat, demikian pula huruf Lamnya. Kemudian Allah menyanggah perkataan mereka itu melalui firman-Nya:",[["وَيَقُولُ","And says"],["ٱلْإِنسَـٰنُ","[the] man"],["أَءِذَا","What! When"],["مَا","What! When"],["مِتُّ","I am dead"],["لَسَوْفَ","surely will"],["أُخْرَجُ","I be brought forth"],["حَيًّا","alive"]]],"2317":["(Dan tidakkah manusia itu memikirkan) asal kata Yadzdzakkaru ini adalah Yatadzakkaru, kemudian huruf Ta diganti menjadi Dzal, lalu diidghamkan ke dalam huruf Dzal asal sehingga menjadi Yadzdzakkaru. Tetapi menurut qiraat yang lain dibaca Yadzkuru (bahwa sesungguhnya Kami telah menciptakannya dahulu, sedangkan ia tidak ada sama sekali) oleh karenanya mengapa ia tidak mengambil kesimpulan dari permulaan itu kepada pengembalian, yakni kembali kepada-Nya.",[["أَوَلَا","Does not"],["يَذْكُرُ","remember"],["ٱلْإِنسَـٰنُ","[the] man"],["أَنَّا","that We"],["خَلَقْنَـٰهُ","We created him"],["مِن","before"],["قَبْلُ","before"],["وَلَمْ","while not"],["يَكُ","he was"],["شَيْـًۭٔا","anything"]]],"2318":["(Demi Rabbmu, sesungguhnya akan Kami bangkitkan mereka) orang-orang yang ingkar kepada adanya hari berbangkit itu (bersama dengan setan) Kami mengumpulkan masing-masing dari mereka bersama setan-setannya dalam keadaan terbelenggu (kemudian akan Kami datangkan mereka ke sekeliling Jahanam) dari luarnya (dengan berlutut) berjalan dengan lututnya. Lafal Jitsiyyan adalah bentuk jamak dari lafal jaatsin, asal katanya adalah Jitsuwwun atau Jitsuwyun yang akar katanya berasal dari Jatsaa-Yajtsuu atau Jatsaa Yajtsii. Ada dua pendapat sehubungan dengan lafal ini.",[["فَوَرَبِّكَ","So by your Lord"],["لَنَحْشُرَنَّهُمْ","surely, We will gather them"],["وَٱلشَّيَـٰطِينَ","and the devils"],["ثُمَّ","then"],["لَنُحْضِرَنَّهُمْ","surely, We will bring them"],["حَوْلَ","around"],["جَهَنَّمَ","Hell"],["جِثِيًّۭا","bent (on) knees"]]],"2319":["(Kemudian pasti akan Kami tarik dari tiap-tiap golongan) yakni setiap kelompok dari mereka (siapa di antara mereka yang sangat durhaka kepada Tuhan Yang Maha Pemurah) sangat berani berbuat durhaka kepada-Nya.",[["ثُمَّ","Then"],["لَنَنزِعَنَّ","surely, We will drag out"],["مِن","from"],["كُلِّ","every"],["شِيعَةٍ","sect"],["أَيُّهُمْ","those of them"],["أَشَدُّ","(who were) worst"],["عَلَى","against"],["ٱلرَّحْمَـٰنِ","the Most Gracious"],["عِتِيًّۭا","(in) rebellion"]]],"2320":["(Dan kemudian Kami sungguh lebih mengetahui orang-orang yang lebih utama terhadapnya) lebih berhak terhadap Jahanam, yaitu orang yang sangat durhaka kepada-Nya dan orang-orang yang sama seperti mereka (untuk dimasukkan ke dalamnya) yang lebih utama masuk Jahanam dan lebih layak untuk menempatinya. Maka Kami memulai dengan mereka. Asal kata Shiliyyun adalah Shiliwyun, berasal dari Fi'il Shaliya atau Shalaa.",[["ثُمَّ","Then"],["لَنَحْنُ","surely, We"],["أَعْلَمُ","know best"],["بِٱلَّذِينَ","[of] those who"],["هُمْ","[they]"],["أَوْلَىٰ","(are) most worthy"],["بِهَا","therein"],["صِلِيًّۭا","(of) being burnt"]]],"2321":["(Dan tidak) (daripada kalian) seorang pun (melainkan mendatangi neraka itu) neraka Jahanam. (Hal itu bagi Rabbmu adalah suatu kemestian yang sudah ditetapkan) telah dipastikan dan telah diputuskan oleh-Nya, hal ini tidak akan diabaikan-Nya.",[["وَإِن","And (there is) not"],["مِّنكُمْ","(any) of you"],["إِلَّا","but"],["وَارِدُهَا ۚ","(will be) passing over it"],["كَانَ","(This) is"],["عَلَىٰ","upon"],["رَبِّكَ","your Lord"],["حَتْمًۭا","an inevitability"],["مَّقْضِيًّۭا","decreed"]]],"2322":["(Kemudian Kami akan menyelamatkan) dapat dibaca Nunajjii dan Nunjii (orang-orang yang bertakwa) orang-orang yang memelihara dirinya dari kemusyrikan dan kekafiran, Kami akan selamatkan daripadanya (dan Kami akan membiarkan orang-orang yang zalim) orang-orang yang melakukan kemusyrikan dan kekafiran (di dalam neraka dalam keadaan berlutut) berdiri di atas lutut mereka.",[["ثُمَّ","Then"],["نُنَجِّى","We will deliver"],["ٱلَّذِينَ","those who"],["ٱتَّقَوا۟","feared (Allah)"],["وَّنَذَرُ","and We will leave"],["ٱلظَّـٰلِمِينَ","the wrongdoers"],["فِيهَا","therein"],["جِثِيًّۭا","bent (on) knees"]]],"2323":["(Dan apabila dibacakan kepada mereka) yaitu mereka orang-orang Mukmin dan orang-orang kafir (ayat-ayat Kami) dari Alquran (yang terang) jelas keadaan dan maksudnya (niscaya orang-orang yang kafir berkata kepada orang-orang yang beriman, \"Manakah di antara kedua golongan) kami dan kalian (yang lebih baik tempat tinggalnya) yaitu, tempat menetap dan rumahnya. Lafal Maqaaman berasal dari kata kerja Qaama, kalau dibaca Muqaaman berarti berasal dari kata kerja Aqaama (dan lebih indah tempat pertemuannya\"). Lafal Nadiyyan bermakna An-Naadi artinya tempat berkumpulnya kaum, yang mereka berbincang-bincang di dalamnya. Mereka bermaksud bahwa kamilah yang lebih baik daripada kalian. Kemudian Allah berfirman,",[["وَإِذَا","And when"],["تُتْلَىٰ","are recited"],["عَلَيْهِمْ","to them"],["ءَايَـٰتُنَا","Our Verses"],["بَيِّنَـٰتٍۢ","clear"],["قَالَ","say"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["لِلَّذِينَ","to those who"],["ءَامَنُوٓا۟","believed"],["أَىُّ","Which"],["ٱلْفَرِيقَيْنِ","(of) the two groups"],["خَيْرٌۭ","(is) better"],["مَّقَامًۭا","(in) position"],["وَأَحْسَنُ","and best"],["نَدِيًّۭا","(in) assembly"]]],"2324":["(\"Berapa banyak) alangkah banyaknya (umat yang telah Kami binasakan sebelum mereka) yaitu umat-umat di masa silam (sedangkan mereka adalah lebih bagus alat rumah tangganya) yakni harta bendanya lebih banyak dan perabotan rumah tangga mereka jauh lebih bagus (dan lebih sedap dipandang mata\") lebih indah dipandang mata. Lafal Ri'yan berasal dari kata Ar-Ru'yah. Maksudnya, sebagaimana Kami telah membinasakan umat-umat dahulu disebabkan kekafirannya, maka Kami pun akan membinasakan mereka pula.",[["وَكَمْ","And how many"],["أَهْلَكْنَا","We destroyed"],["قَبْلَهُم","before them"],["مِّن","of"],["قَرْنٍ","a generation "],["هُمْ","they"],["أَحْسَنُ","(were) better"],["أَثَـٰثًۭا","(in) possessions"],["وَرِءْيًۭا","and appearance"]]],"2325":["(Katakanlah! \"Barang siapa yang berada di dalam kesesatan) kalimat ayat ini mengandung syarat sedangkan Jawabnya ialah (maka biarlah diperpanjang) kalimat perintah di sini bermakna kalimat berita, artinya hendaknya diperpanjang (tempo baginya oleh Yang Maha Pemurah dengan sesungguhnya) di dunia ini dengan memperturutkan apa yang ia kehendaki (sehingga apabila mereka telah melihat apa yang diancamkan kepadanya, baik siksa) seperti dibunuh dan ditahan (maupun kiamat) yang pengertiannya mencakup juga neraka Jahanam tempat mereka dimasukkan ke dalamnya (maka mereka akan mengetahui siapa yang lebih jelek kedudukannya dan lebih lemah penolong-penolongnya\") yakni pembantu-pembantunya; apakah mereka ataukah orang-orang yang beriman, pembantu-pembantu mereka adalah setan sedangkan pembantu-pembantu orang-orang yang beriman di dalam menghadapi mereka adalah para Malaikat.",[["قُلْ","Say"],["مَن","Whoever"],["كَانَ","is"],["فِى","in"],["ٱلضَّلَـٰلَةِ","[the] error"],["فَلْيَمْدُدْ","then surely will extend"],["لَهُ","for him"],["ٱلرَّحْمَـٰنُ","the Most Gracious"],["مَدًّا ۚ","an extension"],["حَتَّىٰٓ","until"],["إِذَا","when"],["رَأَوْا۟","they see"],["مَا","what"],["يُوعَدُونَ","they were promised"],["إِمَّا","either"],["ٱلْعَذَابَ","the punishment"],["وَإِمَّا","or"],["ٱلسَّاعَةَ","the Hour"],["فَسَيَعْلَمُونَ","then they will know"],["مَنْ","who"],["هُوَ","[he]"],["شَرٌّۭ","(is) worst"],["مَّكَانًۭا","(in) position"],["وَأَضْعَفُ","and weaker"],["جُندًۭا","(in) forces"]]],"2326":["(Dan Allah akan menambah kepada mereka yang telah mendapat petunjuk) berkat iman mereka (hidayah) berkat ayat-ayat yang diturunkan kepada mereka (Dan amal-amal saleh yang kekal itu) yaitu ketaatan kepada Allah yang selalu dilakukan oleh seseorang (lebih baik pahalanya di sisi Rabbmu dan lebih baik kesudahannya) akhir dan kesudahan daripadanya, berbeda dengan amal perbuatan orang-orang kafir. Pengertian perbandingan kebaikan di sini sebagai kebalikan daripada perkataan orang-orang kafir, yaitu ketika mereka mengatakan, \"Manakah di antara kedua golongan yang lebih baik kedudukannya?\"",[["وَيَزِيدُ","And Allah increases"],["ٱللَّهُ","And Allah increases"],["ٱلَّذِينَ","those who"],["ٱهْتَدَوْا۟","accept guidance"],["هُدًۭى ۗ","(in) guidance"],["وَٱلْبَـٰقِيَـٰتُ","And the everlasting"],["ٱلصَّـٰلِحَـٰتُ","good deeds"],["خَيْرٌ","(are) better"],["عِندَ","near"],["رَبِّكَ","your Lord"],["ثَوَابًۭا","(for) reward"],["وَخَيْرٌۭ","and better"],["مَّرَدًّا","(for) return"]]],"2327":["(Maka apakah kamu telah melihat orang yang kafir kepada ayat-ayat Kami) maksudnya 'Ashi bin Wa'il (dan ia mengatakan,) kepada Khabbab bin Art yang mengatakan kepadanya, bahwa engkau kelak akan dibangkitkan hidup kembali sesudah mati. Pada saat itu Khabbab sedang menagih utang kepadanya (\"Pasti aku akan diberi) seandainya aku dibangkitkan hidup kembali (harta dan anak\") maka pada saat itu aku akan membayar utangku kepadamu. Allah berfirman menyanggahnya:",[["أَفَرَءَيْتَ","Then, have you seen"],["ٱلَّذِى","he who"],["كَفَرَ","disbelieved"],["بِـَٔايَـٰتِنَا","in Our Verses"],["وَقَالَ","and said"],["لَأُوتَيَنَّ","Surely, I will be given"],["مَالًۭا","wealth"],["وَوَلَدًا","and children"]]],"2328":["(Adakah dia melihat yang gaib) apakah dia mengetahuinya sehingga ia berani mengatakan, bahwa dia akan diberi seperti apa yang dikatakannya itu. Lafal Aththala'a ini disebabkan sudah cukup hanya dengan memakai Hamzah Istifham, maka Hamzah Washalnya dibuang (atau ia telah membuat perjanjian di sisi Tuhan Yang Maha Pemurah?) sehingga ia berani mengatakan, bahwa Allah akan memberikan kepadanya apa yang telah dikatakannya itu.",[["أَطَّلَعَ","Has he looked"],["ٱلْغَيْبَ","(into) the unseen"],["أَمِ","or"],["ٱتَّخَذَ","has he taken"],["عِندَ","from"],["ٱلرَّحْمَـٰنِ","the Most Gracious"],["عَهْدًۭا","a promise"]]],"2329":["(Sekali-kali tidak) hal itu tidak akan diberikan kepadanya (Kami akan menulis) Kami memerintahkan untuk menuliskan (apa yang ia katakan itu dan benar-benar Kami akan memperpanjang azab baginya) Kami akan menambahkan kepada azab kekafirannya azab yang lain, karena perkataannya itu.",[["كَلَّا ۚ","Nay"],["سَنَكْتُبُ","We will record"],["مَا","what"],["يَقُولُ","he says"],["وَنَمُدُّ","and We will extend"],["لَهُۥ","for him"],["مِنَ","from"],["ٱلْعَذَابِ","the punishment"],["مَدًّۭا","extensively"]]],"2330":["(Dan Kami akan mewarisi apa yang ia katakan itu) yaitu harta benda dan anak (dan ia akan datang kepada Kami) kelak pada hari kiamat (dengan seorang diri) dalam keadaan tidak punya harta benda dan tidak punya anak.",[["وَنَرِثُهُۥ","And We will inherit (from) him"],["مَا","what"],["يَقُولُ","he says"],["وَيَأْتِينَا","and he will come to Us"],["فَرْدًۭا","alone"]]],"2331":["(Dan mereka telah mengambil) orang-orang kafir Mekah (selain dari Allah) yakni berhala-berhala (sebagai tuhan-tuhan) yang mereka sembah (agar tuhan-tuhan itu menjadi pelindung bagi mereka) maksudnya memberikan syafaat kepada mereka di hadapan Allah supaya mereka jangan diazab oleh-Nya.",[["وَٱتَّخَذُوا۟","And they have taken"],["مِن","besides Allah"],["دُونِ","besides Allah"],["ٱللَّهِ","besides Allah"],["ءَالِهَةًۭ","gods"],["لِّيَكُونُوا۟","that they may be"],["لَهُمْ","for them"],["عِزًّۭا","an honor"]]],"2332":["(Sekali-kali tidak) tiada sesuatu pun yang dapat mencegah azab mereka. (Kelak mereka itu akan mengingkari) yakni tuhan-tuhan sembahan mereka itu (penyembahan mereka) artinya mereka akan mengingkari penyembahan orang-orang yang mempertuhankan mereka, sebagaimana dijelaskan pula oleh ayat lain, yaitu firman-Nya, \"Mereka sekali-kali tidak menyembah Kami...\" (Q.S. Al-Qashash, 63). (dan tuhan-tuhan itu akan menjadi musuh bagi mereka) yakni berhala-berhala itu justru akan menjadi musuh orang-orang yang menyembahnya kelak di akhirat.",[["كَلَّا ۚ","Nay"],["سَيَكْفُرُونَ","they will deny"],["بِعِبَادَتِهِمْ","their worship (of them)"],["وَيَكُونُونَ","and they will be"],["عَلَيْهِمْ","against them"],["ضِدًّا","opponents"]]],"2333":["(Tidakkah kamu lihat, bahwasanya Kami telah mengirim setan-setan itu) yakni pengaruh mereka (kepada orang-orang kafir untuk menghasut mereka) untuk menggerakkan mereka melakukan perbuatan-perbuatan maksiat (dengan sungguh-sungguh).",[["أَلَمْ","Do not"],["تَرَ","you see"],["أَنَّآ","that We"],["أَرْسَلْنَا","[We] have sent"],["ٱلشَّيَـٰطِينَ","the devils"],["عَلَى","upon"],["ٱلْكَـٰفِرِينَ","the disbelievers"],["تَؤُزُّهُمْ","inciting them"],["أَزًّۭا","(with) incitement"]]],"2334":["(Maka janganlah kamu tergesa-gesa terhadap mereka) untuk mendatangkan azab buat mereka (karena sesungguhnya Kami hanya menghitung untuk mereka) hari-hari atau nafas-nafas mereka (dengan perhitungan yang teliti) hingga tiba saatnya azab mereka.",[["فَلَا","So (do) not"],["تَعْجَلْ","make haste"],["عَلَيْهِمْ ۖ","against them"],["إِنَّمَا","Only"],["نَعُدُّ","We count"],["لَهُمْ","for them"],["عَدًّۭا","a number"]]],"2335":["Ingatlah (hari ketika Kami mengumpulkan orang-orang yang takwa) berkat keimanan mereka (kepada Tuhan Yang Maha Pemurah sebagai perutusan yang terhormat). Lafal Wafdun adalah bentuk jamak dan lafal Waafidun, artinya delegasi.",[["يَوْمَ","(The) Day"],["نَحْشُرُ","We will gather"],["ٱلْمُتَّقِينَ","the righteous"],["إِلَى","to"],["ٱلرَّحْمَـٰنِ","the Most Gracious"],["وَفْدًۭا","(as) a delegation"]]],"2336":["(Dan Kami akan menghalau orang-orang yang durhaka) karena kekafiran mereka (ke neraka Jahanam dalam keadaan dahaga). Lafal Wirdun adalah bentuk jamak dari lafal Waaridun artinya berjalan dalam keadaan dahaga.",[["وَنَسُوقُ","And We will drive"],["ٱلْمُجْرِمِينَ","the criminals"],["إِلَىٰ","to"],["جَهَنَّمَ","Hell"],["وِرْدًۭا","thirsty"]]],"2337":["(Mereka tidak dapat memberi) manusia semuanya (syafaat kecuali orang yang telah mengadakan perjanjian di sisi Tuhan Yang Maha Pemurah) yakni kesaksian bahwa tiada Tuhan selain Allah dan tiada daya serta tiada kekuatan melainkan berkat pertolongan Allah.",[["لَّا","Not"],["يَمْلِكُونَ","they will have the power"],["ٱلشَّفَـٰعَةَ","(of) the intercession"],["إِلَّا","except"],["مَنِ","(he) who"],["ٱتَّخَذَ","has taken"],["عِندَ","from"],["ٱلرَّحْمَـٰنِ","the Most Gracious"],["عَهْدًۭا","a covenant"]]],"2338":["(Dan mereka berkata,) orang-orang Yahudi dan Nasrani dan orang-orang yang menyangka bahwa malaikat-malaikat itu adalah anak-anak perempuan Allah (\"Tuhan Yang Maha Pemurah mempunyai anak\") maka Allah menyanggah perkataan mereka itu melalui firman-Nya,",[["وَقَالُوا۟","And they say"],["ٱتَّخَذَ","Has taken"],["ٱلرَّحْمَـٰنُ","the Most Gracious"],["وَلَدًۭا","a son"]]],"2339":["(\"Sesungguhnya kalian telah mendatangkan sesuatu perkara yang sangat mungkar) yaitu suatu perkara mungkar yang sangat besar.",[["لَّقَدْ","Verily"],["جِئْتُمْ","you have put forth"],["شَيْـًٔا","a thing"],["إِدًّۭا","atrocious"]]],"2340":["(Hampir-hampir) dapat dibaca Takaadu dan Yakaadu (langit pecah) terbelah, dan menurut qiraat yang lain lafal Yatafaththarna dibaca Yanfathirna (karena ucapan itu dan bumi belah dan gunung-gunung runtuh) yakni terbalik menindih mereka disebabkan.",[["تَكَادُ","Almost"],["ٱلسَّمَـٰوَٰتُ","the heavens"],["يَتَفَطَّرْنَ","get torn"],["مِنْهُ","therefrom"],["وَتَنشَقُّ","and splits asunder"],["ٱلْأَرْضُ","the earth"],["وَتَخِرُّ","and collapse"],["ٱلْجِبَالُ","the mountain"],["هَدًّا","(in) devastation"]]],"2341":["(mereka mendakwakan Allah Yang Maha Pemurah mempunyai anak\"). Allah berfirman,",[["أَن","That"],["دَعَوْا۟","they invoke"],["لِلرَّحْمَـٰنِ","to the Most Gracious"],["وَلَدًۭا","a son"]]],"2342":["(\"Dan tidak layak bagi Allah Yang Maha Pemurah mempunyai anak\") yakni tidak patut bagi-Nya hal yang demikian itu.",[["وَمَا","And not"],["يَنۢبَغِى","is appropriate"],["لِلرَّحْمَـٰنِ","for the Most Gracious"],["أَن","that"],["يَتَّخِذَ","He should take"],["وَلَدًا","a son"]]],"2343":["(Tidak ada) (seorang pun di langit dan di bumi melainkan akan datang kepada Tuhan Yang Maha Pemurah selaku seorang hamba) yang hina dan tunduk patuh kepada-Nya kelak di hari kiamat, termasuk Uzair dan Isa juga.",[["إِن","Not"],["كُلُّ","all"],["مَن","who"],["فِى","(are) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ","and the earth"],["إِلَّآ","but"],["ءَاتِى","(will) come"],["ٱلرَّحْمَـٰنِ","(to) the Most Gracious"],["عَبْدًۭا","(as) a slave"]]],"2344":["(Sesungguhnya Allah telah menentukan jumlah mereka dan menghitung mereka dengan hitungan yang teliti) maka tidak samar bagi-Nya mengenai jumlah mereka secara keseluruhan atau pun secara rinci dan tiada seorang pun yang terlewat dari perhitungan-Nya.",[["لَّقَدْ","Verily"],["أَحْصَىٰهُمْ","He has enumerated them"],["وَعَدَّهُمْ","and counted them"],["عَدًّۭا","a counting"]]],"2345":["(Dan tiap-tiap mereka akan datang kepada Allah pada hari kiamat dengan sendiri-sendiri) tanpa harta dan tanpa pembantu yang dapat membelanya.",[["وَكُلُّهُمْ","And all of them"],["ءَاتِيهِ","(will) come (to) Him"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["فَرْدًا","alone"]]],"2346":["(Sesungguhnya orang-orang yang beriman dan beramal saleh, kelak Allah Yang Maha Pemurah akan menanamkan dalam hati mereka rasa kasih sayang) di antara sesama mereka; mereka saling kasih-mengasihi dan sayang-menyayangi dan Allah swt. mencintai mereka semuanya.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["وَعَمِلُوا۟","and did"],["ٱلصَّـٰلِحَـٰتِ","good deeds"],["سَيَجْعَلُ","will bestow"],["لَهُمُ","for them"],["ٱلرَّحْمَـٰنُ","the Most Gracious"],["وُدًّۭا","affection"]]],"2347":["(Maka sesungguhnya telah Kami mudahkan dia) Alquran itu (dengan bahasamu) bahasa Arab (agar kamu dapat memberi kabar gembira dengan Alquran itu kepada orang-orang yang bertakwa) yaitu orang-orang yang beruntung memperoleh iman (dan agar kamu memberi peringatan) menakut-nakuti (dengannya kepada kaum yang membangkang). Lafal Luddan adalah bentuk jamak dari lafal Aladdun artinya banyak membantah dengan kebatilan, mereka adalah orang-orang kafir Mekah.",[["فَإِنَّمَا","So, only"],["يَسَّرْنَـٰهُ","We (have) made it easy"],["بِلِسَانِكَ","in your tongue"],["لِتُبَشِّرَ","that you may give glad tidings"],["بِهِ","with it"],["ٱلْمُتَّقِينَ","(to) the righteous"],["وَتُنذِرَ","and warn"],["بِهِۦ","with it"],["قَوْمًۭا","a people"],["لُّدًّۭا","hostile"]]],"2348":["(Dan berapa banyak) banyak sekali (telah Kami binasakan umat-umat sebelum mereka) umat-umat di masa silam disebabkan kedustaan mereka terhadap Rasul (Adakah kamu melihat) menemukan (seorang pun dari mereka atau kamu dengar suara mereka yang samar-samar?) Tentu saja tidak. Sebagaimana Kami telah membinasakan umat-umat di masa silam maka niscaya pula Kami akan membinasakan mereka, disebabkan kekafiran mereka itu.",[["وَكَمْ","And how many"],["أَهْلَكْنَا","We (have) destroyed"],["قَبْلَهُم","before them"],["مِّن","of"],["قَرْنٍ","a generation"],["هَلْ","Can"],["تُحِسُّ","you perceive"],["مِنْهُم","of them"],["مِّنْ","any"],["أَحَدٍ","one"],["أَوْ","or"],["تَسْمَعُ","hear"],["لَهُمْ","from them"],["رِكْزًۢا","a sound"]]],"2349":["(Tha Ha) hanya Allahlah yang mengetahui maksudnya",[["طه","Ta Ha"]]],"2350":["(Kami tidak menurunkan Alquran ini kepadamu) hai Muhammad (agar kamu menjadi susah) supaya kamu letih dan payah disebabkan apa yang kamu kerjakan sesudah ia diturunkan, sehingga kamu harus berkepanjangan berdiri di dalam melakukan salat malam. Maksudnya berilah kesempatan istirahat bagi dirimu.",[["مَآ","Not"],["أَنزَلْنَا","We (have) sent down"],["عَلَيْكَ","to you"],["ٱلْقُرْءَانَ","the Quran"],["لِتَشْقَىٰٓ","that you be distressed"]]],"2351":["(Tetapi) Kami turunkan Alquran ini (sebagai peringatan) melalui apa yang dikandungnya (bagi orang yang takut) kepada Allah.",[["إِلَّا","(But)"],["تَذْكِرَةًۭ","(as) a reminder"],["لِّمَن","for (those) who"],["يَخْشَىٰ","fear"]]],"2352":["(Yaitu diturunkan) lafal Tanziilan ini menjadi Badal dari lafal Fi'il yang menashabkannya, yakni Nazzalahu Tanziilan (dari Allah yang menciptakan bumi dan langit yang tinggi). Lafal Al 'Ula merupakan bentuk jamak dari kata 'Ulyaa, keadaannya sama dengan lafal Kubraa dan Kubar.",[["تَنزِيلًۭا","A revelation"],["مِّمَّنْ","from (He) Who"],["خَلَقَ","created"],["ٱلْأَرْضَ","the earth"],["وَٱلسَّمَـٰوَٰتِ","and the heavens"],["ٱلْعُلَى","[the] high"]]],"2353":["Yaitu (Tuhan Yang Maha Pemurah, yang di atas Arasy) lafal Arasy ini menurut pengertian bahasa diartikan singgasana raja (berkuasa) yakni bersemayam sesuai dengan keagungan dan kebesaran-Nya.",[["ٱلرَّحْمَـٰنُ","The Most Gracious"],["عَلَى","over"],["ٱلْعَرْشِ","the Throne"],["ٱسْتَوَىٰ","is established"]]],"2354":["(Kepunyaan-Nyalah semua yang ada di langit, semua yang ada di bumi, semua yang ada di antara keduanya) yakni makhluk-makhluk yang ada di antara keduanya (dan semua yang di bawah tanah) yaitu lapisan tanah yang masih basah, yang dimaksud adalah di bawah semua lapisan bumi yang tujuh, karena lapisan bumi yang berjumlah tujuh itu berada di bawah lapisan tanah yang basah.",[["لَهُۥ","To Him (belongs)"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَا","and whatever"],["فِى","(is) in"],["ٱلْأَرْضِ","the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا","(is) between them"],["وَمَا","and whatever"],["تَحْتَ","(is) under"],["ٱلثَّرَىٰ","the soil"]]],"2355":["(Dan jika kamu mengeraskan ucapanmu) di dalam berzikir atau berdoa, maka sesungguhnya Allah tidak memerlukan suara keras engkau sewaktu melakukan hal tersebut (maka sesungguhnya Dia mengetahui rahasia dan yang lebih tersembunyi) daripada rahasia, maksudnya adalah semua apa yang ada dalam hati manusia yang tidak diungkapkannya, maka janganlah engkau memayahkan dirimu dengan mengeraskan suaramu.",[["وَإِن","And if"],["تَجْهَرْ","you speak aloud"],["بِٱلْقَوْلِ","the word"],["فَإِنَّهُۥ","then indeed, He"],["يَعْلَمُ","knows"],["ٱلسِّرَّ","the secret"],["وَأَخْفَى","and the more hidden"]]],"2356":["(Dialah Allah, tidak ada Tuhan melainkan Dia, Dia mempunyai Asmaulhusna) jumlahnya sebanyak yang disebutkan di dalam hadis yaitu sembilan puluh sembilan nama-nama yang baik. Lafal Al Husna bentuk Muannats daripada lafal Al Ahsan.",[["ٱللَّهُ","Allah "],["لَآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","except"],["هُوَ ۖ","Him"],["لَهُ","To Him (belong)"],["ٱلْأَسْمَآءُ","the Names"],["ٱلْحُسْنَىٰ","the Most Beautiful"]]],"2357":["(Apakah) telah (datang kepadamu kisah Musa?)",[["وَهَلْ","And has"],["أَتَىٰكَ","come to you"],["حَدِيثُ","the narration"],["مُوسَىٰٓ","(of) Musa"]]],"2358":["(Ketika ia melihat api, lalu berkatalah ia kepada keluarganya) yakni kepada istrinya, (\"Tinggallah kamu) di sini, hal itu terjadi sewaktu ia berada dalam perjalanan dari Madyan menuju ke negeri Mesir (sesungguhnya aku melihat) menyaksikan (api, mudah-mudahan aku dapat membawa sedikit daripadanya untuk kalian) berupa obor yang dinyalakan pada sumbu atau kayu (atau aku akan mendapatkan petunjuk di tempat itu\") yang dapat menunjukkan jalan; karena pada saat itu Nabi Musa kehilangan arah jalan disebabkan gelapnya malam. Nabi Musa mengungkapkan kata-katanya dengan memakai istilah La'alla yang artinya mudah-mudahan karena ia merasa kurang pasti dengan apa yang telah dijanjikannya itu.",[["إِذْ","When"],["رَءَا","he saw"],["نَارًۭا","a fire"],["فَقَالَ","then he said"],["لِأَهْلِهِ","to his family"],["ٱمْكُثُوٓا۟","Stay here"],["إِنِّىٓ","indeed, I"],["ءَانَسْتُ","[I] perceived"],["نَارًۭا","a fire"],["لَّعَلِّىٓ","perhaps I (can)"],["ءَاتِيكُم","bring you"],["مِّنْهَا","therefrom"],["بِقَبَسٍ","a burning brand"],["أَوْ","or"],["أَجِدُ","I find"],["عَلَى","at"],["ٱلنَّارِ","the fire"],["هُدًۭى","guidance"]]],"2359":["(Maka ketika ia datang ke tempat api itu) yaitu di pohon 'Ausaj (ia dipanggil, \"Hai Musa!)",[["فَلَمَّآ","Then when"],["أَتَىٰهَا","he came to it"],["نُودِىَ","he was called"],["يَـٰمُوسَىٰٓ","O Musa"]]],"2360":["(Sesungguhnya Aku) dibaca Innii karena dengan menganggap lafal Nudiya bermakna Qiila. Dan bila dibaca Annii maka diperkirakan adanya huruf Ba sebelumnya (inilah) lafal Anaa di sini berfungsi mentaukidkan makna yang terkandung di dalam Ya Mutakallim (Rabbmu, maka tanggalkanlah kedua terompahmu; sesungguhnya kamu berada di lembah yang suci) lembah yang disucikan, atau lembah yang diberkati (Thuwa) menjadi Badal atau 'Athaf Bayan. Kalau dibaca Thuwan maka dianggap sebagai nama tempat saja dan jika dibaca Thuwa dalam bentuk lafal yang Muannats, maka dianggap sebagai nama daerah dan 'Alamiyah, sehingga tidak menerima harakat Tanwin.",[["إِنِّىٓ","Indeed, [I]"],["أَنَا۠","I Am"],["رَبُّكَ","your Lord"],["فَٱخْلَعْ","so remove"],["نَعْلَيْكَ ۖ","your shoes"],["إِنَّكَ","Indeed, you"],["بِٱلْوَادِ","(are) in the valley"],["ٱلْمُقَدَّسِ","the sacred"],["طُوًۭى","(of) Tuwa"]]],"2361":["(Dan Aku telah memilih kamu) dari kaummu (maka dengarkanlah apa yang akan diwahyukan kepadamu) dari-Ku.",[["وَأَنَا","And I"],["ٱخْتَرْتُكَ","(have) chosen you"],["فَٱسْتَمِعْ","so listen"],["لِمَا","to what"],["يُوحَىٰٓ","is revealed"]]],"2362":["(Sesungguhnya Aku ini adalah Allah, tiada Tuhan selain Aku, maka sembahlah Aku dan dirikanlah salat untuk mengingat Aku) di dalam salat itu.",[["إِنَّنِىٓ","Indeed, [I]"],["أَنَا","I Am"],["ٱللَّهُ","Allah"],["لَآ","(There is) no"],["إِلَـٰهَ","god"],["إِلَّآ","but"],["أَنَا۠","I"],["فَٱعْبُدْنِى","so worship Me"],["وَأَقِمِ","and establish"],["ٱلصَّلَوٰةَ","the prayer"],["لِذِكْرِىٓ","for My remembrance"]]],"2363":["(Sesungguhnya hari kiamat itu akan datang Aku merahasiakan waktunya) dari manusia dan menampakkan kepada mereka hanya dekatnya hari kiamat melalui alamat-alamatnya supaya mendapatkan balasan) di hari itu (tiap-tiap diri itu dengan apa yang ia usahakan) apakah kebaikan ataukah keburukan.",[["إِنَّ","Indeed"],["ٱلسَّاعَةَ","the Hour"],["ءَاتِيَةٌ","(will be) coming"],["أَكَادُ","I almost"],["أُخْفِيهَا","[I] hide it"],["لِتُجْزَىٰ","that may be recompensed"],["كُلُّ","every"],["نَفْسٍۭ","soul"],["بِمَا","for what"],["تَسْعَىٰ","it strives"]]],"2364":["(Maka sekali-kali janganlah kamu dipalingkan) dibelokkan (daripadanya) dari iman kepada adanya hari kiamat (oleh orang yang tidak beriman kepadanya dan oleh orang yang mengikuti hawa nafsunya) untuk ingkar kepada adanya hari kiamat (yang menyebabkan kamu jadi binasa\") sedangkan mereka pasti akan binasa.",[["فَلَا","So (do) not"],["يَصُدَّنَّكَ","(let) avert you"],["عَنْهَا","from it"],["مَن","(one) who"],["لَّا","(does) not"],["يُؤْمِنُ","believe"],["بِهَا","in it"],["وَٱتَّبَعَ","and follows"],["هَوَىٰهُ","his desires"],["فَتَرْدَىٰ","lest you perish"]]],"2365":["(Apakah itu) yang berada (di tangan kananmu, hai Musa?) Kata tanya atau Istifham di sini mengandung makna Taqrir, maksudnya supaya Allah menurunkan mukjizat kepada Nabi Musa dengan melalui tongkatnya itu.",[["وَمَا","And what"],["تِلْكَ","(is) that"],["بِيَمِينِكَ","in your right hand"],["يَـٰمُوسَىٰ","O Musa"]]],"2366":["(Berkata Musa, \"Ini adalah tongkatku, aku bertelekan) berpegangan (padanya) sewaktu aku melompat dan berjalan (dan aku pukul) aku memukul daun-daun pohon (dengannya) supaya daun-daun itu berjatuhan (untuk kambingku) lalu kambing-kambingku itu memakannya (dan bagiku ada lagi padanya keperluan). Lafal Ma'aarib adalah bentuk jamak dari lafal Ma'ribah atau Ma'rabah atau Ma'rubah, artinya keperluan-keperluan (yang lain\") seperti untuk memikul bekal dan air minum, serta untuk mengusir binatang buas. Kemudian Allah menambahkan jawaban, sebagai penjelasan bahwa pada tongkat itu masih terdapat kegunaan lainnya, yaitu:",[["قَالَ","He said"],["هِىَ","It"],["عَصَاىَ","(is) my staff"],["أَتَوَكَّؤُا۟","I lean"],["عَلَيْهَا","upon it"],["وَأَهُشُّ","and I bring down leaves"],["بِهَا","with it"],["عَلَىٰ","for"],["غَنَمِى","my sheep"],["وَلِىَ","and for me"],["فِيهَا","in it"],["مَـَٔارِبُ","(are) uses"],["أُخْرَىٰ","other"]]],"2367":["(Allah berfirman, \"Lemparkanlah tongkat itu, hai Musa!\")",[["قَالَ","He said"],["أَلْقِهَا","Throw it down"],["يَـٰمُوسَىٰ","O Musa"]]],"2368":["(Lalu dilemparkannyalah tongkat itu, maka tiba-tiba ia menjadi seekor ular) yang sangat besar (yang merayap) yakni berjalan cepat dengan perutnya seperti ular kecil, di dalam ayat lain disebutkan Al Jaan, bukan Hayyatun.",[["فَأَلْقَىٰهَا","So he threw it down"],["فَإِذَا","and behold"],["هِىَ","It"],["حَيَّةٌۭ","(was) a snake"],["تَسْعَىٰ","moving swiftly"]]],"2369":["(Allah berfirman, \"Peganglah ia dan jangan takut) kepadanya (Kami akan mengembalikannya kepada keadaannya) lafal Siiratahaa dinashabkan dengan mencabut huruf Jarnya, maksudnya ke dalam bentuknya (yang semula) kemudian Nabi Musa memasukkan tangannya ke mulut ular besar itu, maka kembalilah kepada keadaan semula yaitu menjadi tongkat lagi. Jelaslah bahwa tempat untuk memasukkan tangannya adalah tempat pegangan tongkat, yaitu di antara kedua rahang ular tersebut. Allah swt. sengaja memperlihatkan hal itu kepada Nabi Musa, supaya ia jangan kaget bila tongkat itu berubah menjadi ular besar di hadapan raja Firaun nanti.",[["قَالَ","He said"],["خُذْهَا","Seize it"],["وَلَا","and (do) not"],["تَخَفْ ۖ","fear"],["سَنُعِيدُهَا","We will return it"],["سِيرَتَهَا","(to) its state"],["ٱلْأُولَىٰ","the former"]]],"2370":["(Dan kepitkanlah tanganmu) yang sebelah kanan, yang dimaksud adalah telapak tangannya (ke ketiakmu) yakni dijepitkan pada tubuhmu yang sebelah kiri, yaitu pada tempat antara ketiak dan lenganmu, kemudian keluarkanlah ia (niscaya ia keluar) dalam keadaan berbeda dengan warna kulit yang sebelumnya, yaitu (menjadi putih cemerlang tanpa cacat) putih bersinar dengan cemerlang sebagaimana sinar matahari, dan sinarnya itu menyilaukan pandangan mata (sebagai mukjizat yang lain) tangan itu bisa menjadi putih bersinar; lafal Baidhaa'a dan lafal Aayatan Ukhraa keduanya menjadi Hal atau kata keterangan keadaan bagi Dhamir yang terkandung di dalam lafal Takhruj.",[["وَٱضْمُمْ","And draw near"],["يَدَكَ","your hand"],["إِلَىٰ","to"],["جَنَاحِكَ","your side"],["تَخْرُجْ","it will come out"],["بَيْضَآءَ","white"],["مِنْ","without any"],["غَيْرِ","without any"],["سُوٓءٍ","disease"],["ءَايَةً","(as) a sign"],["أُخْرَىٰ","another"]]],"2371":["(Untuk Kami perlihatkan kepadamu) Kami sengaja melakukan hal itu bilamana kamu sewaktu-waktu mau menggunakannya, untuk memperlihatkan kepadamu (sebagian tanda-tanda kekuasaan Kami) bukti kekuasaan Kami (yang sangat besar) bukti yang besar bagi kerasulanmu. Apabila Nabi Musa hendak mengembalikan tangannya seperti semula, maka ia mengepitkannya lagi pada ketiaknya seperti yang dilakukannya semula, kemudian mengeluarkannya kembali.",[["لِنُرِيَكَ","That We may show you"],["مِنْ","of"],["ءَايَـٰتِنَا","Our Signs"],["ٱلْكُبْرَى","the Greatest"]]],"2372":["(Pergilah) sebagai seorang Rasul (kepada Firaun) dan orang-orang yang mengikutinya (sesungguhnya ia telah melampaui batas)\" sangat keterlaluan di dalam kekafirannya, hingga ia berani mengaku menjadi tuhan.",[["ٱذْهَبْ","Go"],["إِلَىٰ","to"],["فِرْعَوْنَ","Firaun"],["إِنَّهُۥ","Indeed, he"],["طَغَىٰ","(has) transgressed"]]],"2373":["(Berkata Musa, \"Ya Rabbku! Lapangkanlah untukku dadaku,) maksudnya lapangkanlah dadaku supaya mampu mengemban risalah-Mu.",[["قَالَ","He said"],["رَبِّ","My Lord"],["ٱشْرَحْ","Expand"],["لِى","for me"],["صَدْرِى","my breast"]]],"2374":["(Dan mudahkanlah) permudahlah (untukku urusanku) supaya aku dapat menyampaikannya.",[["وَيَسِّرْ","And ease"],["لِىٓ","for me"],["أَمْرِى","my task"]]],"2375":["(Dan lepaskanlah kekakuan dari lidahku) keadaan ini terjadi sejak lidahnya terbakar bara api yang ia masukkan ke dalam mulutnya sewaktu masih kecil.",[["وَٱحْلُلْ","And untie"],["عُقْدَةًۭ","(the) knot"],["مِّن","from"],["لِّسَانِى","my tongue"]]],"2376":["(Supaya mereka mengerti) yakni dapat memahami (perkataanku) di waktu aku menyampaikan risalah kepada mereka.",[["يَفْقَهُوا۟","That they may understand"],["قَوْلِى","my speech"]]],"2377":["(Dan jadikanlah untukku seorang pembantu) orang yang membantuku di dalam menyampaikan risalah-Mu (dari keluargaku).",[["وَٱجْعَل","And appoint"],["لِّى","for me"],["وَزِيرًۭا","a minister"],["مِّنْ","from"],["أَهْلِى","my family"]]],"2378":["(Yaitu Harun) lafal Haaruna menjadi Maf'ul Tsani (saudaraku) lafal Akhii menjadi 'Athaf Rayan.",[["هَـٰرُونَ","Harun"],["أَخِى","my brother"]]],"2379":["(Teguhkanlah dengan dia kekuatanku) kemampuanku.",[["ٱشْدُدْ","Reinforce"],["بِهِۦٓ","through him"],["أَزْرِى","my strength"]]],"2380":["(Dan jadikanlah ia sekutu dalam urusanku) yakni ikut mengemban risalah ini. Kedua Fi'il tadi yaitu Usydud dan Asyrik dapat pula dibaca sebagai Fi'il Mudhari' yang dijazamkan sehingga menjadi Asydud Bihi dan Usyrik-hu, keduanya merupakan Jawab dari Thalab atau permintaan.",[["وَأَشْرِكْهُ","And make him share"],["فِىٓ","[in]"],["أَمْرِى","my task"]]],"2381":["(Supaya kami dapat bertasbih kepada-Mu) yakni melakukan tasbih (dengan banyak).",[["كَىْ","That"],["نُسَبِّحَكَ","we may glorify You"],["كَثِيرًۭا","much"]]],"2382":["(Dan dapat mengingat-Mu) berzikir kepada-Mu (dengan banyak pula).",[["وَنَذْكُرَكَ","And [we] remember You"],["كَثِيرًا","much"]]],"2383":["(Sesungguhnya Engkau adalah Maha Mengetahui keadaan kami)\" Maha Mengetahuinya, oleh sebab itu maka Engkau akan memberikan nikmat-Mu kepadaku dengan mengangkat Harun menjadi Rasul.",[["إِنَّكَ","Indeed, [You]"],["كُنتَ","You are"],["بِنَا","of us"],["بَصِيرًۭا","All-Seer"]]],"2384":["(Allah berfirman, \"Sesungguhnya telah dikabulkan permintaanmu, hai Musa) sebagai anugerah Kami kepadamu.",[["قَالَ","He said"],["قَدْ","Verily"],["أُوتِيتَ","you are granted"],["سُؤْلَكَ","your request"],["يَـٰمُوسَىٰ","O Musa"]]],"2385":["(Dan sesungguhnya Kami telah memberi nikmat kepadamu pada kali yang lain).",[["وَلَقَدْ","And indeed"],["مَنَنَّا","We conferred a favor"],["عَلَيْكَ","on you"],["مَرَّةً","another time"],["أُخْرَىٰٓ","another time"]]],"2386":["(Yaitu ketika) lafal Idz di sini mengandung makna Ta'lil (mengilhamkan kepada ibumu) di dalam mimpi, atau berupa inspirasi, yaitu sewaktu ibumu melahirkan dirimu, dan ia merasa khawatir Firaun akan membunuhmu bersama-sama dengan anak-anak lelaki lainnya yang baru dilahirkan saat itu (suatu yang diilhamkan\") mengenai urusanmu. Selanjutnya dijelaskan ilham tersebut dalam firman selanjutnya:",[["إِذْ","When"],["أَوْحَيْنَآ","We inspired"],["إِلَىٰٓ","to"],["أُمِّكَ","your mother"],["مَا","what"],["يُوحَىٰٓ","is inspired"]]],"2387":["(Yaitu, \"Letakkanlah ia) tarohlah ia (di dalam sebuah peti, kemudian lemparkanlah ia) yakni peti itu (ke sungai) yakni sungai Nil (maka pasti sungai itu membawanya ke tepi) ke pinggirnya. Kata perintah di sini mengandung makna kalimat berita (supaya diambil oleh musuh-Ku dan musuhnya) yaitu raja Firaun. (Dan Aku telah melimpahkan) sesudah Firaun mengambil anakmu darimu (kepadamu kasih sayang yang datang daripada-Ku) supaya semua orang merasa kasih sayang kepadamu, lalu Firaun akan merasa sayang kepadamu, demikian pula setiap orang yang melihatmu (dan supaya kamu diasuh di bawah pengawasan-Ku) kamu dipelihara di bawah asuhan dan penjagaan-Ku.",[["أَنِ","That"],["ٱقْذِفِيهِ","cast him"],["فِى","in"],["ٱلتَّابُوتِ","the chest"],["فَٱقْذِفِيهِ","then cast it"],["فِى","in"],["ٱلْيَمِّ","the river"],["فَلْيُلْقِهِ","then let cast it"],["ٱلْيَمُّ","the river"],["بِٱلسَّاحِلِ","on the bank"],["يَأْخُذْهُ","will take him"],["عَدُوٌّۭ","an enemy"],["لِّى","to Me"],["وَعَدُوٌّۭ","and an enemy"],["لَّهُۥ ۚ","to him"],["وَأَلْقَيْتُ","And I cast"],["عَلَيْكَ","over you"],["مَحَبَّةًۭ","love"],["مِّنِّى","from Me"],["وَلِتُصْنَعَ","and that you may be brought up"],["عَلَىٰ","under"],["عَيْنِىٓ","My eye"]]],"2388":["(Yaitu ketika) lafal Idz di sini bermakna Ta'lil (saudaramu yang perempuan berjalan) namanya Maryam untuk menyelidiki beritamu. Karena sesungguhnya Firaun dan keluarganya telah mendatangkan orang-orang perempuan yang menyusui, sedangkan kamu tidak mau menerima air susu seorang pun di antara mereka (lalu ia berkata, 'Bolehkah saya menunjukkan kepada kalian orang yang akan memeliharanya?') kemudian usulnya itu ternyata diperkenankan oleh keluarga Firaun, maka segera Maryam mendatangkan ibunya, lalu Nabi Musa mau menerima air susunya. (Maka Kami mengembalikanmu kepada ibumu, agar senang hatinya) karena bertemu kembali denganmu (dan tidak berduka cita) sejak saat itu. (Dan kamu pernah membunuh seorang manusia) yaitu seorang bangsa Qibti di Mesir. Maka kamu merasa susah dan khawatir setelah membunuh orang itu terhadap pembalasan raja Firaun (lalu Kami selamatkan kamu dari kesusahan dan Kami telah mencobamu dengan beberapa cobaan) Kami telah mengujimu dengan beberapa cobaan selain dari peristiwa itu, kemudian Kami selamatkan pula kamu daripadanya (maka kamu tinggal beberapa tahun) yakni selama sepuluh tahun (di antara penduduk Madyan) sesudah kamu datang ke tempat itu dari negeri Mesir, yaitu kamu tinggal di tempat Nabi Syuaib yang kemudian ia mengawinkanmu dengan putrinya (kemudian kamu datang menurut waktu yang ditetapkan) di dalam ilmu-Ku dengan membawa risalah, yaitu dalam usia empat puluh tahun (hai Musa!).",[["إِذْ","When"],["تَمْشِىٓ","was going"],["أُخْتُكَ","your sister"],["فَتَقُولُ","and she said"],["هَلْ","Shall"],["أَدُلُّكُمْ","I show you"],["عَلَىٰ","[to]"],["مَن","(one) who"],["يَكْفُلُهُۥ ۖ","will nurse and rear him"],["فَرَجَعْنَـٰكَ","So We returned you"],["إِلَىٰٓ","to"],["أُمِّكَ","your mother"],["كَىْ","that"],["تَقَرَّ","may be cooled"],["عَيْنُهَا","her eyes"],["وَلَا","and not"],["تَحْزَنَ ۚ","she grieves"],["وَقَتَلْتَ","And you killed"],["نَفْسًۭا","a man"],["فَنَجَّيْنَـٰكَ","but We saved you"],["مِنَ","from"],["ٱلْغَمِّ","the distress"],["وَفَتَنَّـٰكَ","and We tried you"],["فُتُونًۭا ۚ","(with) a trial"],["فَلَبِثْتَ","Then you remained"],["سِنِينَ","(some) years"],["فِىٓ","with"],["أَهْلِ","(the) people"],["مَدْيَنَ","(of) Madyan"],["ثُمَّ","Then"],["جِئْتَ","you came"],["عَلَىٰ","at"],["قَدَرٍۢ","the decreed (time)"],["يَـٰمُوسَىٰ","O Musa"]]],"2389":["(Dan Aku telah memilihmu) telah menjadikanmu sebagai orang yang terpilih (untuk diri-Ku) untuk mengemban risalah.",[["وَٱصْطَنَعْتُكَ","And I (have) chosen you"],["لِنَفْسِى","for Myself"]]],"2390":["(Pergilah kamu beserta saudaramu) kepada manusia (dengan membawa ayat-ayat-Ku) yang berjumlah sembilan ayat (dan janganlah kamu berdua lalai) melalaikan (dalam mengingat-Ku) yaitu dengan cara bertasbih dan cara-cara lainnya.",[["ٱذْهَبْ","Go"],["أَنتَ","you"],["وَأَخُوكَ","and your brother"],["بِـَٔايَـٰتِى","with My Signs"],["وَلَا","and (do) not"],["تَنِيَا","slacken"],["فِى","in"],["ذِكْرِى","My remembrance"]]],"2391":["(Pergilah kamu berdua kepada Firaun, sesungguhnya dia telah melampaui batas) karena ia mengaku menjadi tuhan.",[["ٱذْهَبَآ","Go, both of you"],["إِلَىٰ","to"],["فِرْعَوْنَ","Firaun"],["إِنَّهُۥ","Indeed, he"],["طَغَىٰ","(has) transgressed"]]],"2392":["(Maka berbicaralah kamu berdua kepadanya dengan kata-kata yang lemah lembut) untuk menyadarkannya supaya jangan mengaku menjadi tuhan (mudah-mudahan ia ingat) yakni sadar dan mau menerimanya (atau takut\") kepada Allah lalu karenanya ia mau sadar. Ungkapan 'mudah-mudahan' berkaitan dengan pengetahuan Nabi Musa dan Nabi Harun. Adapun menurut pengetahuan Allah, maka Dia telah mengetahui bahwa Firaun tidak akan mau sadar dari perbuatannya.",[["فَقُولَا","And speak"],["لَهُۥ","to him"],["قَوْلًۭا","a word"],["لَّيِّنًۭا","gentle"],["لَّعَلَّهُۥ","perhaps he"],["يَتَذَكَّرُ","may take heed"],["أَوْ","or"],["يَخْشَىٰ","fear"]]],"2393":["(Berkatalah mereka berdua, \"Ya Rabb kami! Sesungguhnya kami khawatir bahwa ia segera menyiksa kami) mengambil keputusan yang cepat untuk menyiksa kami (atau akan bertambah melampaui batas\") terhadap kami, yakni bertambah takabbur.",[["قَالَا","They said"],["رَبَّنَآ","Our Lord"],["إِنَّنَا","Indeed, we"],["نَخَافُ","fear"],["أَن","that"],["يَفْرُطَ","he will hasten"],["عَلَيْنَآ","against us"],["أَوْ","or"],["أَن","that"],["يَطْغَىٰ","he will transgress"]]],"2394":["(Allah berfirman, \"Janganlah kamu berdua takut sesungguhnya Aku beserta kamu berdua) Aku akan membantu kamu berdua (Aku mendengar) apa yang dikatakannya (dan melihat) apa yang dikerjakannya.",[["قَالَ","He said"],["لَا","(Do) not"],["تَخَافَآ ۖ","fear"],["إِنَّنِى","Indeed, I Am"],["مَعَكُمَآ","with you both"],["أَسْمَعُ","I hear"],["وَأَرَىٰ","and I see"]]],"2395":["(Maka datanglah kamu berdua kepadanya dan katakanlah, \" Sesungguhnya kami berdua adalah utusan Rabbmu, maka lepaskanlah Bani Israel bersama kami) untuk berangkat ke negeri Syam (dan janganlah kamu menyiksa mereka) lepaskanlah mereka dari perbudakanmu yang telah kamu pekerjakan dengan kerja-kerja yang berat seperti menggali, membangun bangunan dan mengangkat barang-barang yang berat. (Sesungguhnya kami telah datang kepadamu dengan membawa bukti) yakni hujah (dari Rabbmu) yang membenarkan kerasulan kami. (Dan keselamatan itu dilimpahkan kepada orang yang mengikuti petunjuk) keselamatan dari azab bagi orang yang mengikutinya.",[["فَأْتِيَاهُ","So go to him"],["فَقُولَآ","and say"],["إِنَّا","Indeed, we"],["رَسُولَا","both (are) Messengers"],["رَبِّكَ","(of) your Lord"],["فَأَرْسِلْ","so send"],["مَعَنَا","with us"],["بَنِىٓ","(the) Children of Israel"],["إِسْرَٰٓءِيلَ","(the) Children of Israel"],["وَلَا","and (do) not"],["تُعَذِّبْهُمْ ۖ","torment them"],["قَدْ","Verily"],["جِئْنَـٰكَ","we came to you"],["بِـَٔايَةٍۢ","with a Sign"],["مِّن","from"],["رَّبِّكَ ۖ","your Lord"],["وَٱلسَّلَـٰمُ","And peace"],["عَلَىٰ","on"],["مَنِ","(one) who"],["ٱتَّبَعَ","follows"],["ٱلْهُدَىٰٓ","the Guidance"]]],"2396":["(Sesungguhnya telah diwahyukan kepada kami, bahwa siksa itu ditimpakan kepada orang-orang yang mendustakan) apa yang kami datangkan ini (dan berpaling\") daripadanya. Kemudian Nabi Musa dan Nabi Harun mendatangi Firaun dan keduanya mengatakan semuanya itu kepadanya.",[["إِنَّا","Indeed, we"],["قَدْ","verily"],["أُوحِىَ","it has been revealed"],["إِلَيْنَآ","to us"],["أَنَّ","that"],["ٱلْعَذَابَ","the punishment"],["عَلَىٰ","(will be) on"],["مَن","(one) who"],["كَذَّبَ","denies"],["وَتَوَلَّىٰ","and turns away"]]],"2397":["(Berkata Firaun, \"Maka siapakah Rabbmu berdua, hai Musa?\") ungkapan ini ditujukan kepada Nabi Musa, karena dialah asal pembawa risalah Allah dan yang mendapatkan pemeliharaan dari-Nya.",[["قَالَ","He said"],["فَمَن","Then who"],["رَّبُّكُمَا","(is) your Lord"],["يَـٰمُوسَىٰ","O Musa"]]],"2398":["(Musa berkata, \"Rabb kami ialah yang telah memberikan kepada tiap-tiap sesuatu) yakni tiap-tiap makhluk (bentuk kejadiannya) yang membedakannya daripada makhluk yang lain (kemudian memberinya petunjuk\") sehingga mengetahui makanan, minuman dan cara mengembangkan keturunannya serta hal-hal lain yang menyangkut kehidupannya.",[["قَالَ","He said"],["رَبُّنَا","Our Lord"],["ٱلَّذِىٓ","(is) the One Who"],["أَعْطَىٰ","gave"],["كُلَّ","(to) every"],["شَىْءٍ","thing"],["خَلْقَهُۥ","its form"],["ثُمَّ","then"],["هَدَىٰ","He guided (it)"]]],"2399":["(Berkatalah ia) yakni Firaun, (\"Maka bagaimanakah) keadaan (umat-umat) yakni bangsa-bangsa (yang dahulu?\") seperti kaum Nabi Nuh, kaum Nabi Hud, kaum Nabi Luth dan kaum Nabi Saleh, tentang penyembahan mereka kepada berhala-berhala.",[["قَالَ","He said"],["فَمَا","Then what"],["بَالُ","(is the) case"],["ٱلْقُرُونِ","(of) the generations"],["ٱلْأُولَىٰ","(of) the former"]]],"2400":["(Ia berkata) yakni Nabi Musa, (\"Pengetahuan tentang itu) pengetahuan mengenai keadaan mereka berada (di sisi Rabbku, di dalam sebuah kitab) yaitu Lohmahfuz; Dia akan membalas mereka kelak di hari kiamat. (Tidak akan salah) tidak akan lenyap (dari Rabbku) segala sesuatu (dan tidak pula lupa) akan sesuatu.",[["قَالَ","He said"],["عِلْمُهَا","Its knowledge"],["عِندَ","(is) with"],["رَبِّى","my Lord"],["فِى","in"],["كِتَـٰبٍۢ ۖ","a Record"],["لَّا","Not"],["يَضِلُّ","errs"],["رَبِّى","my Lord"],["وَلَا","and not"],["يَنسَى","forgets"]]],"2401":["Dia (yang telah menjadikan bagi kalian) di antara sekian banyak makhluk-Nya (bumi sebagai hamparan) tempat berpijak (dan Dia memudahkan) mempermudah (bagi kalian di bumi itu jalan-jalan) tempat-tempat untuk berjalan (dan Dia menurunkan dari langit air hujan) yakni merupakan hujan. Allah berfirman menggambarkan apa yang telah disebutkan-Nya itu sebagai nikmat dari-Nya, kepada Nabi Musa dan dianggap sebagai khithab untuk penduduk Mekah. (Maka Kami tumbuhkan dengan air hujan itu berjenis-jenis) bermacam-macam (tumbuh-tumbuhan yang beraneka ragam). Lafal Syattaa ini menjadi kata sifat daripada lafal Azwaajan, maksudnya, yang berbeda-beda warna dan rasa serta lain-lainnya. Lafal syattaa ini adalah bentuk jamak dari lafal Syatiitun, wazannya sama dengan lafal Mardhaa sebagai jamak dari lafal Mariidhun. Ia berasal dari kata kerja Syatta artinya Tafarraqa atau berbeda-beda.",[["ٱلَّذِى","The One Who"],["جَعَلَ","made"],["لَكُمُ","for you"],["ٱلْأَرْضَ","the earth"],["مَهْدًۭا","(as) a bed"],["وَسَلَكَ","and inserted"],["لَكُمْ","for you"],["فِيهَا","therein"],["سُبُلًۭا","ways"],["وَأَنزَلَ","and sent down"],["مِنَ","from"],["ٱلسَّمَآءِ","the sky"],["مَآءًۭ","water"],["فَأَخْرَجْنَا","then We (have) brought forth"],["بِهِۦٓ","with it"],["أَزْوَٰجًۭا","pairs"],["مِّن","of"],["نَّبَاتٍۢ","plants"],["شَتَّىٰ","diverse"]]],"2402":["(Makanlah) daripadanya (dan gembalakanlah ternak kalian) di dalamnya. Lafal An'am adalah bentuk jamak dari lafal Ni'amun, yang artinya mencakup unta, sapi dan kambing. Dikatakan, Ru'tul An'aama atau aku menggembalakan ternak dan Ra'aituhaa atau aku telah menggembalakannya. Pengertian yang terkandung di dalam perintah ini menunjukkan makna ibahah atau boleh dan sekaligus sebagai pengingat akan nikmat-nikmat-Nya. Jumlah keseluruhan ayat ini menjadi kata keterangan keadaan daripada Dhamir yang terkandung di dalam lafal Akhrajnaa. Maksudnya, Kami memperbolehkan bagi kalian untuk memakannya dan mengembalakan ternak padanya. (sesungguhnya pada yang demikian itu) yakni pada hal-hal yang telah disebutkan dalam ayat ini (terdapat tanda-tanda) pelajaran-pelajaran (bagi orang-orang yang berakal) lafal Nuhaa adalah bentuk jamak dan lafal Nuhyah, wazannya sama dengan lafal Ghurfah yang jamaknya Ghuraf. Akal dinamakan dengan istilah ini, karena dapat mencegah pemiliknya dari melakukan perbuatan-perbuatan yang buruk.",[["كُلُوا۟","Eat"],["وَٱرْعَوْا۟","and pasture"],["أَنْعَـٰمَكُمْ ۗ","your cattle"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","surely (are) Signs"],["لِّأُو۟لِى","for possessors"],["ٱلنُّهَىٰ","(of) intelligence"]]],"2403":["(Dari bumi itulah) dari tanah (Kami menjadikan kalian) dengan menciptakan nenek moyang kalian Adam daripadanya (dan kepadanya Kami akan mengembalikan kalian) kalian akan dikuburkan di dalamnya sesudah mati (dan daripadanya Kami akan mengeluarkan kalian) pada hari berbangkit (pada kali) untuk kali (yang lain) sebagaimana Kami mengeluarkan kalian pada permulaan penciptaan kalian.",[["۞ مِنْهَا","From it"],["خَلَقْنَـٰكُمْ","We created you"],["وَفِيهَا","and in it"],["نُعِيدُكُمْ","We will return you"],["وَمِنْهَا","and from it"],["نُخْرِجُكُمْ","We will bring you out"],["تَارَةً","time"],["أُخْرَىٰ","another"]]],"2404":["(Dan sesungguhnya telah Kami perlihatkan kepadanya) kepada Firaun (ayat-ayat Kami semuanya) yang berjumlah sembilan ayat itu (maka ia mendustakan) nya dan menuduh bahwa ayat-ayat itu adalah sihir (dan ia enggan) untuk mengesakan Allah swt.",[["وَلَقَدْ","And verily"],["أَرَيْنَـٰهُ","We showed him"],["ءَايَـٰتِنَا","Our Signs"],["كُلَّهَا","all of them"],["فَكَذَّبَ","but he denied"],["وَأَبَىٰ","and refused"]]],"2405":["(Berkata Firaun, \"Adakah kamu datang kepada kami untuk mengusir kami dari negeri kami) yakni dari negeri Mesir, kemudian kamu menjadi raja padanya (dengan sihirmu, hai Musa?\")",[["قَالَ","He said"],["أَجِئْتَنَا","Have you come to us"],["لِتُخْرِجَنَا","to drive us out"],["مِنْ","of"],["أَرْضِنَا","our land"],["بِسِحْرِكَ","with your magic"],["يَـٰمُوسَىٰ","O Musa"]]],"2406":["(\"Dan kami pun pasti akan mendatangkan pula kepadamu sihir semacam itu) yang akan melawannya (maka buatlah suatu waktu antara kami dan kamu) untuk pertemuan itu (yang kami tidak akan menyalahinya dan tidak pula kamu, di suatu tempat) lafal Makaanan ini dinashabkan dengan mencabut huruf Jarnya, maksudnya, di tempat (yang pertengahan\") lafal Suwan dapat pula dibaca Siwan, artinya, tempat yang letaknya pertengahan, dari arah mana saja didatangi oleh kedua pihak jaraknya sama.",[["فَلَنَأْتِيَنَّكَ","Then we will surely produce for you"],["بِسِحْرٍۢ","magic"],["مِّثْلِهِۦ","like it"],["فَٱجْعَلْ","So make"],["بَيْنَنَا","between us"],["وَبَيْنَكَ","and between you"],["مَوْعِدًۭا","an appointment"],["لَّا","not"],["نُخْلِفُهُۥ","we will fail it"],["نَحْنُ","[we]"],["وَلَآ","and not"],["أَنتَ","you"],["مَكَانًۭا","(in) a place"],["سُوًۭى","even"]]],"2407":["(Berkatalah ia) Nabi Musa, (\"Waktu untuk pertemuan kami dengan kalian itu adalah hari raya) yakni hari raya Firaun dan kaumnya, yang pada hari itu mereka berhias diri dan berkumpul-kumpul (dan hendaklah dikumpulkan manusia) semua penduduk negeri Mesir dikumpulkan (pada waktu matahari naik sepenggalah\") untuk menyaksikan apa yang akan terjadi.",[["قَالَ","He said"],["مَوْعِدُكُمْ","Your appointment"],["يَوْمُ","(is on the) day"],["ٱلزِّينَةِ","(of) the festival"],["وَأَن","and that"],["يُحْشَرَ","will be assembled"],["ٱلنَّاسُ","the people"],["ضُحًۭى","(at) forenoon"]]],"2408":["(Maka Firaun meninggalkan) pergi meninggalkan tempat itu (lalu ia mengatur tipu muslihatnya) ia mulai mengumpulkan para ahli sihirnya (kemudian ia datang) bersama mereka pada waktu yang telah ditentukan itu.",[["فَتَوَلَّىٰ","Then went away"],["فِرْعَوْنُ","Firaun"],["فَجَمَعَ","and put together"],["كَيْدَهُۥ","his plan"],["ثُمَّ","then"],["أَتَىٰ","came"]]],"2409":["(Berkata Musa kepada mereka,) jumlah para ahli sihir Firaun ada tujuh puluh dua orang; setiap orang dari mereka memegang tali dan tongkat (\"Celakalah kalian) maksudnya semoga Allah menimpakan kecelakaan kepada kalian (janganlah kalian mengada-adakan kedustaan terhadap Allah) dengan menyekutukan seseorang bersama-Nya (maka Dia membinasakan kalian) ia dapat dibaca Fayushitakum dan Fayashitakum, artinya Dia akan membinasakan kalian, karena perbuatan musyrik itu (dengan siksa\") dari sisi-Nya. (Dan sesungguhnya telah kecewa) merugi (orang yang mengada-adakan kedustaan) terhadap Allah.",[["قَالَ","Said"],["لَهُم","to them"],["مُّوسَىٰ","Musa"],["وَيْلَكُمْ","Woe to you"],["لَا","(Do) not"],["تَفْتَرُوا۟","invent"],["عَلَى","against"],["ٱللَّهِ","Allah"],["كَذِبًۭا","a lie"],["فَيُسْحِتَكُم","lest He will destroy you"],["بِعَذَابٍۢ ۖ","with a punishment"],["وَقَدْ","And verily"],["خَابَ","he failed"],["مَنِ","who"],["ٱفْتَرَىٰ","invented"]]],"2410":["(Maka mereka berbantah-bantahan di antara mereka tentang urusannya) yakni mengenai Nabi Musa dan saudaranya itu (dan mereka merahasiakan percakapan) mereka yang menyangkut Nabi Musa dan Nabi Harun.",[["فَتَنَـٰزَعُوٓا۟","Then they disputed"],["أَمْرَهُم","(in) their affair"],["بَيْنَهُمْ","among them"],["وَأَسَرُّوا۟","and they kept secret"],["ٱلنَّجْوَىٰ","the private conversation"]]],"2411":["(Mereka berkata) kepada diri mereka sendiri, (\"Sesungguhnya dua orang ini) ungkapan Haadzaani dijadikan hujah atau alasan bagi sebagian ahli Nahwu yang menetapkan huruf Alif pada isim Tatsniyah dalam tiga keadaan. Akan tetapi menurut qiraat Abu 'Amr, lafal Haadzaani ini dibaca Haadzaini (adalah benar-benar ahli sihir yang hendak mengusir kalian, dari negeri kalian dengan sihirnya dan hendak melenyapkan kedudukan kalian yang utama\") lafal Mutslaa adalah bentuk Muannats dari lafal Amtsal; maksudnya yang mulia. Artinya, keduanya akan melenyapkan kemuliaan kalian, bila mereka berdua dibiarkan menang, kemudian kalian cenderung kepada keduanya.",[["قَالُوٓا۟","They said"],["إِنْ","Indeed"],["هَـٰذَٰنِ","these two"],["لَسَـٰحِرَٰنِ","[two] magicians"],["يُرِيدَانِ","they intend"],["أَن","that"],["يُخْرِجَاكُم","they drive you out"],["مِّنْ","of"],["أَرْضِكُم","your land"],["بِسِحْرِهِمَا","with their magic"],["وَيَذْهَبَا","and do away"],["بِطَرِيقَتِكُمُ","with your way"],["ٱلْمُثْلَىٰ","the exemplary"]]],"2412":["(\"Maka himpunkanlah segala daya upaya kalian) semua kekuatan dan keahlian sihir kalian. Kalau dibaca Fajma'uu berasal dari lafal Jama'a dan kalau dibaca Fa-ajmi'uu berasal dari lafal Ajma'a, artinya kerahkanlah (kemudian datanglah dengan berbaris). Lafal Shaffan adalah Hal atau kata keterangan keadaan, maksudnya dalam keadaan berbaris (dan sesungguhnya beruntunglah) yakni akan memperoleh keuntungan (orang yang menang pada hari ini\") yakni yang dapat mengalahkan musuhnya.",[["فَأَجْمِعُوا۟","So put together"],["كَيْدَكُمْ","your plan"],["ثُمَّ","then"],["ٱئْتُوا۟","come"],["صَفًّۭا ۚ","(in) a line"],["وَقَدْ","And verily"],["أَفْلَحَ","(will be) successful"],["ٱلْيَوْمَ","today"],["مَنِ","who"],["ٱسْتَعْلَىٰ","overcomes"]]],"2413":["(Mereka berkata, \"Hai Musa!) Pilihlah (apakah kamu yang melemparkan dahulu) tongkatmu (atau kamikah orang yang mula-mula melemparkan?\") tongkat.",[["قَالُوا۟","They said"],["يَـٰمُوسَىٰٓ","O Musa"],["إِمَّآ","Either"],["أَن","[that]"],["تُلْقِىَ","you throw"],["وَإِمَّآ","or"],["أَن","[that]"],["نَّكُونَ","we will be"],["أَوَّلَ","the first"],["مَنْ","who"],["أَلْقَىٰ","throws"]]],"2414":["(Berkata Musa, \"Silakan kamu sekalian melemparkan\") maka mereka melemparkannya. (Maka tiba-tiba tali-tali dan tongkat-tongkat mereka) asal kata 'Ishiyyun adalah 'Ushuwwun, kemudian kedua huruf Wawu ditukar menjadi Ya, selanjutnya harakat huruf 'Ain dan Shad dikasrahkan, maka menjadi 'Ishiyyun (terbayang kepada Musa seakan-akan karena pengaruh sihir mereka ia) merupakan ular-ular (yang berjalan) atau merayap pada perutnya.",[["قَالَ","He said"],["بَلْ","Nay"],["أَلْقُوا۟ ۖ","you throw"],["فَإِذَا","Then behold"],["حِبَالُهُمْ","Their ropes"],["وَعِصِيُّهُمْ","and their staffs"],["يُخَيَّلُ","seemed"],["إِلَيْهِ","to him"],["مِن","by"],["سِحْرِهِمْ","their magic"],["أَنَّهَا","that they"],["تَسْعَىٰ","(were) moving"]]],"2415":["(Maka timbullah perasaan) muncul perasaan (takut dalam hati Musa) dia merasa takut karena ternyata sihir mereka sejenis dengan mukjizatnya, sehingga akibatnya akan mengaburkan mana yang hak dan mana yang batil di mata orang banyak, yang nantinya mereka tidak mau beriman, disebabkan kejadian itu.",[["فَأَوْجَسَ","So sensed"],["فِى","in"],["نَفْسِهِۦ","himself"],["خِيفَةًۭ","a fear"],["مُّوسَىٰ","Musa"]]],"2416":["(Kami berkata) kepada Musa, (\"Janganlah kamu takut, sesungguhnya kamulah yang paling unggul) kamulah yang akan mengungguli mereka.",[["قُلْنَا","We said"],["لَا","(Do) not"],["تَخَفْ","fear"],["إِنَّكَ","Indeed, you"],["أَنتَ","you"],["ٱلْأَعْلَىٰ","(will be) superior"]]],"2417":["(Dan lemparkanlah apa yang ada di tangan kananmu) yakni tongkat (niscaya ia akan menelan) yakni akan melahap (apa yang mereka perbuat. Sesungguhnya apa yang mereka perbuat itu adalah tipu daya tukang sihir) ulah tukang sihir belaka. (Dan tidak akan menang tukang sihir itu, dari mana saja ia datang\") dengan sihirnya itu. Lalu Nabi Musa melemparkan tongkatnya, maka tongkat Nabi Musa itu menjadi ular yang besar dan menelan semua apa yang diperbuat oleh para ahli sihir.",[["وَأَلْقِ","And throw"],["مَا","what"],["فِى","(is) in"],["يَمِينِكَ","your right hand"],["تَلْقَفْ","it will swallow up"],["مَا","what"],["صَنَعُوٓا۟ ۖ","they have made"],["إِنَّمَا","Only"],["صَنَعُوا۟","they (have) made"],["كَيْدُ","a trick"],["سَـٰحِرٍۢ ۖ","(of) a magician"],["وَلَا","and not"],["يُفْلِحُ","will be successful"],["ٱلسَّاحِرُ","the magician"],["حَيْثُ","wherever"],["أَتَىٰ","he comes"]]],"2418":["(Lalu tukang-tukang sihir itu tersungkur dengan bersujud) yakni mereka bersujud kepada Allah swt. (seraya berkata, \"Kami telah percaya kepada Rabb Harun dan Musa\").",[["فَأُلْقِىَ","So were thrown down"],["ٱلسَّحَرَةُ","the magicians"],["سُجَّدًۭا","prostrating"],["قَالُوٓا۟","They said"],["ءَامَنَّا","We believe"],["بِرَبِّ","in (the) Lord"],["هَـٰرُونَ","(of) Harun"],["وَمُوسَىٰ","and Musa"]]],"2419":["(Berkatalah) Firaun, (\"Apakah kalian telah beriman) dapat dibaca A-amantum dan Aamantum (kepada Musa sebelum aku memberi izin) sebelum aku mengizinkan (kepadamu sekalian. Sesungguhnya ia adalah pemimpin kalian) guru kalian (yang mengajarkan sihir kepada kalian. Maka sesungguhnya aku akan memotong tangan dan kaki kamu sekalian dengan bersilang secara bertimbal balik) lafal Min Khilaafin berkedudukan menjadi Hal, artinya secara bersilang, yaitu tangan kanan dengan kaki kiri (dan sesungguhnya aku akan menyalib kalian pada pangkal pohon kurma) yakni pada pohon kurma (dan sesungguhnya kalian akan mengetahui siapa di antara kita) yakni diri Firaun sendiri dan Rabb Nabi Musa (yang lebih pedih dan lebih kekal siksaannya\") bila ada orang yang melanggar kepadanya.",[["قَالَ","He said"],["ءَامَنتُمْ","You believe"],["لَهُۥ","[to] him"],["قَبْلَ","before"],["أَنْ","[that]"],["ءَاذَنَ","I gave permission"],["لَكُمْ ۖ","to you"],["إِنَّهُۥ","Indeed, he"],["لَكَبِيرُكُمُ","(is) your chief"],["ٱلَّذِى","the one who"],["عَلَّمَكُمُ","taught you"],["ٱلسِّحْرَ ۖ","the magic"],["فَلَأُقَطِّعَنَّ","So surely I will cut off"],["أَيْدِيَكُمْ","your hands"],["وَأَرْجُلَكُم","and your feet"],["مِّنْ","of"],["خِلَـٰفٍۢ","opposite sides"],["وَلَأُصَلِّبَنَّكُمْ","and surely I will crucify you"],["فِى","on"],["جُذُوعِ","(the) trunks"],["ٱلنَّخْلِ","(of) date-palms"],["وَلَتَعْلَمُنَّ","and surely you will know"],["أَيُّنَآ","which of us"],["أَشَدُّ","(is) more severe"],["عَذَابًۭا","(in) punishment"],["وَأَبْقَىٰ","and more lasting"]]],"2420":["(Mereka berkata, \"Kami sekali-kali tidak akan mengutamakan kamu) kami tidak akan memilih kamu (daripada bukti-bukti yang nyata yang telah datang kepada kami) bukti-bukti yang menunjukkan kebenaran Nabi Musa (dan daripada Tuhan yang telah menciptakan kami) yakni Allah yang telah menjadikan kami. Kalimat ini dapat diartikan sebagai Qasam atau sumpah atau di'athafkan kepada lafal Ma (maka putuskanlah apa yang hendak kamu putuskan) artinya lakukanlah apa yang kamu ucapkan itu. (Sesungguhnya kamu hanya akan dapat memutuskan pada kehidupan di dunia saja) dinashabkannya lafal Al-Hayaatad Dun-yaa menunjukkan makna Ittisa', maksudnya peradilan di dunia dan kelak kamu akan mendapat balasan yang setimpal di akhirat akibat dari perbuatanmu itu.",[["قَالُوا۟","They said"],["لَن","Never"],["نُّؤْثِرَكَ","we will prefer you"],["عَلَىٰ","over"],["مَا","what"],["جَآءَنَا","has come to us"],["مِنَ","of"],["ٱلْبَيِّنَـٰتِ","the clear proofs"],["وَٱلَّذِى","and the One Who"],["فَطَرَنَا ۖ","created us"],["فَٱقْضِ","So decree"],["مَآ","whatever"],["أَنتَ","you"],["قَاضٍ ۖ","(are) decreeing"],["إِنَّمَا","Only"],["تَقْضِى","you can decree"],["هَـٰذِهِ","(for) this"],["ٱلْحَيَوٰةَ","life"],["ٱلدُّنْيَآ","(of) the world"]]],"2421":["(Sesungguhnya kami telah beriman kepada Rabb kami, agar Dia mengampuni kesalahan-kesalahan kami) dari kemusyrikan dan dosa-dosa lainnya yang pernah kami lakukan (dan sihir yang telah kamu paksakan kepada kami melakukannya) mulai dari belajar sampai dengan mempraktekkannya untuk melawan Nabi Musa. (Dan Allah lebih baik) pahala-Nya daripada kamu, jika Dia ditaati (dan lebih kekal\") azab-Nya daripada kamu, jika didurhakai.",[["إِنَّآ","Indeed, [we]"],["ءَامَنَّا","we believe"],["بِرَبِّنَا","in our Lord"],["لِيَغْفِرَ","that He may forgive"],["لَنَا","for us"],["خَطَـٰيَـٰنَا","our sins"],["وَمَآ","and what"],["أَكْرَهْتَنَا","you compelled us"],["عَلَيْهِ","on it"],["مِنَ","of"],["ٱلسِّحْرِ ۗ","the magic"],["وَٱللَّهُ","And Allah"],["خَيْرٌۭ","(is) Best"],["وَأَبْقَىٰٓ","and Ever Lasting"]]],"2422":["Allah berfirman (Sesungguhnya barang siapa yang datang kepada Rabbnya dalam keadaan berdosa) yakni dalam keadaan kafir, sebagaimana Firaun (maka sesungguhnya baginya neraka Jahanam. Ia tidak mati di dalamnya) sehingga ia dapat istirahat dari kepedihan azab (dan tidak pula hidup) dengan kehidupan yang layak dan bermanfaat bagi dirinya.",[["إِنَّهُۥ","Indeed, he"],["مَن","who"],["يَأْتِ","comes"],["رَبَّهُۥ","(to) his Lord"],["مُجْرِمًۭا","(as) a criminal"],["فَإِنَّ","then indeed"],["لَهُۥ","for him"],["جَهَنَّمَ","(is) Hell"],["لَا","Not"],["يَمُوتُ","he will die"],["فِيهَا","in it"],["وَلَا","and not"],["يَحْيَىٰ","live"]]],"2423":["(Dan barang siapa yang datang kepada Rabbnya dalam keadaan beriman, lagi sungguh-sungguh telah beramal saleh) mengerjakan amal-amal fardu dan amal-amal sunah (maka mereka itulah orang-orang yang memperoleh kedudukan-kedudukan yang tinggi) lafal Al 'Ulaa adalah bentuk jamak daripada lafal Al 'Ulyaa muannats daripada lafal Al A'laa artinya yang paling tinggi.",[["وَمَن","But whoever"],["يَأْتِهِۦ","comes to Him"],["مُؤْمِنًۭا","(as) a believer"],["قَدْ","verily"],["عَمِلَ","he has done"],["ٱلصَّـٰلِحَـٰتِ","the righteous deeds"],["فَأُو۟لَـٰٓئِكَ","then those"],["لَهُمُ","for them"],["ٱلدَّرَجَـٰتُ","(will be) the ranks"],["ٱلْعُلَىٰ","[the] high"]]],"2424":["(Yaitu surga Adn) sebagai tempat tinggalnya, lafal Jannaatu 'Adnin merupakan penjelasan daripada kedudukan tadi (yang mengalir sungai-sungai di bawahnya, mereka kekal di dalamnya. Dan itu adalah balasan bagi orang yang bersih) daripada dosa-dosa.",[["جَنَّـٰتُ","Gardens"],["عَدْنٍۢ","(of) Eden"],["تَجْرِى","flows"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ","the rivers"],["خَـٰلِدِينَ","abiding forever"],["فِيهَا ۚ","in it"],["وَذَٰلِكَ","And that"],["جَزَآءُ","(is) the reward"],["مَن","(for him) who"],["تَزَكَّىٰ","purifies himself"]]],"2425":["(Dan sesungguhnya telah Kami wahyukan kepada Musa, \"Pergilah kalian dengan hamba-hamba-Ku di malam hari) jika dibaca Asri berasal dari Asraa dan jika dibaca Anisri dengan memakai Hamzah Washal, berasal dari kata Saraa, demikian menurut dua pendapat mengenainya, artinya: bawalah mereka pergi di malam hari dari negeri Mesir (maka buatlah untuk mereka) dengan tongkatmu itu (jalan yang kering di laut itu) artinya, jalan yang keadaannya telah kering. Nabi Musa mengerjakan apa yang telah diperintahkan kepadanya, lalu Allah mengeringkan jalan yang dilalui mereka, sehingga mereka dapat melaluinya (kamu tak usah khawatir akan tersusul) dapat terkejar oleh Firaun (dan tidak usah takut\") tenggelam.",[["وَلَقَدْ","And verily"],["أَوْحَيْنَآ","We inspired"],["إِلَىٰ","to"],["مُوسَىٰٓ","Musa"],["أَنْ","that"],["أَسْرِ","Travel by night"],["بِعِبَادِى","with My slaves"],["فَٱضْرِبْ","and strike"],["لَهُمْ","for them"],["طَرِيقًۭا","a path"],["فِى","in"],["ٱلْبَحْرِ","the sea"],["يَبَسًۭا","dry"],["لَّا","not"],["تَخَـٰفُ","fearing"],["دَرَكًۭا","to be overtaken"],["وَلَا","and not"],["تَخْشَىٰ","being afraid"]]],"2426":["(Maka Firaun dengan bala tentaranya mengejar mereka) Firaun pun ikut bersama dengan bala tentaranya (lalu mereka ditutup oleh laut) yakni laut itu melanda mereka (yang menenggelamkan mereka) akhirnya Firaun bersama dengan balatentaranya tenggelam.",[["فَأَتْبَعَهُمْ","Then followed them"],["فِرْعَوْنُ","Firaun"],["بِجُنُودِهِۦ","with his forces"],["فَغَشِيَهُم","but covered them"],["مِّنَ","from"],["ٱلْيَمِّ","the sea"],["مَا","what"],["غَشِيَهُمْ","covered them"]]],"2427":["(Dan Firaun telah menyesatkan kaumnya) dengan menyeru mereka supaya menyembah dirinya (dan tidak memberi petunjuk) akan tetapi justru Firaun menjerumuskan mereka ke dalam kebinasaan, berbeda halnya dengan apa yang telah diungkapkannya, yang kemudian disitir oleh firman-Nya, yaitu: (Firaun berkata), \"Dan aku tiada menunjukkan kepada kalian melainkan jalan yang benar\" (Q.S. Al-Mukmin 29).",[["وَأَضَلَّ","And led astray"],["فِرْعَوْنُ","Firaun"],["قَوْمَهُۥ","his people"],["وَمَا","and (did) not"],["هَدَىٰ","guide them"]]],"2428":["(Hai Bani Israel! Sesungguhnya Kami telah menyelamatkan kamu sekalian dari musuh kalian) yakni Firaun dengan menenggelamkannya (dan Kami telah mengadakan perjanjian dengan kamu sekalian di sebelah kanan bukit Thur) kemudian Kami memberikan kitab Taurat kepada Musa untuk diamalkan (dan Kami telah menurunkan kepada kamu sekalian manna dan salwa) yaitu dinamakan pula Taranjabin dan burung Sammani. Sedangkan orang-orang yang diseru dalam ayat ini adalah orang-orang Yahudi yang hidup di masa Nabi saw. Allah swt. berbicara kepada mereka seraya mengingatkan akan nikmat-nikmat yang telah dilimpahkan-Nya kepada kakek moyang mereka di zaman Nabi Musa. Dimaksud sebagai pendahuluan terhadap apa yang akan diungkapkan oleh Allah pada firman selanjutnya, yaitu:",[["يَـٰبَنِىٓ","O Children of Israel"],["إِسْرَٰٓءِيلَ","O Children of Israel"],["قَدْ","Verily"],["أَنجَيْنَـٰكُم","We delivered you"],["مِّنْ","from"],["عَدُوِّكُمْ","your enemy"],["وَوَٰعَدْنَـٰكُمْ","and We made a covenant with you"],["جَانِبَ","on (the) side"],["ٱلطُّورِ","(of) the Mount"],["ٱلْأَيْمَنَ","the right"],["وَنَزَّلْنَا","and We sent down"],["عَلَيْكُمُ","to you"],["ٱلْمَنَّ","the Manna"],["وَٱلسَّلْوَىٰ","and the quails"]]],"2429":["(Makanlah di antara rezeki yang baik yang telah kami berikan kepada kalian) yakni nikmat yang telah dilimpahkan kepada kalian (dan janganlah melampaui batas padanya) seumpamanya kalian mengingkari nikmat-nikmat itu (yang menyebabkan kemurkaan-Ku menimpa kalian) bila dibaca Yahilla artinya wajib kemurkaan-Ku menimpa kalian. Dan jika dibaca Yahulla artinya, pasti kemurkaan-Ku menimpa kalian (Dan barang siapa ditimpa oleh kemurkaan-Ku) lafal Yahlil dapat pula dibaca Yahlul (maka sungguh binasalah ia) terjerumuslah ia ke dalam neraka.",[["كُلُوا۟","Eat"],["مِن","of"],["طَيِّبَـٰتِ","(the) good things"],["مَا","which"],["رَزَقْنَـٰكُمْ","We have provided you"],["وَلَا","and (do) not"],["تَطْغَوْا۟","transgress"],["فِيهِ","therein"],["فَيَحِلَّ","lest should descend"],["عَلَيْكُمْ","upon you"],["غَضَبِى ۖ","My Anger"],["وَمَن","And whoever"],["يَحْلِلْ","on whom descends"],["عَلَيْهِ","on whom descends"],["غَضَبِى","My Anger"],["فَقَدْ","indeed"],["هَوَىٰ","he (has) perished"]]],"2430":["(Dan sesungguhnya Aku Maha Pengampun bagi orang yang bertobat) dari kemusyrikan (dan beriman) mentauhidkan Allah (dan beramal saleh) yakni mengamalkan fardu dan sunah (kemudian tetap di jalan yang benar) tetap mengamalkan apa yang telah disebutkan di atas hingga umurnya habis.",[["وَإِنِّى","But indeed, I Am"],["لَغَفَّارٌۭ","the Perpetual Forgiver"],["لِّمَن","of whoever"],["تَابَ","repents"],["وَءَامَنَ","and believes"],["وَعَمِلَ","and does"],["صَـٰلِحًۭا","righteous (deeds)"],["ثُمَّ","then"],["ٱهْتَدَىٰ","remains guided"]]],"2431":["(Mengapa kamu datang lebih cepat daripada kaummu) lebih cepat dari janji yang telah ditentukan untuk mengambil kitab Taurat (hai Musa?)",[["۞ وَمَآ","And what"],["أَعْجَلَكَ","made you hasten"],["عَن","from"],["قَوْمِكَ","your people"],["يَـٰمُوسَىٰ","O Musa"]]],"2432":["(Berkata Musa, \"Itulah mereka) dekat denganku berdatangan (sedang menyusul aku dan aku bersegera kepada-Mu, Ya Rabbku, supaya Engkau rida\") kepadaku, lebih daripada keridaan-Mu kepadaku sebelumnya. Sebelum menjawab pertanyaan Allah, Nabi Musa terlebih dahulu memohon maaf kepada-Nya, hal ini dia lakukan menurut dugaannya. Akan tetapi ternyata kenyataannya berbeda dengan apa yang diduga sebelumnya, yaitu ketika Allah berfirman pada ayat selanjutnya.",[["قَالَ","He said"],["هُمْ","They"],["أُو۟لَآءِ","(are) close"],["عَلَىٰٓ","upon"],["أَثَرِى","my tracks"],["وَعَجِلْتُ","and I hastened"],["إِلَيْكَ","to you"],["رَبِّ","my Lord"],["لِتَرْضَىٰ","that You be pleased"]]],"2433":["(Berfirman Allah) subhaanahu wa taala, (\"Maka sesungguhnya Kami telah menguji kaummu sesudah kamu tinggalkan) sesudah kamu berpisah meninggalkan mereka (dan mereka telah disesatkan oleh Samiri\") yang menjerumuskan mereka sehingga mereka menyembah anak sapi.",[["قَالَ","He said"],["فَإِنَّا","But indeed, We"],["قَدْ","[verily]"],["فَتَنَّا","We (have) tried"],["قَوْمَكَ","your people"],["مِنۢ","after you"],["بَعْدِكَ","after you"],["وَأَضَلَّهُمُ","and has led them astray"],["ٱلسَّامِرِىُّ","the Samiri"]]],"2434":["(Kemudian Musa kembali kepada kaumnya dengan marah) disebabkan tingkah laku kaumnya itu (dan bersedih hati) yakni dengan hati yang sangat sedih (Berkata Musa, \"Hai kaumku! Bukankah Rabb kalian telah menjanjikan kepada kalian suatu janji yang baik?) janji yang benar, bahwa Dia akan memberi kitab Taurat kepada kalian. (Maka apakah terasa lama masa yang berlalu itu bagi kalian) yakni masa perpisahanku dengan kalian (atau kalian menghendaki agar menimpa) (kalian kemurkaan dari Rabb kalian) disebabkan kalian menyembah anak sapi (dan kalian melanggar perjanjian kalian dengan aku?\") padahal sebelumnya kalian telah berjanji akan datang sesudahku, tetapi ternyata kalian tidak mau datang.",[["فَرَجَعَ","Then Musa returned"],["مُوسَىٰٓ","Then Musa returned"],["إِلَىٰ","to"],["قَوْمِهِۦ","his people"],["غَضْبَـٰنَ","angry"],["أَسِفًۭا ۚ","(and) sorrowful"],["قَالَ","He said"],["يَـٰقَوْمِ","O my people"],["أَلَمْ","Did not"],["يَعِدْكُمْ","promise you"],["رَبُّكُمْ","your Lord"],["وَعْدًا","a promise"],["حَسَنًا ۚ","good"],["أَفَطَالَ","Then, did seem long"],["عَلَيْكُمُ","to you"],["ٱلْعَهْدُ","the promise"],["أَمْ","or"],["أَرَدتُّمْ","did you desire"],["أَن","that"],["يَحِلَّ","descend"],["عَلَيْكُمْ","upon you"],["غَضَبٌۭ","(the) Anger"],["مِّن","of"],["رَّبِّكُمْ","your Lord"],["فَأَخْلَفْتُم","so you broke"],["مَّوْعِدِى","(the) promise to me"]]],"2435":["(Mereka berkata, \"Kami sekali-kali tidak melanggar perjanjianmu dengan kemauan kami sendiri) lafal Bimalkinaa dapat pula dibaca Bimilkinaa atau Bimulkinaa, artinya dengan kehendak kami sendiri, atau dengan kemauan kami sendiri (tetapi kami disuruh membawa) dapat dibaca Hammalnaa atau Hummilnaa (beban-beban) yakni beban yang berat-berat (dari perhiasan kaum itu) yakni perhiasan milik kaum Firaun, yang mereka pinjam dahulu untuk keperluan pengantin, kini perhiasan itu masih berada di tangan mereka (maka kami telah melemparkannya) kami mencampakkannya ke dalam api atas perintah Samiri (dan demikian pula) sebagaimana kami melemparkannya (Samiri melemparkannya\") yakni ia pun ikut melemparkan perhiasan kaum Firaun yang masih ada padanya dan ia melemparkan pula tanah Yang ia ambil dari bekas teracak kuda malaikat Jibril dengan cara seperti berikut ini.",[["قَالُوا۟","They said"],["مَآ","Not"],["أَخْلَفْنَا","we broke"],["مَوْعِدَكَ","promise to you"],["بِمَلْكِنَا","by our will"],["وَلَـٰكِنَّا","but we"],["حُمِّلْنَآ","[we] were made to carry"],["أَوْزَارًۭا","burdens"],["مِّن","from"],["زِينَةِ","ornaments"],["ٱلْقَوْمِ","(of) the people"],["فَقَذَفْنَـٰهَا","so we threw them"],["فَكَذَٰلِكَ","and thus"],["أَلْقَى","threw"],["ٱلسَّامِرِىُّ","the Samiri"]]],"2436":["(Kemudian Samiri mengeluarkan untuk mereka anak lembu) yang berhasil ia cetak dari perhiasan itu (yang bertubuh) yakni ada daging dan darahnya (dan bersuara) suaranya dapat didengar. Anak lembu itu menjadi demikian disebabkan pengaruh tanah bekas teracak kuda malaikat Jibril, sehingga ia dapat hidup. Tanah itu diletakkan oleh Samiri ke dalam mulut lembu itu sesudah dicetak, lalu anak lembu itu menjadi hidup (maka mereka berkata) yakni Samiri dan para pengikutnya, (\"Inilah Tuhan kalian dan Tuhan Musa, tetapi ia telah lupa\") Musa telah lupa akan Tuhannya, bahwa Dia ada di sini, lalu pergi mencari-Nya. Maka Allah berfirman:",[["فَأَخْرَجَ","Then he brought forth"],["لَهُمْ","for them"],["عِجْلًۭا","a calf's"],["جَسَدًۭا","body"],["لَّهُۥ","it had"],["خُوَارٌۭ","a lowing sound"],["فَقَالُوا۟","and they said"],["هَـٰذَآ","This"],["إِلَـٰهُكُمْ","(is) your god"],["وَإِلَـٰهُ","and the god"],["مُوسَىٰ","(of) Musa"],["فَنَسِىَ","but he forgot"]]],"2437":["(Maka apakah mereka tidak memperhatikan bahwa patung anak lembu itu) lafal Allaa merupakan gabungan daripada Ann yang ditakhfif dari Anna dan Laa, sedangkan isim Ann tidak disebutkan, asalnya Annahu Laa, artinya, bahwasanya anak lembu itu (tidak dapat memberi) tidak dapat memberikan (jawaban kepada mereka) yakni tidak dapat menyahuti perkataan mereka (dan tidak dapat memberi kemudaratan kepada mereka) maksudnya tidak dapat menolak kemudaratan yang menimpa mereka (dan tidak pula kemanfaatan?) tidak dapat mendatangkan kemanfaatan buat mereka. Maksudnya, mengapa mereka menjadikannya sebagai Tuhan?",[["أَفَلَا","Then, did not"],["يَرَوْنَ","they see"],["أَلَّا","that not"],["يَرْجِعُ","it (could) return"],["إِلَيْهِمْ","to them"],["قَوْلًۭا","a word"],["وَلَا","and not"],["يَمْلِكُ","possess"],["لَهُمْ","for them"],["ضَرًّۭا","any harm"],["وَلَا","and not"],["نَفْعًۭا","any benefit"]]],"2438":["(Dan sesungguhnya Harun telah berkata kepada mereka sebelumnya) sebelum Nabi Musa kembali kepada mereka (\"Hai kaumku! Sesungguhnya kalian hanya diberi cobaan dengan anak lembu itu dan sesungguhnya Rabb kalian ialah Yang Maha Pemurah, maka ikutilah aku) yakni menyembah kepada-Nya (dan taatilah perintahku\") di dalam menyembah kepada-Nya.",[["وَلَقَدْ","And verily"],["قَالَ","(had) said"],["لَهُمْ","to them"],["هَـٰرُونُ","Harun"],["مِن","before"],["قَبْلُ","before"],["يَـٰقَوْمِ","O my people"],["إِنَّمَا","Only"],["فُتِنتُم","you are being tested"],["بِهِۦ ۖ","by it"],["وَإِنَّ","and indeed"],["رَبَّكُمُ","your Lord"],["ٱلرَّحْمَـٰنُ","(is) the Most Gracious"],["فَٱتَّبِعُونِى","so follow me"],["وَأَطِيعُوٓا۟","and obey"],["أَمْرِى","my order"]]],"2439":["(Mereka menjawab, \"Kami akan tetap) kami akan terus (menyembah patung anak lembu ini) (hingga Musa kembali kepada kami\").",[["قَالُوا۟","They said"],["لَن","Never"],["نَّبْرَحَ","we will cease"],["عَلَيْهِ","being devoted to it"],["عَـٰكِفِينَ","being devoted to it"],["حَتَّىٰ","until"],["يَرْجِعَ","returns"],["إِلَيْنَا","to us"],["مُوسَىٰ","Musa"]]],"2440":["(Berkata Musa) setelah ia kembali kepada mereka, (\"Hai Harun! Apa yang menghalangi kamu ketika kamu melihat mereka sesat,) ketika mereka menyembah patung anak lembu itu.",[["قَالَ","He said"],["يَـٰهَـٰرُونُ","O Harun"],["مَا","What"],["مَنَعَكَ","prevented you"],["إِذْ","when"],["رَأَيْتَهُمْ","you saw them"],["ضَلُّوٓا۟","going astray"]]],"2441":["(Sehingga kamu tidak mengikuti aku?) huruf Laa di sini Zaidah. (Maka apakah kamu telah sengaja mendurhakai perintahku?\") disebabkan kamu tinggal diam di antara orang-orang yang menyembah selain Allah swt.",[["أَلَّا","That not"],["تَتَّبِعَنِ ۖ","you follow me"],["أَفَعَصَيْتَ","Then, have you disobeyed"],["أَمْرِى","my order"]]],"2442":["(Berkatalah) Harun (\"Hai putra ibuku!) dapat dibaca Ummi dan Umma maksudnya ibuku, Nabi Harun sengaja menyebut nama ini untuk mengharapkan belas kasihan dari Nabi Musa (Janganlah kamu pegang janggutku) Nabi Musa memegang janggut Nabi Harun dengan tangan kirinya (dan jangan pula kepalaku) Nabi Musa memegang rambut kepala Nabi Harun dengan tangan kanannya sebagai pelampiasan kemarahannya (sesungguhnya aku khawatir) seandainya aku mengikutimu, maka pastilah akan mengikutiku pula segolongan orang-orang yang menyembah anak lembu itu (bahwa kamu akan berkata kepadaku, 'Kamu telah memecah belah antara Bani Israel) lalu kamu marah kepadaku (dan kamu tidak menunggu) (perintahku\") di dalam mengambil sikap.",[["قَالَ","He said"],["يَبْنَؤُمَّ","O son of my mother"],["لَا","(Do) not"],["تَأْخُذْ","seize (me)"],["بِلِحْيَتِى","by my beard"],["وَلَا","and not"],["بِرَأْسِىٓ ۖ","by my head"],["إِنِّى","Indeed, I"],["خَشِيتُ","[I] feared"],["أَن","that"],["تَقُولَ","you would say"],["فَرَّقْتَ","You caused division"],["بَيْنَ","between"],["بَنِىٓ","(the) Children of Israel"],["إِسْرَٰٓءِيلَ","(the) Children of Israel"],["وَلَمْ","and not"],["تَرْقُبْ","you respect"],["قَوْلِى","my word"]]],"2443":["Berkata Musa, \"Apakah yang mendorongmu) berbuat demikian (hai Samiri?\")",[["قَالَ","He said"],["فَمَا","Then what"],["خَطْبُكَ","(is) your case"],["يَـٰسَـٰمِرِىُّ","O Samiri"]]],"2444":["(Samiri menjawab, \"Aku mengetahui sesuatu yang mereka tidak mengetahuinya) dapat dibaca Yabshuruu dan Tabshuruu, artinya, aku mengetahui apa yang tidak mereka ketahui (maka aku ambil segenggam dari) tanah (bekas) jejak teracak kuda (rasul) yakni malaikat Jibril (lalu aku melemparkannya) yakni aku menaruhnya pada patung anak lembu yang telah dicetak (dan demikianlah telah menggoda) telah membujuk (aku hawa nafsuku\") untuk menaruhnya ke dalam tubuhnya, yaitu setelah terlebih dahulu aku mengambil segenggam tanah bekas jejak teracak kuda malaikat Jibril. Lalu tanah itu aku taruh ke dalam patung yang tidak bernyawa, hingga patung itu menjadi hidup bagaikan ada rohnya. Kemudian aku melihat bahwa kaummu meminta kepadamu untuk menjadikan tuhan buat mereka. Lalu hatiku menggodaku untuk menjadikan patung anak lembu itu sebagai tuhan mereka.",[["قَالَ","He said"],["بَصُرْتُ","I perceived"],["بِمَا","what"],["لَمْ","not"],["يَبْصُرُوا۟","they perceive"],["بِهِۦ","in it"],["فَقَبَضْتُ","so I took"],["قَبْضَةًۭ","a handful"],["مِّنْ","from"],["أَثَرِ","(the) track"],["ٱلرَّسُولِ","(of) the Messenger"],["فَنَبَذْتُهَا","then threw it"],["وَكَذَٰلِكَ","and thus"],["سَوَّلَتْ","suggested"],["لِى","to me"],["نَفْسِى","my soul"]]],"2445":["(Berkata Musa) kepada Samiri, (\"Pergilah kamu) dari kalangan kami ini (maka sesungguhnya bagimu di dalam kehidupan di dunia ini) selama kamu hidup di dalamnya (hanya dapat mengatakan) kepada orang-orang yang kamu bertemu dengannya, ('Janganlah menyentuhku') janganlah kamu mendekat kepadaku. Dan disebutkan bahwa sejak saat itu Samiri mengembara tanpa tujuan dan jika ada seseorang menyentuhnya atau dia menyentuhnya, maka semuanya kena penyakit demam. (Dan sesungguhnya bagimu telah ada ketentuan waktu) bagi hukumanmu (yang kamu sekali-kali tidak dapat menghindarinya) jika dibaca Lan tukhlifahu artinya, kamu tidak dapat selamat dari azab itu. Dan jika dibaca Lan Tukhlafahu artinya, kamu dibangkitkan kelak di hari kiamat untuk diazab (dan lihatlah tuhanmu itu yang kamu tetap) lafal Zhalta asalnya dibaca Zhalilta, kemudian Lam yang pertama dibuang sehingga jadilah Zhalta artinya yang kamu selamanya (menyembah kepadanya) tetap menyembahnya. (Sesungguhnya kami akan membakarnya) dengan api (kemudian kami sungguh-sungguh akan menghambur-hamburkannya ke dalam laut) berupa abu yang berserakan terbawa oleh angin laut. Dan Nabi Musa mengerjakan apa yang telah dikatakannya itu setelah terlebih dahulu menyembelihnya.",[["قَالَ","He said"],["فَٱذْهَبْ","Then go"],["فَإِنَّ","And indeed"],["لَكَ","for you"],["فِى","in"],["ٱلْحَيَوٰةِ","the life"],["أَن","that"],["تَقُولَ","you will say"],["لَا","(Do) not"],["مِسَاسَ ۖ","touch"],["وَإِنَّ","And indeed"],["لَكَ","for you"],["مَوْعِدًۭا","(is) an appointment"],["لَّن","never"],["تُخْلَفَهُۥ ۖ","you will fail to (keep) it"],["وَٱنظُرْ","And look"],["إِلَىٰٓ","at"],["إِلَـٰهِكَ","your god"],["ٱلَّذِى","that which"],["ظَلْتَ","you have remained"],["عَلَيْهِ","to it"],["عَاكِفًۭا ۖ","devoted"],["لَّنُحَرِّقَنَّهُۥ","Surely we will burn it"],["ثُمَّ","then"],["لَنَنسِفَنَّهُۥ","certainly we will scatter it"],["فِى","in"],["ٱلْيَمِّ","the sea"],["نَسْفًا","(in) particles"]]],"2446":["(Sesungguhnya Tuhan kalian hanyalah Allah yang tidak ada Tuhan selain Dia, pengetahuan-Nya meliputi segala sesuatu) lafal 'Ilman adalah Tamyiz yang dipindahkan dari bentuk Fa'ilnya, artinya, pengetahuan-Nya meliputi segala sesuatu.",[["إِنَّمَآ","Only"],["إِلَـٰهُكُمُ","your God"],["ٱللَّهُ","(is) Allah"],["ٱلَّذِى","the One"],["لَآ","(there is) no"],["إِلَـٰهَ","god"],["إِلَّا","but"],["هُوَ ۚ","He"],["وَسِعَ","He has encompassed"],["كُلَّ","all"],["شَىْءٍ","things"],["عِلْمًۭا","(in) knowledge"]]],"2447":["(Demikianlah) sebagaimana Kami telah mengisahkan cerita ini kepadamu, hai Muhammad (Kami kisahkan kepadamu sebagian kisah) berita (umat yang telah silam) yakni bangsa-bangsa di masa lampau (dan sesungguhnya telah Kami berikan kepadamu) yakni Kami telah memberimu (dari sisi Kami) yakni dari hadirat Kami (suatu peringatan) yakni Alquran.",[["كَذَٰلِكَ","Thus"],["نَقُصُّ","We relate"],["عَلَيْكَ","to you"],["مِنْ","from"],["أَنۢبَآءِ","(the) news"],["مَا","(of) what"],["قَدْ","has preceded"],["سَبَقَ ۚ","has preceded"],["وَقَدْ","And certainly"],["ءَاتَيْنَـٰكَ","We have given you"],["مِن","from"],["لَّدُنَّا","Us"],["ذِكْرًۭا","a Reminder"]]],"2448":["(Barang siapa berpaling daripada Alquran) artinya ia tidak beriman kepada Alquran (maka sesungguhnya ia akan memikul dosa yang besar di hari kiamat) beban yang sangat berat berupa dosa-dosa.",[["مَّنْ","Whoever"],["أَعْرَضَ","turns away"],["عَنْهُ","from it"],["فَإِنَّهُۥ","then indeed, he"],["يَحْمِلُ","will bear"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) Resurrection"],["وِزْرًا","a burden"]]],"2449":["(Mereka kekal di dalamnya) menanggung azab dosanya untuk selamanya. (Dan amat buruklah dosa itu sebagai beban bagi mereka di hari kiamat) lafal Himlan merupakan Tamyiz yang menafsirkan makna Dhamir dalam lafal Saa'a, sedangkan subjek yang dicelanya dibuang yaitu lafal Wizrahum, artinya dosa mereka. Huruf Lam yang ada pada lafal Lahum berfungsi untuk menerangkan. Kemudian lafal Yaumal Qiyaamah dijelaskan oleh ayat berikutnya, yaitu:",[["خَـٰلِدِينَ","Abiding forever"],["فِيهِ ۖ","in it"],["وَسَآءَ","and evil"],["لَهُمْ","for them"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["حِمْلًۭا","(as) a load"]]],"2450":["(Yaitu di hari yang di waktu itu ditiup sangkakala) untuk tiupan yang kedua kalinya (dan Kami akan mengumpulkan orang-orang yang berdosa) yaitu orang-orang kafir (pada hari itu dengan mata yang biru muram) yakni mata mereka tampak membiru dan muka mereka tampak hitam karena muram.",[["يَوْمَ","(The) Day"],["يُنفَخُ","will be blown"],["فِى","in"],["ٱلصُّورِ ۚ","the Trumpet"],["وَنَحْشُرُ","and We will gather"],["ٱلْمُجْرِمِينَ","the criminals"],["يَوْمَئِذٍۢ","that Day"],["زُرْقًۭا","blue-eyed"]]],"2451":["(Mereka berbisik-bisik di antara mereka sendiri) yaitu berbicara dengan suara yang pelan-pelan (\"Tidaklah) (kalian tinggal) di dunia (melainkan sepuluh) hari.\"",[["يَتَخَـٰفَتُونَ","They are murmuring"],["بَيْنَهُمْ","among themselves"],["إِن","Not"],["لَّبِثْتُمْ","you remained"],["إِلَّا","except (for)"],["عَشْرًۭا","ten"]]],"2452":["(Kami lebih mengetahui apa yang mereka katakan) dalam bisikan mereka itu. Maksudnya, keadaannya tidaklah seperti apa yang mereka katakan (ketika berkata orang yang paling tepat di antara mereka) yakni paling lurus (penilaiannya) sehubungan dengan hal ini, (\"Kalian tidak berdiam di dunia melainkan hanya sehari saja\") mereka menilai minim sekali masa tinggal mereka di dunia, hal ini disebabkan kengerian-kengerian yang mereka saksikan di alam akhirat.",[["نَّحْنُ","We"],["أَعْلَمُ","know best"],["بِمَا","what"],["يَقُولُونَ","they will say"],["إِذْ","when"],["يَقُولُ","will say"],["أَمْثَلُهُمْ","(the) best of them"],["طَرِيقَةً","(in) conduct"],["إِن","Not"],["لَّبِثْتُمْ","you remained"],["إِلَّا","except (for)"],["يَوْمًۭا","a day"]]],"2453":["(Dan mereka bertanya kepadamu tentang gunung-gunung,) bagaimana jadinya di hari kiamat nanti? (maka katakanlah) kepada mereka (\"Rabbku akan menghancurkannya sehancur-hancurnya,) seumpamanya Dia meleburkannya menjadi debu yang lembut kemudian diterbangkan-Nya dengan angin.",[["وَيَسْـَٔلُونَكَ","And they ask you"],["عَنِ","about"],["ٱلْجِبَالِ","the mountains"],["فَقُلْ","so say"],["يَنسِفُهَا","Will blast them"],["رَبِّى","my Lord"],["نَسْفًۭا","(into) particles"]]],"2454":["(Maka Dia akan menjadikan bekas gunung-gunung itu datar) merata (dengan tanah) yakni rata sama sekali tiada bekasnya.",[["فَيَذَرُهَا","Then He will leave it"],["قَاعًۭا","a level"],["صَفْصَفًۭا","plain"]]],"2455":["(Tidak ada sedikit pun kamu lihat padanya tempat yang melengkung) tempat yang rendah (dan tidak pula tempat yang tinggi) tempat yang tinggi-tinggi.",[["لَّا","Not"],["تَرَىٰ","you will see"],["فِيهَا","in it"],["عِوَجًۭا","any crookedness"],["وَلَآ","and not"],["أَمْتًۭا","any curve"]]],"2456":["(Pada hari itu) pada hari ketika gunung-gunung itu dihancurkan (manusia mengikuti) manusia semuanya mengikuti sesudah mereka dibangunkan dari kuburannya (penyeru) yang menggiring mereka dengan suaranya ke padang Mahsyar, dia adalah malaikat Israfil. Dia mengatakan, \"Kemarilah kamu sekalian ke hadapan Tuhan Yang Maha Pemurah\" (dengan tidak berbelok-belok) sewaktu mereka menuruti panggilan suara itu. Atau dengan kata lain mereka tidak mempunyai kemampuan untuk tidak mengikuti anjuran suara itu (dan merendahlah) yakni menjadi tenanglah (semua suara kepada Tuhan Yang Maha Pemurah, maka kamu tidak mendengar melainkan hanya bisikan saja) suara telapak kaki mereka sewaktu berjalan menuju ke padang Mahsyar bagaikan suara teracak kaki unta bila berjalan.",[["يَوْمَئِذٍۢ","On that Day"],["يَتَّبِعُونَ","they will follow"],["ٱلدَّاعِىَ","the caller"],["لَا","no"],["عِوَجَ","deviation"],["لَهُۥ ۖ","from it"],["وَخَشَعَتِ","And (will be) humbled"],["ٱلْأَصْوَاتُ","the voices"],["لِلرَّحْمَـٰنِ","for the Most Gracious"],["فَلَا","so not"],["تَسْمَعُ","you will hear"],["إِلَّا","except"],["هَمْسًۭا","a faint sound"]]],"2457":["(Pada hari itu tidak berguna syafaat) seseorang (kecuali syafaat orang yang Allah Maha Pemurah telah memberi izin kepadanya) untuk memberi syafaat (dan Dia telah meridai perkataannya) seumpamanya orang yang diberi izin itu mengatakan, \"La Ilaaha Illallaah atau tidak ada Tuhan selain Allah.\"",[["يَوْمَئِذٍۢ","(On) that Day"],["لَّا","not"],["تَنفَعُ","will benefit"],["ٱلشَّفَـٰعَةُ","the intercession"],["إِلَّا","except"],["مَنْ","(to) whom"],["أَذِنَ","has given permission"],["لَهُ","[to him]"],["ٱلرَّحْمَـٰنُ","the Most Gracious"],["وَرَضِىَ","and He has accepted"],["لَهُۥ","for him"],["قَوْلًۭا","a word"]]],"2458":["(Dia mengetahui apa yang ada di hadapan mereka) yaitu perkara-perkara akhirat (dan apa yang ada di belakang mereka) perkara-perkara dunia (sedangkan ilmu mereka tidak dapat meliputi ilmu-Nya\") yakni mereka tidak mengetahui hal tersebut.",[["يَعْلَمُ","He knows"],["مَا","what"],["بَيْنَ","(is) before them"],["أَيْدِيهِمْ","(is) before them"],["وَمَا","and what"],["خَلْفَهُمْ","(is) behind them"],["وَلَا","while not"],["يُحِيطُونَ","they encompass"],["بِهِۦ","it"],["عِلْمًۭا","(in) knowledge"]]],"2459":["(Dan tunduklah semua muka) tunduk merendahkan diri (kepada Tuhan Yang Hidup Kekal lagi Maha Memelihara) yakni Allah swt. (Dan sesungguhnya telah merugilah) (orang yang melakukan kelaliman) yakni kemusyrikan.",[["۞ وَعَنَتِ","And (will be) humbled"],["ٱلْوُجُوهُ","the faces"],["لِلْحَىِّ","before the Ever-Living"],["ٱلْقَيُّومِ ۖ","the Self-Subsisting"],["وَقَدْ","And verily"],["خَابَ","will have failed"],["مَنْ","(he) who"],["حَمَلَ","carried"],["ظُلْمًۭا","wrongdoing"]]],"2460":["(Dan barang siapa mengerjakan amal yang saleh) amal-amal ketaatan (dan ia dalam keadaan beriman, maka ia tidak khawatir akan diperlakukan tidak adil) dengan diberatkan dosanya (dan tidak pula akan pengurangan haknya) dikurangi pahala kebaikannya.",[["وَمَن","But (he) who"],["يَعْمَلْ","does"],["مِنَ","of"],["ٱلصَّـٰلِحَـٰتِ","the righteous deeds"],["وَهُوَ","while he"],["مُؤْمِنٌۭ","(is) a believer"],["فَلَا","then not"],["يَخَافُ","he will fear"],["ظُلْمًۭا","injustice"],["وَلَا","and not"],["هَضْمًۭا","deprivation"]]],"2461":["(Dan demikianlah) lafal Kadzaalika dia'athafkan kepada Kadzaalika Naqushshu pada ayat sembilan puluh sembilan. Artinya: Demikianlah sebagaimana diturunkannya apa yang telah Kami ceritakan tadi (Kami menurunkannya) Alquran (dalam bahasa Arab dan Kami telah menerangkan dengan berulang-ulang) (di dalamnya sebagian dari ancaman, agar mereka bertakwa) takut kepada kemusyrikan (atau agar ia menimbulkan) Alquran ini (pengajaran bagi mereka) melalui kebinasaan yang telah dialami oleh umat-umat sebelumnya sehingga mereka mengambil pelajaran daripadanya.",[["وَكَذَٰلِكَ","And thus"],["أَنزَلْنَـٰهُ","We have sent it down"],["قُرْءَانًا","(the) Quran"],["عَرَبِيًّۭا","(in) Arabic"],["وَصَرَّفْنَا","and We have explained"],["فِيهِ","in it"],["مِنَ","of"],["ٱلْوَعِيدِ","the warnings"],["لَعَلَّهُمْ","that they may"],["يَتَّقُونَ","fear"],["أَوْ","or"],["يُحْدِثُ","it may cause"],["لَهُمْ","[for] them"],["ذِكْرًۭا","remembrance"]]],"2462":["(Maka Maha Tinggi Allah Raja Yang sesungguhnya) daripada apa yang dikatakan oleh orang-orang musyrik (dan janganlah kamu tergesa-gesa terhadap Alquran) sewaktu kamu membacanya (sebelum disempurnakan mewahyukannya kepadamu) sebelum malaikat Jibril selesai menyampaikannya (dan katakanlah, \"Ya Rabbku! Tambahkanlah kepadaku ilmu pengetahuan\") tentang Alquran, sehingga setiap kali diturunkan kepadanya Alquran, makin bertambah ilmu pengetahuannya.",[["فَتَعَـٰلَى","So high (above all)"],["ٱللَّهُ","(is) Allah"],["ٱلْمَلِكُ","the King"],["ٱلْحَقُّ ۗ","the True"],["وَلَا","And (do) not"],["تَعْجَلْ","hasten"],["بِٱلْقُرْءَانِ","with the Quran"],["مِن","before"],["قَبْلِ","before"],["أَن","[that]"],["يُقْضَىٰٓ","is completed"],["إِلَيْكَ","to you"],["وَحْيُهُۥ ۖ","its revelation"],["وَقُل","and say"],["رَّبِّ","My Lord"],["زِدْنِى","Increase me"],["عِلْمًۭا","(in) knowledge"]]],"2463":["(Dan sesungguhnya telah Kami perintahkan kepada Adam) Kami telah berwasiat kepadanya, janganlah ia memakan buah pohon terlarang ini (dahulu) sebelum ia memakannya (maka ia lupa) melupakan perintah kami itu (dan tidak Kami dapati padanya kemauan yang kuat) keteguhan dan kesabaran daripada apa yang Kami larang ia mengerjakannya.",[["وَلَقَدْ","And verily"],["عَهِدْنَآ","We made a covenant"],["إِلَىٰٓ","with"],["ءَادَمَ","Adam"],["مِن","before"],["قَبْلُ","before"],["فَنَسِىَ","but he forgot"],["وَلَمْ","and not"],["نَجِدْ","We found"],["لَهُۥ","in him"],["عَزْمًۭا","determination"]]],"2464":["(Dan) ingatlah (ketika Kami berkata kepada Malaikat, \"Sujudlah kalian kepada Adam!\" Maka mereka sujud kecuali iblis) dia adalah bapaknya jin, dia dahulu berteman dengan para Malaikat dan ikut menyembah Allah bersama dengan para Malaikat (ia membangkang) tidak mau sujud kepada Nabi Adam; bahkan mengatakan sebagaimana yang telah disitir oleh firman-Nya; Iblis menjawab, \"Saya lebih baik daripadanya...\" (Q.S. Al-A'raf, 12).",[["وَإِذْ","And when"],["قُلْنَا","We said"],["لِلْمَلَـٰٓئِكَةِ","to the Angels"],["ٱسْجُدُوا۟","Prostrate"],["لِـَٔادَمَ","to Adam"],["فَسَجَدُوٓا۟","then they prostrated"],["إِلَّآ","except"],["إِبْلِيسَ","Iblis"],["أَبَىٰ","he refused"]]],"2465":["(Maka Kami berkata, \"Hai Adam! Sesungguhnya iblis ini adalah musuh bagimu dan bagi istrimu) yakni Siti Hawa (maka sekali-kali janganlah sampai ia mengeluarkan kamu berdua dari surga, yang menyebabkan kamu menjadi sengsara) hidup sengsara disebabkan terlebih dahulu kamu harus mencangkul, menanam, menuai, menumbuk, membuat roti dan lain sebagainya. Ungkapan sengsara di sini ditujukan hanya kepada Nabi Adam, disebabkan secara fitrah suami itu mencari nafkah buat istrinya.",[["فَقُلْنَا","Then We said"],["يَـٰٓـَٔادَمُ","O Adam"],["إِنَّ","Indeed"],["هَـٰذَا","this"],["عَدُوٌّۭ","(is) an enemy"],["لَّكَ","to you"],["وَلِزَوْجِكَ","and to your wife"],["فَلَا","So not"],["يُخْرِجَنَّكُمَا","(let) him drive you both"],["مِنَ","from"],["ٱلْجَنَّةِ","Paradise"],["فَتَشْقَىٰٓ","so (that) you would suffer"]]],"2466":["(Sesungguhnya kamu tidak akan kelaparan di dalamnya dan tidak akan telanjang). Lafal Allaa adalah gabungan daripada huruf An dan Laa.",[["إِنَّ","Indeed"],["لَكَ","for you"],["أَلَّا","that not"],["تَجُوعَ","you will be hungry"],["فِيهَا","therein"],["وَلَا","and not"],["تَعْرَىٰ","you will be unclothed"]]],"2467":["(Dan sesungguhnya kamu) baik dibaca Annaka atau Innaka, diathafkan kepada isimnya Inna pada ayat sebelumnya dan jumlah kalimat kelanjutannya ialah (tidak akan merasa dahaga di dalamnya) yakni tidak akan merasa haus (dan tidak pula akan ditimpa panas matahari di dalamnya\") yaitu sinar matahari di waktu dhuha tidak akan kamu alami lagi, karena di dalam surga tidak ada matahari.",[["وَأَنَّكَ","And that you"],["لَا","not"],["تَظْمَؤُا۟","will suffer from thirst"],["فِيهَا","therein"],["وَلَا","and not"],["تَضْحَىٰ","exposed to the sun's heat"]]],"2468":["(Kemudian setan membisikkan pikiran jahat kepadanya seraya berkata, \"Hai Adam! Maukah saya tunjukkan kepada kamu pohon keabadian) yaitu pohon yang barang siapa memakan buahnya akan hidup kekal (dan kerajaan yang tidak akan binasa?\") yakni kerajaan yang kekal.",[["فَوَسْوَسَ","Then whispered"],["إِلَيْهِ","to him"],["ٱلشَّيْطَـٰنُ","Shaitaan"],["قَالَ","he said"],["يَـٰٓـَٔادَمُ","O Adam"],["هَلْ","Shall"],["أَدُلُّكَ","I direct you"],["عَلَىٰ","to"],["شَجَرَةِ","(the) tree"],["ٱلْخُلْدِ","(of) the Eternity"],["وَمُلْكٍۢ","and a kingdom"],["لَّا","not"],["يَبْلَىٰ","(that will) deteriorate"]]],"2469":["(Maka keduanya memakan) yakni Adam dan Hawa (dari buah pohon itu, lalu tampaklah bagi keduanya aurat-auratnya) yakni keduanya dapat melihat kemaluan masing-masing. Kedua aurat itu dinamakan kemaluan disebabkan jika kelihatan maka orang yang memilikinya menjadi malu (dan mulailah keduanya menutupi) keduanya menempelkan kepada (aurat masing-masing dengan daun-daun yang ada di surga) untuk menutupi auratnya (dan durhakalah Adam kepada Rabbnya dan sesatlah ia) disebabkan memakan buah pohon yang terlarang itu.",[["فَأَكَلَا","Then they both ate"],["مِنْهَا","from it"],["فَبَدَتْ","so became apparent"],["لَهُمَا","to them"],["سَوْءَٰتُهُمَا","their shame"],["وَطَفِقَا","and they began"],["يَخْصِفَانِ","(to) fasten"],["عَلَيْهِمَا","on themselves"],["مِن","from"],["وَرَقِ","(the) leaves"],["ٱلْجَنَّةِ ۚ","(of) Paradise"],["وَعَصَىٰٓ","And Adam disobeyed"],["ءَادَمُ","And Adam disobeyed"],["رَبَّهُۥ","his Lord"],["فَغَوَىٰ","and erred"]]],"2470":["(Kemudian Rabbnya memilihnya) yakni mendekatkannya ke sisi-Nya (maka Dia menerima tobatnya) sebelum Nabi Adam bertobat (dan memberinya petunjuk) supaya terus-menerus bertobat.",[["ثُمَّ","Then"],["ٱجْتَبَـٰهُ","chose him"],["رَبُّهُۥ","his Lord"],["فَتَابَ","and turned"],["عَلَيْهِ","to him"],["وَهَدَىٰ","and guided (him)"]]],"2471":["(Allah berfirman, \"Turunlah kamu berdua) Adam dan Hawa berikut apa yang telah dikandung oleh kalian yaitu anak cucu kalian (daripadanya) dari surga (bersama-sama, sebagian kalian) sebagian keturunan kalian (menjadi musuh bagi sebagian yang lain) disebabkan sebagian dari mereka berbuat zalim terhadap sebagian yang lain. (Maka jika) lafal Imma ini asalnya terdiri dari In Syarthiyah yang diidgamkan kepada Ma Zaidah (jika datang kepada kalian petunjuk daripada-Ku maka barang siapa yang mengikuti petunjuk-Ku) yakni Alquran (maka ia tidak akan sesat) di dunia (dan tidak akan celaka) di akhirat nanti.",[["قَالَ","He said"],["ٱهْبِطَا","Go down"],["مِنْهَا","from it"],["جَمِيعًۢا ۖ","all"],["بَعْضُكُمْ","some of you"],["لِبَعْضٍ","to others"],["عَدُوٌّۭ ۖ","(as) enemy"],["فَإِمَّا","Then if"],["يَأْتِيَنَّكُم","comes to you"],["مِّنِّى","from Me"],["هُدًۭى","guidance"],["فَمَنِ","then whoever"],["ٱتَّبَعَ","follows"],["هُدَاىَ","My guidance"],["فَلَا","then not"],["يَضِلُّ","he will go astray"],["وَلَا","and not"],["يَشْقَىٰ","suffer"]]],"2472":["(Dan barang siapa berpaling dari peringatan-Ku) yakni Alquran, yaitu dia tidak beriman kepadanya (maka sesungguhnya baginya penghidupan yang sempit) lafal Dhankan ini merupakan Mashdar artinya sempit. Ditafsirkan oleh sebuah hadis, bahwa hal ini menunjukkan tentang diazabnya orang kafir di dalam kuburnya (dan Kami akan mengumpulkannya) orang yang berpaling dari Alquran (pada hari kiamat dalam keadaan buta\") penglihatannya.",[["وَمَنْ","And whoever"],["أَعْرَضَ","turns away"],["عَن","from"],["ذِكْرِى","My remembrance"],["فَإِنَّ","then indeed"],["لَهُۥ","for him"],["مَعِيشَةًۭ","(is) a life"],["ضَنكًۭا","straitened"],["وَنَحْشُرُهُۥ","and We will gather him"],["يَوْمَ","(on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["أَعْمَىٰ","blind"]]],"2473":["(Berkatalah ia, \"Ya Rabbku! Mengapa Engkau menghimpun aku dalam keadaan buta, padahal dahulunya aku adalah orang yang melihat?\") yakni di kala ia hidup di dunia melihat tetapi di kala ia dibangkitkan hidup kembali buta.",[["قَالَ","He will say"],["رَبِّ","My Lord"],["لِمَ","Why"],["حَشَرْتَنِىٓ","You raised me"],["أَعْمَىٰ","blind"],["وَقَدْ","while [verily]"],["كُنتُ","I had"],["بَصِيرًۭا","sight"]]],"2474":["(Allah berfirman,) perkaranya (\"Demikianlah, telah datang kepadamu ayat-ayat Kami, maka kamu melupakannya) kamu meninggalkannya dan tidak mau beriman kepadanya (dan begitu pula) sebagaimana kamu lupa kepada ayat-ayat Kami (pada hari ini kamu pun dilupakan\") dibiarkan tinggal di dalam neraka.",[["قَالَ","He will say"],["كَذَٰلِكَ","Thus"],["أَتَتْكَ","came to you"],["ءَايَـٰتُنَا","Our Signs"],["فَنَسِيتَهَا ۖ","but you forgot them"],["وَكَذَٰلِكَ","and thus"],["ٱلْيَوْمَ","today"],["تُنسَىٰ","you will be forgotten"]]],"2475":["(Dan demikianlah) sebagaimana Kami membalas kepada orang yang berpaling daripada Alquran (Kami membalas orang yang melampaui batas) orang yang musyrik (dan tidak percaya kepada ayat-ayat Rabbnya. Dan sesungguhnya azab di akhirat itu lebih berat) daripada azab di dunia dan azab kubur (dan lebih kekal) lebih abadi.",[["وَكَذَٰلِكَ","And thus"],["نَجْزِى","We recompense"],["مَنْ","(he) who"],["أَسْرَفَ","transgresses"],["وَلَمْ","and not"],["يُؤْمِنۢ","believes"],["بِـَٔايَـٰتِ","in (the) Signs"],["رَبِّهِۦ ۚ","(of) his Lord"],["وَلَعَذَابُ","And surely (the) punishment"],["ٱلْـَٔاخِرَةِ","(of) the Hereafter"],["أَشَدُّ","(is) more severe"],["وَأَبْقَىٰٓ","and more lasting"]]],"2476":["(Maka tidakkah menjadi petunjuk) yakni tidak jelas (bagi mereka) orang-orang kafir Mekah (berapa banyak) lafal Kam di sini adalah kalimat berita yang berkedudukan menjadi maf'ul (Kami membinasakan) sudah berapa banyak telah Kami binasakan (umat-umat sebelum mereka) umat-umat terdahulu disebabkan mereka mendustakan Rasul-rasul (padahal mereka berjalan) Lafal Yamsyuuna ini menjadi Hal daripada Dhamir Lahum (melewati peninggalan umat-umat itu?) sewaktu mereka berniaga ke negeri Syam dan negeri-negeri yang lain, seharusnya mereka mengambil pelajaran daripadanya. Disebutkan pengertian membinasakan, hal ini diambil dari Fi'il atau kata kerjanya tanpa memakai huruf Mashdar demi memelihara keselarasan makna, maka hal ini tidak dilarang. (Sesungguhnya pada yang demikian itu terdapat tanda-tanda) pelajaran-pelajaran (bagi orang-orang yang berakal) yakni bagi mereka yang berakal.",[["أَفَلَمْ","Then has not"],["يَهْدِ","it guided"],["لَهُمْ","[for] them"],["كَمْ","how many"],["أَهْلَكْنَا","We (have) destroyed"],["قَبْلَهُم","before them"],["مِّنَ","of"],["ٱلْقُرُونِ","the generations"],["يَمْشُونَ","(as) they walk"],["فِى","in"],["مَسَـٰكِنِهِمْ ۗ","their dwellings"],["إِنَّ","Indeed"],["فِى","in"],["ذَٰلِكَ","that"],["لَـَٔايَـٰتٍۢ","surely (are) Signs"],["لِّأُو۟لِى","for possessors"],["ٱلنُّهَىٰ","(of) intelligence"]]],"2477":["(Dan sekiranya tidak ada suatu ketetapan dari Rabbmu yang telah terdahulu) untuk menangguhkan azab daripada mereka hingga hari kemudian (niscayalah) pembinasaan itu (pasti) menimpa mereka sejak di dunia (dan waktu yang telah ditentukan) waktu yang telah dipastikan bagi azab mereka. Kalimat ayat ini di'athafkan kepada Dhamir yang terkandung di dalam lafal Kaana dan menjadi pemisah di antara keduanya adalah Khabar Kaana yang berfungsi sebagai pengukuh makna. Maksudnya; dan di hari kemudian, azab akan menimpa mereka pula.",[["وَلَوْلَا","And if not"],["كَلِمَةٌۭ","(for) a Word"],["سَبَقَتْ","(that) preceded"],["مِن","from"],["رَّبِّكَ","your Lord"],["لَكَانَ","surely (would) have been"],["لِزَامًۭا","an obligation"],["وَأَجَلٌۭ","and a term"],["مُّسَمًّۭى","determined"]]],"2478":["(Maka sabarlah kamu atas apa yang mereka katakan) hanya saja ayat ini dimansukh oleh ayat berperang (dan bertasbihlah) salatlah (dengan memuji Rabbmu) lafal Bihamdi Rabbika merupakan Hal atau kata keterangan keadaan, maksudnya seraya memuji-Nya (sebelum terbit matahari) yaitu salat Subuh (dan sebelum terbenamnya) salat Asar (dan pada waktu-waktu di malam hari) saat-saat malam hari (bertasbih pulalah) yaitu salat Magrib dan salat Isyaklah kamu (dan pada waktu-waktu di siang hari) ia di'athafkan secara Mahal kepada lafal Ana yang dinashabkan. Maksudnya salat Zuhurlah kamu; karena waktu salat Zuhur itu mulai sejak bergeser matahari dari garis pertengahan langit; yaitu bergesernya matahari dari bagian pertengahan pertama menuju kepada bagian pertengahan kedua (supaya kamu merasa senang) dengan pahala yang akan diberikan kepadamu.",[["فَٱصْبِرْ","So be patient"],["عَلَىٰ","over"],["مَا","what"],["يَقُولُونَ","they say"],["وَسَبِّحْ","and glorify"],["بِحَمْدِ","with praise"],["رَبِّكَ","(of) your Lord"],["قَبْلَ","before"],["طُلُوعِ","(the) rising"],["ٱلشَّمْسِ","(of) the sun"],["وَقَبْلَ","and before"],["غُرُوبِهَا ۖ","its setting"],["وَمِنْ","and from"],["ءَانَآئِ","(the) hours"],["ٱلَّيْلِ","(of) the night"],["فَسَبِّحْ","and glorify"],["وَأَطْرَافَ","(at the) ends"],["ٱلنَّهَارِ","(of) the day"],["لَعَلَّكَ","so that you may"],["تَرْضَىٰ","be satisfied"]]],"2479":["(Dan janganlah kamu tujukan kedua matamu kepada apa yang telah Kami berikan kepada golongan-golongan) yakni berbagai macam golongan (dari mereka, sebagai bunga kehidupan dunia) sebagai perhiasan dan kesemarakan kehidupan dunia (Kami cobai mereka dengannya) seumpamanya mereka makin kelewat batas karenanya. (Dan karunia Rabbmu) di surga (adalah lebih baik) daripada keduniaan yang diberikan kepada mereka (dan lebih kekal) yakni lebih abadi.",[["وَلَا","And (do) not"],["تَمُدَّنَّ","extend"],["عَيْنَيْكَ","your eyes"],["إِلَىٰ","towards"],["مَا","what"],["مَتَّعْنَا","We have given for enjoyment"],["بِهِۦٓ","[with it]"],["أَزْوَٰجًۭا","pairs"],["مِّنْهُمْ","of them"],["زَهْرَةَ","(the) splendor"],["ٱلْحَيَوٰةِ","(of) the life"],["ٱلدُّنْيَا","(of) the world"],["لِنَفْتِنَهُمْ","that We may test them"],["فِيهِ ۚ","in it"],["وَرِزْقُ","And (the) provision"],["رَبِّكَ","(of) your Lord"],["خَيْرٌۭ","(is) better"],["وَأَبْقَىٰ","and more lasting"]]],"2480":["(Dan perintahkanlah kepada keluargamu mendirikan salat dan bersabarlah kamu) teguh dan sabarlah kamu (dalam mengerjakannya. Kami tidak meminta kepadamu) tidak membebankan kepadamu (rezeki) untuk dirimu dan tidak pula untuk orang lain (Kamilah yang memberi rezeki kepadamu. Dan akibat yang baik itu) yakni pahala surga (hanyalah bagi ketakwaan) bagi orang yang bertakwa.",[["وَأْمُرْ","And enjoin"],["أَهْلَكَ","(on) your family"],["بِٱلصَّلَوٰةِ","the prayer"],["وَٱصْطَبِرْ","and be steadfast"],["عَلَيْهَا ۖ","therein"],["لَا","Not"],["نَسْـَٔلُكَ","We ask you"],["رِزْقًۭا ۖ","(for) provision"],["نَّحْنُ","We"],["نَرْزُقُكَ ۗ","provide (for) you"],["وَٱلْعَـٰقِبَةُ","and the outcome"],["لِلتَّقْوَىٰ","(is) for the righteous[ness]"]]],"2481":["(Dan mereka berkata,) orang-orang musyrik (\"Mengapa tidak) tidakkah (ia datang kepada kami) yakni Nabi Muhammad (dengan membawa bukti dari Rabbnya?\") sesuai dengan apa yang diminta mereka. (Dan apakah belum datang kepada mereka) dapat dibaca Ta-tihim dan Ya-tihim (bukti yang nyata) yakni penjelasan (dari apa yang tersebut di dalam kitab-kitab yang terdahulu?) yang kesemuanya disebutkan oleh Alquran, yaitu mengenai berita umat-umat terdahulu yang telah dibinasakan disebabkan mereka mendustakan para Rasul.",[["وَقَالُوا۟","And they say"],["لَوْلَا","Why not"],["يَأْتِينَا","he brings us"],["بِـَٔايَةٍۢ","a sign"],["مِّن","from"],["رَّبِّهِۦٓ ۚ","his Lord"],["أَوَلَمْ","Has not"],["تَأْتِهِم","come to them"],["بَيِّنَةُ","evidence"],["مَا","(of) what"],["فِى","(was) in"],["ٱلصُّحُفِ","the Scriptures"],["ٱلْأُولَىٰ","the former"]]],"2482":["(Dan sekiranya Kami binasakan mereka dengan suatu azab sebelum ia diutus) sebelum Rasulullah diutus (tentulah mereka berkata) di hari kiamat nanti, (\"Ya Rabb kami! Mengapa tidak) (Engkau utus seorang Rasul kepada kami, lalu kami mengikuti ayat-ayat Engkau) yang dibawa olehnya (sebelum kami menjadi hina) di hari kiamat (dan rendah?\") dijebloskan ke dalam neraka Jahanam.",[["وَلَوْ","And if"],["أَنَّآ","We"],["أَهْلَكْنَـٰهُم","(had) destroyed them"],["بِعَذَابٍۢ","with a punishment"],["مِّن","before him"],["قَبْلِهِۦ","before him"],["لَقَالُوا۟","surely they (would) have said"],["رَبَّنَا","Our Lord"],["لَوْلَآ","why not"],["أَرْسَلْتَ","You sent"],["إِلَيْنَا","to us"],["رَسُولًۭا","a Messenger"],["فَنَتَّبِعَ","so we (could) have followed"],["ءَايَـٰتِكَ","Your signs"],["مِن","before"],["قَبْلِ","before"],["أَن","[that]"],["نَّذِلَّ","we were humiliated"],["وَنَخْزَىٰ","and disgraced"]]],"2483":["(Katakanlah:) kepada mereka, (\"Masing-masing) di antara kami dan kalian (menanti) menunggu apa yang bakal terjadi padanya di hari kiamat itu (maka nantikanlah oleh kamu sekalian! Kelak kalian akan mengetahui) di hari kiamat itu (siapa yang menempuh jalan) yakni tuntunan (yang lurus) yang tidak menyimpang (dan siapa yang telah mendapat petunjuk\") sehingga selamat dari kesesatan, kami ataukah kalian?",[["قُلْ","Say"],["كُلٌّۭ","Each"],["مُّتَرَبِّصٌۭ","(is) waiting"],["فَتَرَبَّصُوا۟ ۖ","so await"],["فَسَتَعْلَمُونَ","Then you will know"],["مَنْ","who"],["أَصْحَـٰبُ","(are the) companions"],["ٱلصِّرَٰطِ","(of) the way"],["ٱلسَّوِىِّ","[the] even"],["وَمَنِ","and who"],["ٱهْتَدَىٰ","is guided"]]]});